        // Update Meal/Restaurant table
        if (typeof mealList !== 'undefined' && mealList.length > 0) {
            mealList.forEach(meal => {
                meal.childQty = childCount;
            });
            if (typeof updateMealTable === 'function') {
                updateMealTable();
            }
