    // Update hotel room counts based on adult+child count from header
    function updateHotelRoomCounts() {
        const adultCount = parseInt(document.getElementById('adultCountInput')?.value || 0);
        const childCount = parseInt(document.getElementById('childCountInput')?.value || 0);
        const totalPax = adultCount + childCount;
        
        if (totalPax <= 0) {
            return; // No need to update if no pax
        }
        
        // Update accommodation list
        if (typeof accommodationList !== 'undefined' && accommodationList.length > 0) {
            let updated = false;
            accommodationList.forEach((hotel, index) => {
                // Get adults per room (capacity of each room)
                const adultsPerRoom = parseInt(hotel.adultsPerRoom) || 2;
                const extraBed = parseInt(hotel.extraBed) || 0;
                const childWithoutBed = parseInt(hotel.childWithoutBed) || 0;
                
                // Calculate effective capacity per room (adults + extra beds + children without bed)
                const effectiveCapacityPerRoom = adultsPerRoom + extraBed + childWithoutBed;
                
                // Calculate minimum rooms needed: ceil(totalPax / effectiveCapacityPerRoom)
                const minRoomsNeeded = Math.ceil(totalPax / Math.max(effectiveCapacityPerRoom, 1));
                
                // Only update if current rooms are less than needed
                const currentRooms = parseInt(hotel.rooms) || 1;
                if (currentRooms < minRoomsNeeded) {
                    hotel.rooms = minRoomsNeeded;
                    updated = true;
                }
            });
            
            // Update accommodation table if any changes were made
            if (updated && typeof updateAccommodationTable === 'function') {
                updateAccommodationTable();
            }
        }
    }
    
    // Get total pax from header
    function getTotalPax() {
        const adults = parseInt(document.getElementById('adultCountInput')?.value || document.getElementById('adults')?.value || 2);
        const child = parseInt(document.getElementById('childCountInput')?.value || document.getElementById('child')?.value || 0);
        return adults + child;
    }
    
    // Function to scan all existing services and expand header dates accordingly
    function scanAndExpandHeaderDates() {
        const startInput = getHeaderStartInput();
        const endInput = getHeaderEndInput();
        console.log('=== Scanning all services to expand header dates ===');
        console.log('Current header dates BEFORE scan:');
        console.log('  Start:', startInput ? startInput.value : '');
        console.log('  End:', endInput ? endInput.value : '');
        
        let servicesFound = 0;
        
        // Check arrival/departure dates
        if (arrivalDepartureList && arrivalDepartureList.length > 0) {
            console.log('Found', arrivalDepartureList.length, 'arrival/departure entries');
            arrivalDepartureList.forEach((item, index) => {
                if (item.dateTime) {
                    console.log(`Arrival/Departure ${index + 1}:`, item.type, item.dateTime);
                    expandHeaderDatesIfNeeded(item.dateTime, true);
                    servicesFound++;
                }
            });
        } else {
            console.log('No arrival/departure entries found');
        }
        
        // Check accommodation dates
        if (accommodationList && accommodationList.length > 0) {
            console.log('Found', accommodationList.length, 'accommodation entries');
            accommodationList.forEach((hotel, index) => {
                console.log(`Accommodation ${index + 1}:`, hotel);
                if (hotel.checkIn) {
                    console.log(`  Check-In:`, hotel.checkIn);
                    expandHeaderDatesIfNeeded(hotel.checkIn, false);
                    servicesFound++;
                }
                if (hotel.checkOut) {
                    console.log(`  Check-Out:`, hotel.checkOut);
                    expandHeaderDatesIfNeeded(hotel.checkOut, false);
                    servicesFound++;
                }
            });
        } else {
            console.log('No accommodation entries found');
        }
        
        // Check tour dates
        if (tourList && tourList.length > 0) {
            console.log('Found', tourList.length, 'tour entries');
            tourList.forEach((tour, index) => {
                if (tour.dateTime) {
                    console.log(`Tour ${index + 1}:`, tour.dateTime);
                    expandHeaderDatesIfNeeded(tour.dateTime, true);
                    servicesFound++;
                }
            });
        } else {
            console.log('No tour entries found');
        }
        
        // Check meal dates
        if (mealList && mealList.length > 0) {
            console.log('Found', mealList.length, 'meal entries');
            mealList.forEach((meal, index) => {
                if (meal.dateTime) {
                    console.log(`Meal ${index + 1}:`, meal.dateTime);
                    expandHeaderDatesIfNeeded(meal.dateTime, true);
                    servicesFound++;
                }
            });
        } else {
            console.log('No meal entries found');
        }
        
        // Check transfer dates
        if (transferList && transferList.length > 0) {
            console.log('Found', transferList.length, 'transfer entries');
            transferList.forEach((transfer, index) => {
                if (transfer.dateTime) {
                    console.log(`Transfer ${index + 1}:`, transfer.dateTime);
                    expandHeaderDatesIfNeeded(transfer.dateTime, true);
                    servicesFound++;
                }
            });
        } else {
            console.log('No transfer entries found');
        }
        
        // Check guide dates
        if (guideList && guideList.length > 0) {
            console.log('Found', guideList.length, 'guide entries');
            guideList.forEach((guide, index) => {
                if (guide.dateTime) {
                    console.log(`Guide ${index + 1}:`, guide.dateTime);
                    expandHeaderDatesIfNeeded(guide.dateTime, true);
                    servicesFound++;
                }
            });
        } else {
            console.log('No guide entries found');
        }
        
        console.log('=== Scan complete ===');
        console.log('Total services with dates found:', servicesFound);
        console.log('Current header dates AFTER scan:');
        console.log('  Start:', startInput ? startInput.value : '');
        console.log('  End:', endInput ? endInput.value : '');
        
        // Update the date display elements after scanning
        updateHeaderDisplays();
    }
    
    // Function to load existing orders from backend into JavaScript arrays (FRESH JSON FORMAT)
    function loadExistingOrdersIntoArrays() {
        console.log('=== Loading existing orders from backend into arrays (Fresh JSON format) ===');
        
        if (!window.existingOrders || window.existingOrders.length === 0) {
            console.log('No existing orders to load');
            return;
        }
        
        console.log('Total orders to process:', window.existingOrders.length);
        
        // Clear all arrays to start fresh
        accommodationList = [];
        arrivalDepartureList = [];
        tourList = [];
        guideList = [];
        transferList = [];
        mealList = [];
        miscList = [];
        
        // Group orders by service type
        const ordersByType = {
            accommodation: [],
            entry_port: [],
            exit_port: [],
            attraction: [],
            guide: [],
            local_transport: [],
            restaurant: [],
            miscellaneous: []
        };
        
        window.existingOrders.forEach(order => {
            const serviceType = order.service_type || order.travel_type || order.item_type || '';
            
            if (serviceType === 'accommodation' || serviceType === 'hotel') {
                ordersByType.accommodation.push(order);
            } else if (serviceType === 'entry_port') {
                ordersByType.entry_port.push(order);
            } else if (serviceType === 'exit_port') {
                ordersByType.exit_port.push(order);
            } else if (serviceType === 'attraction' || serviceType === 'tour') {
                ordersByType.attraction.push(order);
            } else if (serviceType === 'guide') {
                ordersByType.guide.push(order);
            } else if (serviceType === 'local_transport' || serviceType === 'transfer') {
                ordersByType.local_transport.push(order);
            } else if (serviceType === 'restaurant' || serviceType === 'meal') {
                ordersByType.restaurant.push(order);
            } else if (serviceType === 'miscellaneous' || serviceType === 'misc') {
                ordersByType.miscellaneous.push(order);
            }
        });
        
        console.log('Orders grouped by type:', {
            accommodation: ordersByType.accommodation.length,
            entry_port: ordersByType.entry_port.length,
            exit_port: ordersByType.exit_port.length,
            attraction: ordersByType.attraction.length,
            guide: ordersByType.guide.length,
            local_transport: ordersByType.local_transport.length,
            restaurant: ordersByType.restaurant.length,
            miscellaneous: ordersByType.miscellaneous.length
        });
        
        // Load accommodations
        ordersByType.accommodation.forEach((order, idx) => {
            try {
                // Calculate nights from dates
                const checkInDate = order.check_in_date || order.checkIn || '';
                const checkOutDate = order.check_out_date || order.checkOut || '';
                let nights = 1;
                if (checkInDate && checkOutDate) {
                    const checkIn = new Date(checkInDate);
                    const checkOut = new Date(checkOutDate);
                    if (checkOut > checkIn) {
                        nights = Math.ceil((checkOut - checkIn) / (1000 * 60 * 60 * 24));
                    }
                }
                
                // Get prices first to determine checkbox states
                const extraBedPriceVal = parseFloat(order.extra_bed_price || order.extraBedPrice || 0);
                const cwbPriceVal = parseFloat(order.cwb_price || order.cwbPrice || order.child_with_bed_price || order.child_with_bed || 0);
                const cnbPriceVal = parseFloat(order.cnb_price || order.cnbPrice || order.child_without_bed_price || order.child_without_bed || 0);
                const infantPriceVal = parseFloat(order.infant_price || order.infantPrice || order.baby_cot_price || order.babyCotPrice || 0);
                
                const hotelData = {
                    id: generateId('accommodation'),
                    orderId: order.id || order.order_id,
                    bookingId: order.booking_id,
                    hotelId: order.hotel_id || order.hotel_unique_id,
                    hotelName: order.hotel_name || '',
                    roomType: order.room_type || '',
                    bedType: order.bed_type || '',
                    bedId: order.bed_id || '',
                    rooms: parseInt(order.number_of_rooms || order.rooms || 1),
                    checkIn: checkInDate,
                    checkOut: checkOutDate,
                    nights: nights,
                    mealPlan: order.meal_plan || order.mealPlan || 'room only',
                    cost: parseFloat(order.cost || 0),
                    sell: parseFloat(order.price || order.sell || 0),
                    destination: order.destination || order.city || (order.hotelDetails && order.hotelDetails.location ? order.hotelDetails.location : '') || '',
                    adultsPerRoom: parseInt(order.adults_per_room || order.adultsPerRoom || 2, 10) || 2,
                    headCount: parseInt(order.head_count || 0, 10) || null,
                    maxOccupancy: parseInt(order.max_occupancy || 2),
                    // Extra bed and child pricing
                    extraBedPrice: extraBedPriceVal,
                    cwbPrice: cwbPriceVal,
                    cnbPrice: cnbPriceVal,
                    infantPrice: infantPriceVal,
                    // Checkbox states - only true if explicitly set (NOT based on price > 0)
                    hasExtraBed: order.has_extra_bed === true || order.has_extra_bed === 1 || order.hasExtraBed === true,
                    hasCwb: order.has_cwb === true || order.has_cwb === 1 || order.hasCwb === true,
                    hasCnb: order.has_cnb === true || order.has_cnb === 1 || order.hasCnb === true,
                    hasInfant: order.has_infant === true || order.has_infant === 1 || order.hasInfant === true,
                    supplement: order.supplement || false,
