                    console.log('Room price fields:', {
                        weekday_price: hotel.rooms[0].weekday_price,
                        weekend_price: hotel.rooms[0].weekend_price,
                        double_weekday_price: hotel.rooms[0].double_weekday_price,
                        double_weekend_price: hotel.rooms[0].double_weekend_price,
                        breakfast_price: hotel.rooms[0].breakfast_price,
                        lunch_price: hotel.rooms[0].lunch_price,
                        dinner_price: hotel.rooms[0].dinner_price
                    });
                }
                
                const option = document.createElement('option');
                option.value = `hotel_${hotel.id}`;
                option.setAttribute('data-hotel-name', hotel.name);
                option.setAttribute('data-type', 'hotel');
                option.setAttribute('data-hotel-unique-id', hotel.hotel_unique_id || hotel.id);
                option.setAttribute('data-zone-id', hotel.zone_id || '');
                option.setAttribute('data-city', hotel.city || '');
                option.setAttribute('data-country', hotel.country || '');
                // Ensure all room properties are preserved when stringifying
                const hotelData = {
                    id: hotel.id, // Database ID
                    hotel_unique_id: hotel.hotel_unique_id || hotel.id, // Unique ID for API calls
                    name: hotel.name,
                    rooms: hotel.rooms ? hotel.rooms.map(room => ({
                        ...room,
                        // Explicitly preserve price fields
                        weekday_price: room.weekday_price,
                        weekend_price: room.weekend_price,
                        double_weekday_price: room.double_weekday_price,
                        double_weekend_price: room.double_weekend_price,
                        breakfast_price: room.breakfast_price,
                        lunch_price: room.lunch_price,
                        dinner_price: room.dinner_price,
                        child_breakfast_price: room.child_breakfast_price,
                        child_lunch_price: room.child_lunch_price,
                        child_dinner_price: room.child_dinner_price,
                        extra_bed_price: room.extra_bed_price,
                        // Child with bed and child without bed prices from rooms table
                        child_with_bed: room.child_with_bed,
                        child_without_bed: room.child_without_bed,
                        breakfast_included: room.breakfast_included,
                        max_occupancy: room.max_occupancy,
                        room_type: room.room_type,
                        bed_types: room.bed_types
                    })) : [],
                    weekend_days: hotel.weekend_days || hotel.weekend || hotel.weekendDays || [],
                    rates: hotel.rates || [] // Include rates for blackout/fair date calculations
                };
                option.setAttribute('data-hotel-data', JSON.stringify(hotelData));
                option.textContent = hotel.name;
                hotelSelect.appendChild(option);
            });
            
            hotelSelect.disabled = false;
            console.log('Hotels loaded successfully. Total:', data.hotels.length);
            
            // Auto-select hotel: first try default hotel, then first hotel in ascending order
            if (data.hotels.length > 0) {
                let selectedHotelId = null;
                
                // Check if default hotel value exists
                if (typeof window.defaultValues !== 'undefined' && window.defaultValues.hotel) {
                    console.log('Checking for default hotel:', window.defaultValues.hotel);
                    
                    // Try to find default hotel in the dropdown
                    // Default hotel value might be in format "hotel_${id}" or just the id
                    const defaultHotelOption = Array.from(hotelSelect.options).find(option => {
                        if (option.value === '' || option.value === '-- Select Hotel --') return false;
                        // Match by value (hotel_${id}) or by hotel id
                        return option.value === window.defaultValues.hotel || 
                               option.value === `hotel_${window.defaultValues.hotel}` ||
                               option.getAttribute('data-hotel-unique-id') == window.defaultValues.hotel ||
                               option.value.replace('hotel_', '') == window.defaultValues.hotel;
                    });
                    
                    if (defaultHotelOption) {
                        selectedHotelId = defaultHotelOption.value;
                        console.log('Found and selected default hotel:', defaultHotelOption.textContent, selectedHotelId);
                    } else {
                        console.log('Default hotel not found in dropdown, will select first hotel');
                    }
                }
                
                // If no default hotel found or no default value, select first hotel (already sorted ascending)
                if (!selectedHotelId) {
                    selectedHotelId = `hotel_${data.hotels[0].id}`;
                    console.log('Selected first hotel (ascending order):', data.hotels[0].name, selectedHotelId);
                }
                
                // Set the selected hotel
                hotelSelect.value = selectedHotelId;
                
                // Trigger the loadRoomTypes function to show room combinations
                if (typeof loadRoomTypes === 'function') {
                    loadRoomTypes();
                }
            }
        })
        .catch(error => {
            console.error('Error loading hotels:', error);
            hotelSelect.innerHTML = '<option value="">-- Error loading hotels --</option>';
            alert('Error loading hotels. Please try again.');
        });
    }

