        if (totalPax > maxTotalOccupancy) {
            alert(`Total pax (${totalPax}) exceeds maximum room capacity (${maxTotalOccupancy}). Please adjust rooms or pax.`);
            return;
        }

        if (editingHotelId !== null) {
