                    checkIn: checkIn,
                    checkOut: checkOut,
                    nights: nights,
                    rooms: rooms,
                    adultsPerRoom: adultsPerRoom,
                    extraBed: extraBed,
                    childWithoutBed: childWithoutBed,
                    mealPlan: mealPlan,
                    supplement: '',
                    roomPrice: roomPrice
                };
            }
        } else {
            // Add new hotel
            const hotel = {
                id: generateId('hotel'), // Temporary ID
                hotelId: hotelId,
                hotelName: hotelName,
                destination: destination,
                roomId: roomId,
                roomType: roomType,
