                maxOccupancy: maxOccupancy,
                checkIn: checkIn,
                checkOut: checkOut,
                nights: nights,
                rooms: rooms,
                adultsPerRoom: adultsPerRoom,
                extraBed: extraBed,
                childWithoutBed: childWithoutBed,
                mealPlan: mealPlan,
                supplement: '',
                roomPrice: roomPrice
            };
            selectedHotelsTemp.push(hotel);
        }

        updateSelectedHotelsList();
        resetHotelForm();
    }

    // Update the selected hotels list in modal
    function updateSelectedHotelsList() {
        const tbody = document.getElementById('selectedHotelsList');
        const noMessage = document.getElementById('noHotelsMessage');
        
        if (selectedHotelsTemp.length === 0) {
            tbody.innerHTML = '';
            noMessage.style.display = 'block';
            return;
        }

        noMessage.style.display = 'none';
        
        // Group hotels by hotel name, room type, bed type, and dates
        const groupedHotels = {};
        selectedHotelsTemp.forEach(hotel => {
            const key = `${hotel.hotelName}|${hotel.roomType}|${hotel.bedType}|${hotel.checkIn}|${hotel.checkOut}`;
            if (!groupedHotels[key]) {
                groupedHotels[key] = {
                    ...hotel,
                    ids: [hotel.id],
                    totalRooms: parseInt(hotel.rooms)
                };
            } else {
                groupedHotels[key].ids.push(hotel.id);
                groupedHotels[key].totalRooms += parseInt(hotel.rooms);
            }
        });
        
        // Convert to array and limit to 4 for display
        const displayHotels = Object.values(groupedHotels).slice(0, 4);
        const hasMore = Object.keys(groupedHotels).length > 4;
        
        tbody.innerHTML = displayHotels.map(hotel => `
            <tr>
                <td>
                    ${hotel.hotelName}<br>
                    <small class="text-muted">${hotel.roomType} | ${hotel.bedType}</small><br>
                    <small class="text-primary">Avg. Price/Night: ${parseFloat(hotel.roomPrice || 0).toFixed(2)} | Per head: ${hotel.adultsPerRoom + hotel.extraBed + hotel.childWithoutBed > 0 ? (parseFloat(hotel.roomPrice || 0)/(hotel.adultsPerRoom + hotel.extraBed + hotel.childWithoutBed)).toFixed(2) : parseFloat(hotel.roomPrice || 0).toFixed(2)}</small>
                </td>
                <td style="white-space: nowrap; font-size: 9px;">
                    ${formatDate(hotel.checkIn)} - ${formatDate(hotel.checkOut)}<br>
                    <small class="text-muted">${hotel.nights} nights</small>
                </td>
                <td style="text-align: center;">${hotel.totalRooms}</td>
                <td>
                    ${hotel.ids.map(id => `
                        <button type="button" class="btn btn-xs btn-warning me-1" onclick="editHotelFromTempList(${id})" title="Edit">
                            <i class="ri-edit-line"></i>
                        </button>
                        <button type="button" class="btn btn-xs btn-danger" onclick="removeFromTempList(${id})" title="Delete">
                            <i class="ri-delete-bin-line"></i>
                        </button>
                    `).join('<br>')}
                </td>
            </tr>
        `).join('') + (hasMore ? `<tr><td colspan="4" class="text-center text-muted" style="font-size: 9px;">... ${Object.keys(groupedHotels).length - 4} more hotel(s)</td></tr>` : '');
    }

    // Format date for display
    function formatDate(dateString) {
        const date = new Date(dateString);
        const day = String(date.getDate()).padStart(2, '0');
        const month = date.toLocaleString('default', { month: 'short' });
        const year = String(date.getFullYear()).slice(-2);
        return `${day} ${month} '${year}`;
    }

    // Edit hotel from temporary list
    function editHotelFromTempList(id) {
        const hotel = selectedHotelsTemp.find(h => h.id === id);
        if (!hotel) return;

        // Populate form with hotel data
        document.getElementById('hotelDestination').value = hotel.destination;
        document.getElementById('hotelSelect').value = hotel.hotelId;
        
        // Load room types then set values
        loadRoomTypes();
        setTimeout(() => {
            document.getElementById('roomType').value = hotel.roomType;
            loadBedTypes();
            setTimeout(() => {
                document.getElementById('bedType').value = hotel.bedType;
                updatePricing();
            }, 100);
        }, 100);
        
        document.getElementById('checkInDate').value = hotel.checkIn;
        document.getElementById('checkOutDate').value = hotel.checkOut;
        document.getElementById('numNights').value = hotel.nights;
        document.getElementById('numRooms').value = hotel.rooms;
        document.getElementById('adultsPerRoom').value = hotel.adultsPerRoom;
        document.getElementById('extraBed').value = hotel.extraBed;
        document.getElementById('childWithoutBed').value = hotel.childWithoutBed;
        // document.getElementById('mealPlan').value = hotel.mealPlan;

        // Set editing mode
        editingHotelId = id;
        document.getElementById('addButtonText').textContent = 'Update';
    }

    // Remove hotel from temporary list
    function removeFromTempList(id) {
        selectedHotelsTemp = selectedHotelsTemp.filter(hotel => hotel.id !== id);
        updateSelectedHotelsList();
    }

    // Save arrival/departure only (without accommodation)
    // Live preview while editing a standalone arrival/departure row (outside hotel save flow)
    async function syncStandaloneArrDepPreview() {
        const index = window.editingArrivalDepartureIndex;
        if (index === null || index === undefined) return;
        const item = arrivalDepartureList[index];
        if (!item) return;
        const dmcId = '{{ $dmc_id ?? "" }}';

        function findXferIdx(portItem) {
            if (portItem.transferId) {
                const byId = transferList.findIndex(t => String(t.id) === String(portItem.transferId));
                if (byId !== -1) return byId;
            }
            if (portItem.id) {
                const src = (portItem.type === 'Arrival' || portItem.type === 'arrival') ? 'arrival' : 'departure';
                const bySrc = transferList.findIndex(t =>
                    String(t.sourceId) === String(portItem.id) &&
                    String(t.sourceType || '').toLowerCase() === src
                );
                if (bySrc !== -1) return bySrc;
            }
            return -1;
        }

        const isArr = item.type === 'Arrival' || item.type === 'arrival';
        if (isArr) {
            const hasXfer = document.getElementById('arrivalTransfer')?.checked;
            const xferType = document.getElementById('arrivalTransferType')?.value || 'S';
            const vSel = document.getElementById('arrivalVehicleType');
            const vehicleId = vSel?.value || '';
            const vOpt = vSel?.selectedOptions?.[0];
            const vehicleName = vOpt?.text || '';
            const vehicleType = vOpt?.getAttribute('data-type') || '';
            const adults = parseInt(document.getElementById('arrivalAdults')?.value || '2', 10);
            const child = parseInt(document.getElementById('arrivalChild')?.value || '0', 10);
            const portName = document.getElementById('arrivalPort')?.selectedOptions?.[0]?.text || item.portName || '';
            const destSel = document.getElementById('arrivalDestination');
            const destId = destSel?.value || '';
            const destName = destSel?.selectedOptions?.[0]?.getAttribute('data-name') || '';
            const destType = destSel?.selectedOptions?.[0]?.getAttribute('data-type') || 'hotel';
            const portId = document.getElementById('arrivalPort')?.value || '';
            let actualDestId = destId;
            if (destType === 'hotel') {
                const huId = destSel?.selectedOptions?.[0]?.getAttribute('data-hotel-unique-id');
                if (huId) actualDestId = huId;
            }
            const cost = parseFloat(document.getElementById('arrivalCost')?.value || 0);
            const sell = parseFloat(document.getElementById('arrivalSell')?.value || 0);
            const foc = document.getElementById('arrivalFocServiceDiscount')?.checked === true;
            const dt = document.getElementById('arrivalDateTime')?.value || item.dateTime;

            Object.assign(item, {
                vehicleId, vehicleType, vehicleName, transferType: xferType, hasTransfer: !!hasXfer,
                adultsQty: adults, childQty: child, cost, sell, focServiceDiscount: foc, dateTime: dt
            });

            const xi = findXferIdx(item);
            if (hasXfer && vehicleId && xi !== -1) {
                transferList[xi] = {
                    ...transferList[xi],
                    vehicleId, vehicleType, vehicleName,
                    type: xferType, transferType: xferType,
                    adults, child, cost, sell,
                    destination: destName ? `Arrival: ${portName} → ${destName}` : `Arrival: ${portName}`,
                    focServiceDiscount: foc, dateTime: dt
