    // Load attractions by destination
    function loadAttractionsByDestination(onLoadedCallback) {
        const destination = document.getElementById('tourDestination').value;
        const tbody = document.getElementById('attractionsTableBody');
        
        if (!destination) {
            tbody.innerHTML = '<tr><td colspan="16" class="text-center text-muted" style="padding: 20px;">Please select a destination to load attractions</td></tr>';
            return;
        }
        
        // Show loading state
        tbody.innerHTML = '<tr><td colspan="16" class="text-center" style="padding: 20px;"><i class="ri-loader-4-line ri-spin"></i> Loading attractions...</td></tr>';
        
        // Make AJAX call to get attractions by destination
        console.log('Loading attractions for destination:', destination);
        fetch(`{{ route('enquiry-form-pro.get-attractions') }}?destination=${encodeURIComponent(destination)}`)
            .then(response => {
                console.log('Attractions API response status:', response.status);
                return response.json();
            })
            .then(data => {
                console.log('Attractions API response data:', data);
                console.log('Attractions count:', data.count);
                console.log('DMC ID:', data.dmc_id);
                
                if (data.success && data.attractions.length > 0) {
                    // Get header values for auto-fill
                    const headerValues = getHeaderValues();
                    
                    // Build table rows - one row per ticket
                    let html = '';
                    data.attractions.forEach(attr => {
                        console.log('Attraction:', attr.name, 'attraction_type:', attr.attraction_type, 'Tickets:', attr.tickets);
                        
                        // Determine attraction type and label
                        // attraction_type: 1 = Tour Sites, 2 = Attraction
                        // Parse as integer to handle both string and number values
                        const attractionType = parseInt(attr.attraction_type) || 1;
                        const isAttraction = (attractionType === 2);
