                }
                
                // Fetch zone price and calculate transfer price
                const dmcId = '{{ $dmc_id ?? "" }}';
                let transferCost = 0;
                let transferSell = 0;
                let zonePrice = { private_price: 0, shared_price: 0 };
                
                if (vehicleId && pickupId && dropoffId && dmcId) {
                    try {
                        zonePrice = await fetchZonePrice(
                            vehicleId,
                            pickupId,
                            pickupType,
                            dropoffId,
                            dropoffType,
                            dmcId
                        );
                        
                        // Calculate prices using zone price
                        const prices = calculateTransferPrice(zonePrice, transferType === 'P' ? 'Private' : 'Shared', transferWay, adultsQty, childQty);
                        transferCost = prices.cost || 0;
                        transferSell = prices.sell || 0;
                    } catch (error) {
                        console.error('Error fetching zone price for attraction transfer:', error);
                    }
                }
                
                // Fallback: if new price is 0 but the old transfer had a price, preserve it
                if (transferCost === 0 && oldTransferCost > 0) {
                    transferCost = oldTransferCost;
                    if (oldTransferForPrice) {
                        zonePrice.private_price = parseFloat(oldTransferForPrice.zonePrivatePrice) || 0;
                        zonePrice.shared_price = parseFloat(oldTransferForPrice.zoneSharedPrice) || 0;
                    }
                    console.log('Using existing attraction transfer cost as fallback:', transferCost);
                }
                if (transferSell === 0 && oldTransferSell > 0) {
                    transferSell = oldTransferSell;
                    console.log('Using existing attraction transfer sell as fallback:', transferSell);
                }
                
                transferInfo = {
                    id: transferId,
                    type: transferType === 'P' ? 'P' : 'S',
                    way: transferWay || 'both-way',
                    vehicleId: vehicleId,
                    vehicleName: vehicleName,
                    vehicleType: vehicleType,
                    capacity: vehicleCapacity,
                    cost: transferCost,
                    sell: transferSell,
                    service: `${pickupName} / ${dropoffName}`,
                    attractionName: attractionName,
                    destination: destinationName,
                    destinationId: transferDestination, // Store destination ID for reliable matching in edit
                    destinationType: destinationType,
                    pickup: pickupName,
                    dropoff: dropoffName,
                    isDestinationPickup: isDestinationPickup,
                    dateTime: dateTime,
                    adults: adultsQty,
                    child: childQty,
                    taxIncluded: true,
                    transportMode: 'local', // Mark as local transfer for correct calculation
                    isStandalone: false,
                    sourceType: 'tour',
                    sourceId: tourId,
                    zonePrivatePrice: zonePrice.private_price,
                    zoneSharedPrice: zonePrice.shared_price
                };
                
                transferList.push(transferInfo);
            }
            
            // Get guide info if selected
            let guideInfo = null;
            let guideName = '';
            let guideLanguages = '';
            let guideEntryId = null;
            
            if (guideChecked && guideId) {
                const guideOption = guideSelect.options[guideSelect.selectedIndex];
                guideName = guideOption.getAttribute('data-name') || guideOption.text;
                guideLanguages = guideOption.getAttribute('data-languages') || '';
                const priceAttr = guideOption.getAttribute('data-twelve-hour-price') || '0';
                const defaultPrice = parseFloat(priceAttr) || 0;
                const guideQuantity = parseInt(row.querySelector('.attraction-guide-qty')?.value || '1') || 1;
                
                console.log('Creating linked guide:', {
                    guideId: guideId,
                    guideName: guideName,
                    priceAttr: priceAttr,
                    defaultPrice: defaultPrice,
                    adultsQty: adultsQty,
                    childQty: childQty,
                    guideQuantity: guideQuantity
                });
                
                guideInfo = {
                    guide_id: guideId,
                    name: guideName,
                    languages: guideLanguages
                };
                
                // Guide price is fixed for 12 hours, not dependent on pax
                // Use the 12-hour price directly without multiplying by pax
                const adultCost = defaultPrice;
                const adultSell = defaultPrice;
                const childCost = defaultPrice; // Same price for children
                const childSell = defaultPrice; // Same price for children
                
                // Total cost and sell - guide price is fixed, not per person
                const totalCost = defaultPrice; // Fixed price for 12 hours, not multiplied by pax
                const totalSell = defaultPrice; // Fixed price for 12 hours, not multiplied by pax
                
                // Add guide(s) to guide list based on quantity
                guideEntryId = generateId('guide');
                for (let gq = 0; gq < guideQuantity; gq++) {
                    const guideEntryId_q = gq === 0 ? guideEntryId : generateId('guide');
                    const guideEntry = {
                        id: guideEntryId_q,
                        guide_id: guideId,
                        dateTime: dateTime,
                        tourName: `${attractionName} - ${guideName}`,
                        languages: guideLanguages,
                        name: guideName,
                        hours: 12,
                        cost: totalCost,
                        sell: totalSell,
                        adultsQty: adultsQty,
                        childQty: childQty,
                        adultCost: adultCost,
                        adultSell: adultSell,
                        childCost: childCost,
                        childSell: childSell,
                        isStandalone: false,
                        sourceTourId: tourId,
                        focServiceDiscount: false
                    };
                    guideList.push(guideEntry);
                }
            }
            
            // Create guide_options object if guide is selected
            let guide_options = null;
            if (guideChecked && guideId && guideInfo) {
                const guideOption = guideSelect.options[guideSelect.selectedIndex];
                const guidePrice = parseFloat(guideOption.getAttribute('data-twelve-hour-price') || '0') || 0;
                
                guide_options = {
                    guideId: guideId,
                    guide_id: guideId,
                    guideName: guideName,
                    guide_name: guideName,
                    name: guideName,
                    languages: guideLanguages,
                    language: guideLanguages,
                    hours: 12,
                    adultsQty: adultsQty,
                    adults_qty: adultsQty,
                    adultQty: adultsQty,
                    adult_qty: adultsQty,
                    childQty: childQty,
                    child_qty: childQty,
                    childrenQty: childQty,
                    children_qty: childQty,
                    cost: guidePrice,
                    sell: guidePrice,
                    serviceType: 'Full Day',
                    service_type: 'Full Day',
                    tourActivity: `${attractionName} - ${guideName}`,
                    tour_activity: `${attractionName} - ${guideName}`
                };
            }
            
            // Create tour data using the pre-generated tourId
            const tourData = {
                id: tourId,
                destination: document.getElementById('tourDestination').value || 'Singapore',
                attractionId: attrId,
                attractionName: attractionName,
                ticketId: ticketId ? parseInt(ticketId) : 0,
                ticketName: ticketName,
                dateTime: dateTime,
                adultsQty: adultsQty,
                adultCost: adultCost,
                adultSell: adultSell,
                childQty: childQty,
                childCost: childCost,
                childSell: childSell,
                infantQty: infantQty,
                infantCost: infantCost,
                infantSell: infantSell,
                transferId: transferId,
                transferInfo: transferInfo,
                guideId: guideEntryId,
                guideInfo: guideInfo,
                guide_options: guide_options,
                guideRequired: guideChecked,
                focServiceDiscount: lineFocDisc
            };
            
            tourList.push(tourData);
            console.log('Pushed tour to list:', tourData.attractionName, tourData.dateTime);
        }
        
        console.log('Total tours in list after adding:', tourList.length);
        
        // Update tables
        updateTourTable();
        updateTransferTable();
        updateGuideTable();
        recalculateTotals();
        
        // Close modal
        const tourModal = bootstrap.Modal.getInstance(document.getElementById('tourModal'));
        if (tourModal) tourModal.hide();
        
