        document.getElementById('selectAllAttractions').checked = false;
        document.querySelectorAll('.attraction-checkbox').forEach(cb => cb.checked = false);
        
        // Update header dates AFTER modal closes (with delay to ensure modal animation completes)
        setTimeout(() => {
            console.log('About to call updateHeaderDatesIfNeeded with:', dateTime);
            updateHeaderDatesIfNeeded(dateTime);
            console.log('updateHeaderDatesIfNeeded completed after modal close');
        }, 300);
    }
    
    // Add another attraction (keep modal open)
    async function addAnotherAttraction() {
        // Save current selections without closing
        const selectedRows = document.querySelectorAll('.attraction-checkbox:checked');
        
        if (selectedRows.length === 0) {
            alert('Please select at least one attraction');
            return;
        }
        
        // Process selected attractions (same logic as saveAndCloseAttractions) - wait for it to complete
        await saveAndCloseAttractions();
        
        // Reopen the modal after save completes
        setTimeout(() => {
            const tourModal = new bootstrap.Modal(document.getElementById('tourModal'));
            tourModal.show();
        }, 300);
    }
    
    // Save tour
    function saveTour() {
        const destination = document.getElementById('tourDestination').value;
        const attractionSelect = document.getElementById('attractionSelect');
        const attractionId = attractionSelect.value;
        const attractionName = attractionSelect.options[attractionSelect.selectedIndex]?.text || '';
        const dateTime = document.getElementById('tourDateTime').value;
        const pte = document.getElementById('tourPTE').checked;
        const adultsQty = parseInt(document.getElementById('tourAdultsQty').value);
        const adultCost = parseFloat(document.getElementById('tourAdultCost').value);
        const adultSell = parseFloat(document.getElementById('tourAdultSell').value);
        const childQty = parseInt(document.getElementById('tourChildQty').value);
        const childCost = parseFloat(document.getElementById('tourChildCost').value);
        const childSell = parseFloat(document.getElementById('tourChildSell').value);
        
        console.log('Tour/Attraction DateTime:', dateTime);
        console.log('Attraction ID:', attractionId);
        console.log('Attraction Name:', attractionName);
        
        if (!attractionId || !dateTime) {
            alert('Please select attraction and date/time');
            return;
        }
        
        const isEditing = window.editingTourIndex !== undefined && window.editingTourIndex !== null;
        
        // Get transfer info
        const transferRequired = document.getElementById('transferRequired').value === 'yes';
        let transferInfo = null;
        let transferId = null;
        
        if (transferRequired) {
            const transferType = document.getElementById('transferType').value;
            const transferWay = document.getElementById('transferWay').value;
            const vehicleType = document.getElementById('vehicleType').value;
            const transferCost = parseFloat(document.getElementById('transferCost').value);
            const transferSell = parseFloat(document.getElementById('transferSell').value);
            
            transferId = generateId('transfer');
            transferInfo = {
                id: transferId,
                type: transferType,
                way: transferWay,
                vehicleType: vehicleType,
                cost: transferCost,
                sell: transferSell,
                destination: attractionName,
                dateTime: dateTime,
                adults: adultsQty,
                adultsQty: adultsQty,
                child: childQty,
                childQty: childQty,
                taxIncluded: true,
                transportMode: 'local',
                isStandalone: false,
                sourceType: 'attraction',
                sourceId: attractionId
            };
            
            // Add to transfer list
            transferList.push(transferInfo);
        }
        
        // Get guide info
        const guideRequired = document.getElementById('guideRequired').value === 'yes';
        let guideInfo = null;
        let guideId = null;
        
        if (guideRequired) {
            const language = document.getElementById('guideLanguage').value;
            const guideName = document.getElementById('guideName').value;
            const hours = parseFloat(document.getElementById('guideHours').value);
            const guideCost = parseFloat(document.getElementById('guideCost').value);
            const guideSell = parseFloat(document.getElementById('guideSell').value);
            
            guideId = generateId('guide');
            guideInfo = {
                id: guideId,
                language: language,
                name: guideName,
                hours: hours,
                cost: guideCost,
                sell: guideSell,
                tourName: attractionName,
                dateTime: dateTime,
                isStandalone: false
            };
            
            // Add to guide list
            guideList.push(guideInfo);
        }
        
    const tourData = {
        id: generateId('tour'),
            destination: destination,
            attractionId: attractionId,
            attractionName: attractionName,
            dateTime: dateTime,
            pte: pte,
            adultsQty: adultsQty,
            adultCost: adultCost,
            adultSell: adultSell,
            childQty: childQty,
            childCost: childCost,
            childSell: childSell,
            transferId: transferId,
            transferInfo: transferInfo,
            guideId: guideId,
            guideInfo: guideInfo
        };
        
        // Check if editing
        if (isEditing) {
            // Remove old transfer and guide if exists
            const oldTour = tourList[window.editingTourIndex];
            if (oldTour.transferId) {
                transferList = transferList.filter(t => t.id !== oldTour.transferId);
            }
            if (oldTour.guideId) {
                guideList = guideList.filter(g => g.id !== oldTour.guideId);
            }
            
            tourList[window.editingTourIndex] = tourData;
            window.editingTourIndex = null;
        } else {
            tourList.push(tourData);
        }
        
        // Update header dates
        if (isEditing) {
            // When editing, recalculate from all services to handle date changes properly
            recalculateHeaderDatesFromServices();
        } else {
            // When adding new, just expand if needed
            console.log('Calling expandHeaderDatesIfNeeded for TOUR...');
            expandHeaderDatesIfNeeded(dateTime, true);
        }
        
        updateTourTable();
        updateGuideTable();
        updateTransferTable();
        recalculateTotals();
        
        // Close modal
        const tourModal = bootstrap.Modal.getInstance(document.getElementById('tourModal'));
        if (tourModal) tourModal.hide();
    }
    
    // Update tour table
    function updateTourTable() {
        const tbody = document.getElementById('tourTableBody');
        const table = document.getElementById('tourTable');
        const emptyMessage = document.getElementById('emptyTourMessage');
        
        if (tourList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        tbody.innerHTML = tourList.map((tour, index) => {
            // Ensure dateTime has time component, if not add default time 10:00
            let dateTimeValue = tour.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T10:00';
            }
            
            return `
            <tr>
                <td><input type="checkbox" class="tour-checkbox" value="${tour.id}"></td>
                <td>
                    <input type="datetime-local" value="${dateTimeValue}" onchange="updateTourField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;">
                </td>
                <td>
                    <a href="javascript:void(0)" onclick="editTour(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">
                        ${tour.attractionName}
                    </a>
                </td>
                <td><input type="number" value="${tour.adultsQty}" onchange="updateTourField(${index}, 'adultsQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(tour.adultCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(tour.adultSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateTourField(${index}, 'adultSell', this.value)" step="1"></td>
                <td><input type="number" value="${tour.childQty}" onchange="updateTourField(${index}, 'childQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(tour.childCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(tour.childSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateTourField(${index}, 'childSell', this.value)" step="1"></td>
                <td style="text-align: center;"><input type="checkbox" ${tour.supplement ? 'checked' : ''} onchange="updateTourField(${index}, 'supplement', this.checked)"></td>
            </tr>
        `;
        }).join('');
    }
    
    function getTourFocDiscountState(tour) {
        if (tour.focServiceDiscount === true || tour.foc_service_discount === true) return true;
        if (tour.focServiceDiscount === false || tour.foc_service_discount === false) return false;
        if (tour.transferId && Array.isArray(transferList)) {
            const xfer = transferList.find(t => String(t.id) === String(tour.transferId));
            if (xfer && (xfer.focServiceDiscount === true || xfer.foc_service_discount === true)) return true;
        }
        return false;
    }

    function findAttractionRowForTour(tour) {
        const rows = Array.from(document.querySelectorAll('.attraction-row'));
        if (!rows.length || !tour) return null;

        const tourAttrId = String(tour.attractionId || tour.attraction_id || '').trim();
        const tourTicket = String(tour.ticketId != null && tour.ticketId !== '' ? tour.ticketId : '').trim();
        const tourTicketName = (tour.ticketName || tour.ticket_name || '').trim().toLowerCase();
        const tourAttrName = (tour.attractionName || tour.attraction_name || '').trim().toLowerCase();

        const sameAttrId = (row) => String(row.getAttribute('data-attraction-id') || '').trim() === tourAttrId;
        const sameTicketId = (row) => String(row.getAttribute('data-ticket-id') || '0').trim() === tourTicket;
        const sameTicketName = (row) => (row.getAttribute('data-ticket-name') || '').trim().toLowerCase() === tourTicketName;

        if (tourAttrId && tourTicket && tourTicket !== '0') {
            const strict = rows.find(row => sameAttrId(row) && sameTicketId(row));
            if (strict) return strict;
        }
        if (tourAttrId && tourTicketName) {
            const byName = rows.find(row => sameAttrId(row) && sameTicketName(row));
            if (byName) return byName;
        }
        if (tourAttrId) {
            const attrRows = rows.filter(sameAttrId);
            if (attrRows.length === 1) return attrRows[0];
            if (!tourTicket || tourTicket === '0') {
                const noTicketRow = attrRows.find(row => String(row.getAttribute('data-ticket-id') || '0') === '0');
                if (noTicketRow) return noTicketRow;
            }
            if (attrRows.length > 1) {
                const adultCost = parseFloat(tour.adultCost || tour.adultSell || 0);
                if (adultCost > 0) {
                    const byPrice = attrRows.find(row => {
                        const inp = row.querySelector('.attraction-adult-charge');
                        return inp && Math.abs(parseFloat(inp.value) - adultCost) < 0.01;
                    });
                    if (byPrice) return byPrice;
                }
            }
        }
        if (tourAttrName) {
            const byAttrName = rows.find(row => {
                const name = (row.getAttribute('data-attraction-name') || '').trim().toLowerCase();
                return name === tourAttrName;
            });
            if (byAttrName) return byAttrName;
        }
        return rows.find(row => String(row.getAttribute('data-attraction-id') || '') == tourAttrId) || null;
    }

    function populateAttractionRowFromTour(row, tour) {
        if (!row || !tour) return;

        document.querySelectorAll('.attraction-checkbox').forEach(cb => { cb.checked = false; });

        const checkbox = row.querySelector('.attraction-checkbox');
        if (checkbox) checkbox.checked = true;

        const adultQty = row.querySelector('.attraction-adult-qty');
        if (adultQty) adultQty.value = tour.adultsQty || 0;

        const adultCharge = row.querySelector('.attraction-adult-charge');
        if (adultCharge) adultCharge.value = `${parseFloat(String(tour.adultCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}`;

        const childQty = row.querySelector('.attraction-child-qty');
        if (childQty) childQty.value = tour.childQty || 0;

        const childCharge = row.querySelector('.attraction-child-charge');
        if (childCharge) childCharge.value = `${parseFloat(String(tour.childCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}`;

        const infantQty = row.querySelector('.attraction-infant-qty');
        if (infantQty) infantQty.value = tour.infantQty || 0;

        const infantCharge = row.querySelector('.attraction-infant-charge');
        if (infantCharge) infantCharge.value = `${parseFloat(String(tour.infantCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}`;

        const transferCheckbox = row.querySelector('.attraction-transfer-checkbox');
        const hasTransfer = !!(tour.transferInfo || tour.transferId);
        if (hasTransfer) {
            if (transferCheckbox) transferCheckbox.checked = true;
            const info = tour.transferInfo || {};
            if (info.destination || info.destinationId) {
                const transferDestSelect = row.querySelector('.attraction-transfer-destination');
                if (transferDestSelect) {
                    let matched = false;
                    if (info.destinationId) {
                        const optById = Array.from(transferDestSelect.options).find(o =>
                            String(o.value) === String(info.destinationId)
                        );
                        if (optById) {
                            transferDestSelect.value = optById.value;
                            matched = true;
                        }
                    }
                    if (!matched && info.destination) {
                        for (let i = 0; i < transferDestSelect.options.length; i++) {
                            const optionName = transferDestSelect.options[i].getAttribute('data-name');
                            if (optionName === info.destination) {
                                transferDestSelect.value = transferDestSelect.options[i].value;
                                break;
                            }
                        }
                    }
                }
            }
            const isPickupCheckbox = row.querySelector('.attraction-is-pickup');
            if (isPickupCheckbox) isPickupCheckbox.checked = info.isDestinationPickup || false;
            const vehicleTypeSelect = row.querySelector('.attraction-vehicle-type');
            if (vehicleTypeSelect && info.vehicleId) {
                vehicleTypeSelect.value = info.vehicleId;
                if (vehicleTypeSelect.value !== String(info.vehicleId)) {
                    const opt = Array.from(vehicleTypeSelect.options).find(o => String(o.value) === String(info.vehicleId));
                    if (opt) vehicleTypeSelect.value = opt.value;
                }
            }
            const waySelect = row.querySelector('.attraction-transfer-way');
            if (waySelect && info.way) waySelect.value = info.way;
            const typeSelect = row.querySelector('.attraction-transfer-type');
            if (typeSelect && info.type) typeSelect.value = info.type;
        } else if (transferCheckbox) {
            transferCheckbox.checked = false;
        }

        const guideCheckbox = row.querySelector('.attraction-guide-checkbox');
        if (tour.guideRequired || tour.guideInfo || tour.guideId) {
            if (guideCheckbox) guideCheckbox.checked = true;
            if (tour.guideInfo) {
                const guideSelect = row.querySelector('.attraction-guide-select');
                const guideId = tour.guideInfo.guide_id || tour.guideInfo.guideId;
                if (guideSelect && guideId) guideSelect.value = guideId;
            }
        } else if (guideCheckbox) {
            guideCheckbox.checked = false;
        }

        const focCb = row.querySelector('.attraction-foc-discount');
        if (focCb) focCb.checked = getTourFocDiscountState(tour);
    }

    function restoreTourModalFromTour(tour) {
        const targetRow = findAttractionRowForTour(tour);
        if (!targetRow) {
            console.warn('Could not find attraction row for tour:', tour);
            return;
        }
        const rowType = parseInt(targetRow.getAttribute('data-attraction-type')) || 1;
        const selectedFilterType = (rowType === 1) ? 'toursite' : 'attraction';
        const filterRadioId = selectedFilterType === 'toursite' ? 'filterTourSite' : 'filterAttraction';
        const filterRadio = document.getElementById(filterRadioId);
        if (filterRadio) filterRadio.checked = true;
        filterAttractionsByType(selectedFilterType);
        populateAttractionRowFromTour(targetRow, tour);
    }

    // Edit tour
    function editTour(index) {
        const tour = tourList[index];
        if (!tour) return;

        console.log('Editing tour:', tour);

        window.editingTourIndex = index;

        document.getElementById('tourDestination').value = tour.destination || '';

        let dateTimeValue = tour.dateTime || '';
        if (dateTimeValue && !dateTimeValue.includes('T')) {
            dateTimeValue = dateTimeValue + 'T09:00';
        }
        document.getElementById('tourDateTime').value = dateTimeValue;

        document.getElementById('tourModalTitleText').textContent = 'Edit Tour / Attraction';

        const tourModalEl = document.getElementById('tourModal');
        const tourModal = bootstrap.Modal.getInstance(tourModalEl) || new bootstrap.Modal(tourModalEl);
        tourModal.show();

        loadAttractionsByDestination(() => {
            restoreTourModalFromTour(tour);
        });
    }
    
    // Update tour field
    function updateTourField(index, field, value) {
        if (tourList[index]) {
            const tour = tourList[index];
            tour[field] = value;
            
            // If supplement is changed, do NOT sync with linked services
            if (field === 'supplement') {
                // Recalculate totals after supplement change
                recalculateTotals();
            }
            
            // If dateTime is changed, sync with linked transfer and guide
            if (field === 'dateTime' && value) {
                // Update linked transfer if exists
                if (tour.transferId) {
                    const transferIndex = transferList.findIndex(t => t.id === tour.transferId);
                    if (transferIndex !== -1) {
                        transferList[transferIndex].dateTime = value;
                        updateTransferTable();
                    }
                }
                
                // Update linked guide if exists
                if (tour.guideId) {
                    const guideIndex = guideList.findIndex(g => g.id === tour.guideId);
                    if (guideIndex !== -1) {
                        guideList[guideIndex].dateTime = value;
                        updateGuideTable();
                    }
                }
                
                // Expand header dates
                expandHeaderDatesIfNeeded(value, false);
            }
        }
    }
    
    // Toggle select all tours
    function toggleSelectAllTours() {
        const selectAll = document.getElementById('selectAllTours');
        const checkboxes = document.querySelectorAll('.tour-checkbox');
        checkboxes.forEach(cb => cb.checked = selectAll.checked);
    }
    
    // Remove selected tours
    function removeSelectedTours() {
        const checkboxes = document.querySelectorAll('.tour-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select tours to remove');
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        const existingIdsToRemove = idsToRemove.filter(id => {
            const item = tourList.find(t => String(t.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        const hasExistingItems = idsToRemove.some(id => {
            const item = tourList.find(t => String(t.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        
        const count = checkboxes.length;
        const itemLabel = count === 1 ? 'tour' : 'tours';
        showRemoveFormSelectionAlert(count, itemLabel, () => {
            const snapshotBefore = snapshotAllServiceState();
            tourList.forEach(tour => {
                if (idsToRemove.includes(String(tour.id))) {
                    if (tour.transferId) {
                        transferList = transferList.filter(t => String(t.id) !== String(tour.transferId));
                    }
                    if (tour.guideId) {
                        guideList = guideList.filter(g => String(g.id) !== String(tour.guideId));
                    }
                }
            });
            
            tourList = tourList.filter(tour => !idsToRemove.includes(String(tour.id)));
        
            updateTourTable();
            updateTransferTable();
            updateGuideTable();
            recalculateHeaderDatesFromServices();
            recalculateTotals();
            scheduleRemoveWithUndo({
                categoryKey: 'tours',
                serviceMessage: 'Tour service',
                existingIds: existingIdsToRemove,
                snapshotBefore
            });
        }, window.hasNegotiationHistory, hasExistingItems);
    }

    // ==================== GUIDE FUNCTIONS ====================
    
    // Open Guide Modal
    function openGuideModal() {
        // Reset destination select
        const destinationSelect = document.getElementById('guideDestination');
        if (destinationSelect) {
            destinationSelect.value = '';
        }
        
        // Reset location select to first attraction (default)
        const locationSelect = document.getElementById('guideLocation');
        if (locationSelect) {
            // Find the first option in the Attractions optgroup and select it
            const attractionsOptgroup = locationSelect.querySelector('optgroup[label="Attractions"]');
            if (attractionsOptgroup) {
                const firstAttraction = attractionsOptgroup.querySelector('option');
                if (firstAttraction) {
                    locationSelect.value = firstAttraction.value;
                }
            }
        }
        
        // Set default date with 10:00 AM time
        const guideDate = document.getElementById('guideDate');
        if (guideDate) {
            // Get date part from getDefaultServiceDate but use 10:00 AM as default time
            const defaultDate = getDefaultServiceDate();
            const datePart = defaultDate.split('T')[0];
            guideDate.value = `${datePart}T10:00`;
        }
        
        // Clear guides table
        const tbody = document.getElementById('guidesTableBody');
        if (tbody) {
            tbody.innerHTML = '<tr><td colspan="8" class="text-center text-muted" style="padding: 20px;">Please select a destination to load guides</td></tr>';
        }
        
        // Reset all checkboxes in the table
        const selectAllCheckbox = document.getElementById('selectAllGuides');
        if (selectAllCheckbox) {
            selectAllCheckbox.checked = false;
        }
        
        // Set date range constraints
        if (typeof updateAllServiceDateRanges === 'function') {
            updateAllServiceDateRanges();
        }
        
        // Auto-fill destination from header using autoFillModalFields
        autoFillModalFields('guide');
        
        const guideModal = new bootstrap.Modal(document.getElementById('guideModal'));
        guideModal.show();
    }
    
    // Load guides by destination
    function loadGuidesByDestination() {
        const destination = document.getElementById('guideDestination').value;
        const tbody = document.getElementById('guidesTableBody');
        
        if (!destination) {
            tbody.innerHTML = '<tr><td colspan="10" class="text-center text-muted" style="padding: 20px;">Please select a destination to load guides</td></tr>';
            return;
        }
        
        // Show loading state
        tbody.innerHTML = '<tr><td colspan="10" class="text-center" style="padding: 20px;"><i class="ri-loader-4-line ri-spin"></i> Loading guides...</td></tr>';
        
        console.log('Loading guides for destination:', destination);
        
        // Make AJAX call to get guides by destination
        fetch(`{{ route('enquiry-form-pro.get-guides') }}?destination=${encodeURIComponent(destination)}`)
            .then(response => {
                console.log('Response status:', response.status);
                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }
                return response.json();
            })
            .then(data => {
                console.log('Guides data received:', data);
                if (data.success && data.guides.length > 0) {
                    // Get header values for adult/child counts
                    const headerValues = getHeaderValues();
                    const defaultAdultQty = headerValues.adults || 0;
                    const defaultChildQty = headerValues.children || 0;
                    
                    // Build table rows
                    let html = '';
                    data.guides.forEach(guide => {
                        // Get languages as comma-separated string with proficiency
                        const languagesDisplay = guide.languages.map(l => `${l.language} (${l.proficiency})`).join(', ') || 'N/A';
                        // Get first language for saving (or all languages as comma-separated)
                        const languagesForSave = guide.languages.map(l => l.language).join(', ') || 'N/A';
                        
                        // Parse prices as numbers, ensuring they are valid
                        const twoHourPrice = parseFloat(guide.two_hour_price) || 0;
                        const fourHourPrice = parseFloat(guide.four_hour_price) || 0;
                        const sixHourPrice = parseFloat(guide.six_hour_price) || 0;
                        const eightHourPrice = parseFloat(guide.eight_hour_price) || 0;
                        const tenHourPrice = parseFloat(guide.ten_hour_price) || 0;
                        const twelveHourPrice = parseFloat(guide.twelve_hour_price) || parseFloat(guide.day_rate) || 0;
                        
                        // Ensure all prices are valid numbers (not NaN)
                        const validTwoHour = isNaN(twoHourPrice) ? 0 : twoHourPrice;
                        const validFourHour = isNaN(fourHourPrice) ? 0 : fourHourPrice;
                        const validSixHour = isNaN(sixHourPrice) ? 0 : sixHourPrice;
                        const validEightHour = isNaN(eightHourPrice) ? 0 : eightHourPrice;
                        const validTenHour = isNaN(tenHourPrice) ? 0 : tenHourPrice;
                        const validTwelveHour = isNaN(twelveHourPrice) ? 0 : twelveHourPrice;
                        
                        // Format the default sell price (12 hour price)
                        const defaultSellPrice = validTwelveHour > 0 ? validTwelveHour.toFixed(2) : '0.00';
                        
                        html += `
                            <tr class="guide-row" data-guide-id="${guide.guide_id}" data-guide-name="${guide.name}" data-guide-languages="${languagesForSave}">
                                <td style="padding: 2px 8px; text-align: center;">
                                    <input type="checkbox" class="guide-checkbox" data-guide-id="${guide.guide_id}">
                                </td>
                                <td style="padding: 2px 8px;">${guide.name}</td>
                                <td style="padding: 2px 8px;">
                                    <span class="guide-languages-display" style="font-size: 10px; color: #495057;">
                                        ${languagesDisplay}
                                    </span>
                                </td>
                                <td style="padding: 2px 8px; text-align: center;">
                                    <input type="number" class="form-control form-control-sm guide-quantity" data-guide-id="${guide.guide_id}" 
                                           value="1" step="1" min="1" max="99"
                                           style="font-size: 10px; padding: 2px 4px; text-align: center; width: 60px;">
                                </td>
                                <td style="padding: 2px 8px; text-align: center;">
                                    <input type="number" class="form-control form-control-sm guide-adult-qty" data-guide-id="${guide.guide_id}" 
                                           value="${defaultAdultQty}" step="1" min="0" max="${headerValues.adults || 99}"
                                           style="font-size: 10px; padding: 2px 4px; text-align: center; width: 70px;">
                                </td>
                                <td style="padding: 2px 8px; text-align: center;">
                                    <input type="number" class="form-control form-control-sm guide-child-qty" data-guide-id="${guide.guide_id}" 
                                           value="${defaultChildQty}" step="1" min="0" max="${headerValues.children || 99}"
                                           style="font-size: 10px; padding: 2px 4px; text-align: center; width: 70px;">
                                </td>
                                <td style="padding: 2px 8px; text-align: right;">
                                    <input type="text" class="form-control form-control-sm guide-cost" data-guide-id="${guide.guide_id}" 
                                           value="${defaultSellPrice}" readonly
                                           style="font-size: 10px; padding: 2px 4px; text-align: right; background-color: #f5f5f5;">
                                </td>
                                <td style="padding: 2px 8px; text-align: right;">
                                    <input type="number" class="form-control form-control-sm guide-sell" data-guide-id="${guide.guide_id}" 
                                           value="${defaultSellPrice}" step="1" min="0"
                                           style="font-size: 10px; padding: 2px 4px; text-align: right;">
                                </td>
                                <td style="padding: 2px 8px; text-align: center;" class="group-foc-service-discount-ui">
                                    <input type="checkbox" class="form-check-input guide-foc-discount" data-guide-id="${guide.guide_id}" title="FOC discount">
                                </td>
                            </tr>
                        `;
                    });
                    tbody.innerHTML = html;
                } else {
                    tbody.innerHTML = '<tr><td colspan="10" class="text-center text-muted" style="padding: 20px;">No guides found for this destination</td></tr>';
                }
            })
            .catch(error => {
                console.error('Error loading guides:', error);
                tbody.innerHTML = `<tr><td colspan="10" class="text-center text-danger" style="padding: 20px;">
                    Error loading guides: ${error.message}<br>
                    <small>Please check the browser console for more details.</small>
                </td></tr>`;
            });
    }
    
    // Update guide pricing based on hours selected
    function updateGuidePricing(guideId, twoHourPrice, fourHourPrice, sixHourPrice, eightHourPrice, tenHourPrice, twelveHourPrice) {
        const hoursSelect = document.querySelector(`.guide-hours[data-guide-id="${guideId}"]`);
        const costInput = document.querySelector(`.guide-cost[data-guide-id="${guideId}"]`);
        const sellInput = document.querySelector(`.guide-sell[data-guide-id="${guideId}"]`);
        
        if (!hoursSelect || !costInput || !sellInput) return;
        
        const hours = parseInt(hoursSelect.value);
        let price = 0;
        
        switch(hours) {
            case 2: price = parseFloat(twoHourPrice) || 0; break;
            case 4: price = parseFloat(fourHourPrice) || 0; break;
            case 6: price = parseFloat(sixHourPrice) || 0; break;
            case 8: price = parseFloat(eightHourPrice) || 0; break;
            case 10: price = parseFloat(tenHourPrice) || 0; break;
            case 12: price = parseFloat(twelveHourPrice) || 0; break;
            default: price = parseFloat(twelveHourPrice) || 0;
        }
        
        // Ensure price is a valid number
        if (isNaN(price) || price < 0) {
            price = 0;
        }
        
        const priceFormatted = price.toFixed(2);
        costInput.value = priceFormatted;
        
        // Only update sell price if it's currently empty or has a default/invalid value
        // This allows users to manually set sell price with commission markup
        const currentSellValue = parseFloat(sellInput.value);
        if (!sellInput.value || isNaN(currentSellValue) || currentSellValue === 0 || currentSellValue === 50 || currentSellValue === 30 || currentSellValue === 20) {
            sellInput.value = priceFormatted;
        }
    }
    
