    // Update guide table
    function updateGuideTable() {
        const tbody = document.getElementById('guideTableBody');
        const table = document.getElementById('guideTable');
        const emptyMessage = document.getElementById('emptyGuideMessage');
        
        if (guideList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        tbody.innerHTML = guideList.map((guide, index) => {
            // Ensure dateTime has time component, if not add default time 09:00
            let dateTimeValue = guide.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T09:00';
            }

            // Show checkbox for all guides (both standalone and linked)
            // Use guide.id as the value since that's the unique identifier
            const checkboxHtml = `<input type="checkbox" class="guide-checkbox" value="${guide.id}">`;
            
            // Date and time is now editable in guide table
            const dateHtml = `<input type="datetime-local" value="${dateTimeValue}" onchange="updateGuideField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;">`;

            // Determine supplement checkbox display - show checkbox for linked guides too
            const supplementCheckboxHtml = guide.isStandalone !== false
                ? `<input type="checkbox" ${guide.supplement ? 'checked' : ''} onchange="updateGuideSupplement(${index}, this.checked)">`
                : `<input type="checkbox" ${guide.supplement ? 'checked' : ''} onchange="updateGuideSupplement(${index}, this.checked)" style="opacity: 0.7;">`;

            // Make Tour/Activity clickable - opens guide modal for standalone, or tour modal for linked
            const tourActivityValue = guide.tourActivity || guide.tourName || guide.tour_activity || '-';
            const tourActivityHtml = `<a href="javascript:void(0)" onclick="editGuide(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">${tourActivityValue}</a>`;

            // Format languages for display - can be array or string
            let languagesDisplay = '';
            if (Array.isArray(guide.languages)) {
                languagesDisplay = guide.languages.join(', ');
            } else if (guide.languages) {
                languagesDisplay = guide.languages;
            } else if (guide.language) {
                languagesDisplay = guide.language;
            } else {
                languagesDisplay = '';
            }

            // Get guide name - check multiple possible field names
            const guideNameDisplay = guide.guideName || guide.name || guide.guide_name || '';

            return `
            <tr>
                <td>${checkboxHtml}</td>
                <td>${dateHtml}</td>
                <td>${tourActivityHtml}</td>
                <td>${languagesDisplay}</td>
                <td><input type="text" value="${guideNameDisplay}" onchange="updateGuideField(${index}, 'guideName', this.value)" style="width: 100px;"></td>
                <td><input type="number" value="${guide.adultsQty || guide.adults || 0}" onchange="updateGuideField(${index}, 'adultsQty', this.value)" step="1" min="0" max="99" style="width: 70px; text-align: center;"></td>
                <td><input type="number" value="${guide.childQty || guide.children || 0}" onchange="updateGuideField(${index}, 'childQty', this.value)" step="1" min="0" max="99" style="width: 70px; text-align: center;"></td>
                <td><input type="text" value="${guide.cost || 0}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${guide.sell || 0}" onchange="updateGuideField(${index}, 'sell', this.value)" step="1"></td>
                <td style="text-align: center;">${supplementCheckboxHtml}</td>
            </tr>
        `;
        }).join('');
    }
    
    // Edit guide - opens guide modal for standalone, or tour modal for linked guides
    function editGuide(index) {
        const guide = guideList[index];
        if (!guide) return;
        
        // If it's linked to a service, open the source modal instead
        if (guide.isStandalone === false) {
            // If linked to arrival/departure, open arrival/departure modal
            if (guide.linkedTo === 'arrival' || guide.linkedTo === 'Arrival') {
                // Find the arrival that has this guide
                const arrivalIndex = arrivalDepartureList.findIndex(item => 
                    (item.type === 'Arrival' || item.type === 'arrival') && (item.guideId === guide.id || item.id === guide.sourceId)
                );
                if (arrivalIndex !== -1) {
                    editArrivalDeparture(arrivalIndex);
                    return;
                }
            } else if (guide.linkedTo === 'departure' || guide.linkedTo === 'Departure') {
                // Find the departure that has this guide
                const departureIndex = arrivalDepartureList.findIndex(item => 
                    (item.type === 'Departure' || item.type === 'departure') && (item.guideId === guide.id || item.id === guide.sourceId)
                );
                if (departureIndex !== -1) {
                    editArrivalDeparture(departureIndex);
                    return;
                }
            }
            
            // If linked to a tour, open the tour modal instead
            const tourIndex = tourList.findIndex(tour => tour.guideId === guide.id || tour.guideId === guide.guide_id);
            if (tourIndex !== -1) {
                editTour(tourIndex);
                return;
            }
            
            // If linked to a meal/restaurant, find and edit the meal
            if (guide.linkedTo === 'restaurant') {
                // Try multiple matching strategies
                let mealIndex = mealList.findIndex(meal => meal.guideId === guide.id || meal.guideId === guide.guide_id);
                
                // Fallback: match by restaurant name if guide has it
                if (mealIndex === -1 && guide.restaurantName) {
                    mealIndex = mealList.findIndex(meal => meal.restaurantName === guide.restaurantName);
                }
                
                // Fallback: match by guideId field in guide_options
                if (mealIndex === -1 && guide.guideId) {
                    mealIndex = mealList.findIndex(meal => 
                        (meal.guide_options && meal.guide_options.guideId === guide.guideId) ||
                        (meal.guideInfo && meal.guideInfo.guideId === guide.guideId)
                    );
                }
                
                if (mealIndex !== -1) {
                    editMeal(mealIndex);
                    return;
                }
            }
            
            // If linked to local transfer, find and edit the transfer
            if (guide.linkedTo === 'local_transport' || guide.sourceType === 'transfer' || (guide.tourActivity && guide.tourActivity.includes('Local Transfer Guide'))) {
                // First, try using transferId if available (most direct link)
                if (guide.transferId) {
                    const transferIndex = transferList.findIndex(transfer => transfer.id === guide.transferId);
                    if (transferIndex !== -1) {
                        console.log('Found transfer for guide using transferId:', transferIndex, transferList[transferIndex]);
                        editTransfer(transferIndex);
                        return;
                    }
                }
                
                // Find the transfer that has this guide
                const transferIndex = transferList.findIndex(transfer => {
                    // Check if transfer has this guide's ID
                    if (transfer.guideId === guide.id) {
                        return true;
                    }
                    // Check if guide's sourceId matches transfer's id
                    if (guide.sourceId && transfer.id === guide.sourceId) {
                        return true;
                    }
                    // Check if guideInfo exists and matches
                    if (transfer.guideInfo && transfer.guideInfo.guideId === guide.guideId) {
                        return true;
                    }
                    // Check if transfer has guide_options with matching guideId
                    if (transfer.guideOptions && (transfer.guideOptions.guideId === guide.guideId || transfer.guideOptions.guide_id === guide.guide_id)) {
                        return true;
                    }
                    // Fallback: match by transport mode and check if guide was created from this transfer
                    if (transfer.transportMode === 'local' && guide.sourceId && transfer.id === guide.sourceId) {
                        return true;
                    }
                    return false;
                });
                if (transferIndex !== -1) {
                    console.log('Found transfer for guide, opening transfer modal:', transferIndex, transferList[transferIndex]);
                    editTransfer(transferIndex);
                    return;
                } else {
                    console.warn('Could not find transfer for guide:', {
                        guide: guide,
                        guideId: guide.id,
                        sourceId: guide.sourceId,
                        transferId: guide.transferId,
                        transferListLength: transferList.length,
                        transferList: transferList.map(t => ({ id: t.id, guideId: t.guideId, transportMode: t.transportMode }))
                    });
                }
            }
            
            // If we can't find the source, just open guide modal
            console.warn('Could not find source for linked guide, opening guide modal');
        }
        
        // For standalone guides, open the guide modal with data pre-filled
        window.editingGuideIndex = index;
        
        // Set destination
        const destinationSelect = document.getElementById('guideDestination');
        if (destinationSelect && guide.destination) {
            destinationSelect.value = guide.destination;
        }
        
        // Set location
        const locationSelect = document.getElementById('guideLocation');
        if (locationSelect && guide.locationId) {
            locationSelect.value = guide.locationId;
        }
        
        // Set date
        let dateTimeValue = guide.dateTime || '';
        if (dateTimeValue && !dateTimeValue.includes('T')) {
            dateTimeValue = dateTimeValue + 'T09:00';
        }
        const guideDate = document.getElementById('guideDate');
        if (guideDate) {
            guideDate.value = dateTimeValue.split('T')[0] || getDefaultServiceDate();
        }
        
        // Load guides for the destination
        loadGuidesByDestination();
        
        // Wait for guides to load, then select the guide
        setTimeout(() => {
            const guideRows = document.querySelectorAll('.guide-row');
            guideRows.forEach(row => {
                const guideId = row.getAttribute('data-guide-id');
                if (guideId == guide.guideId || guideId == guide.guide_id || guideId == guide.id) {
                    const checkbox = row.querySelector('.guide-checkbox');
                    if (checkbox) {
                        checkbox.checked = true;
                        const quantityInput = row.querySelector('.guide-quantity');
                        if (quantityInput) {
                            quantityInput.value = 1;
                        }
                        const adultQtyInput = row.querySelector('.guide-adult-qty');
                        if (adultQtyInput && guide.adultsQty !== undefined) {
                            adultQtyInput.value = guide.adultsQty;
                        }
                        const childQtyInput = row.querySelector('.guide-child-qty');
                        if (childQtyInput && guide.childQty !== undefined) {
                            childQtyInput.value = guide.childQty;
                        }
                        const gFoc = row.querySelector('.guide-foc-discount');
                        if (gFoc) gFoc.checked = !!(guide.focServiceDiscount || guide.foc_service_discount);
                    }
                }
            });
        }, 500);
        
        // Open the guide modal
        const guideModal = new bootstrap.Modal(document.getElementById('guideModal'));
        guideModal.show();
    }
    
    // Remove selected guides
    function removeSelectedGuides() {
        const checkboxes = document.querySelectorAll('.guide-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select guides to remove');
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        const existingIdsToRemove = idsToRemove.filter(id => {
            const item = guideList.find(g => String(g.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        const hasExistingItems = idsToRemove.some(id => {
            const item = guideList.find(g => String(g.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        
        const count = checkboxes.length;
        const itemLabel = count === 1 ? 'guide' : 'guides';
        showRemoveFormSelectionAlert(count, itemLabel, () => {
        const snapshotBefore = snapshotAllServiceState();
        
        // CASCADE: Remove guide links from parent services
        idsToRemove.forEach(guideIdToRemove => {
            // Remove from tours
            tourList.forEach(tour => {
                if (tour.guideId && String(tour.guideId) === String(guideIdToRemove)) {
                    tour.guideId = null;
                    tour.guideInfo = null;
                    // Update guide_options in the tour to reflect removal
                    if (tour.guide_options) {
                        delete tour.guide_options;
                    }
                }
            });
            
            // Remove from local transfers
            transferList.forEach(transfer => {
                if (transfer.guideId && String(transfer.guideId) === String(guideIdToRemove)) {
                    transfer.guideId = null;
                    transfer.guideInfo = null;
                    // Update guide_options in the transfer to reflect removal
                    if (transfer.guide_options) {
                        delete transfer.guide_options;
                    }
                    console.log('Unchecked guide checkbox for local transfer:', transfer);
                }
            });
            
            // Remove from hotels
            accommodationList.forEach(hotel => {
                if (hotel.guide_options && hotel.guide_options.guideId && String(hotel.guide_options.guideId) === String(guideIdToRemove)) {
                    delete hotel.guide_options;
                }
            });
            
            // Remove from meals/restaurants
            mealList.forEach(meal => {
                if (meal.guideId && String(meal.guideId) === String(guideIdToRemove)) {
                    // Uncheck the guide checkbox
                    meal.guideId = null;
                    meal.guideInfo = null;
                    // Note: Do NOT clear transferId - transfer checkbox should remain checked
                    console.log('Unchecked guide checkbox for meal/restaurant (transfer remains if checked):', meal);
                }
                // Also handle guide_options format
                if (meal.guide_options && meal.guide_options.guideId && String(meal.guide_options.guideId) === String(guideIdToRemove)) {
                    delete meal.guide_options;
                }
            });
            
            // Remove from arrival/departure
            arrivalDepartureList.forEach(item => {
                if (item.guideId && String(item.guideId) === String(guideIdToRemove)) {
                    // Uncheck the guide checkbox
                    item.hasGuide = false;
                    item.guideId = null;
                    // Note: Do NOT clear transferId - transfer checkbox should remain checked
                    console.log('Unchecked guide checkbox for arrival/departure (transfer remains if checked):', item);
                }
                // Also handle guide_options format
                if (item.guide_options && item.guide_options.guideId && String(item.guide_options.guideId) === String(guideIdToRemove)) {
                    delete item.guide_options;
                }
            });
        });
        
            // Remove guides from guideList
            guideList = guideList.filter(guide => !idsToRemove.includes(String(guide.id)));
            
            // Update all affected tables
            updateGuideTable();
            updateTourTable();
            updateTransferTable();
            updateAccommodationTable();
            updateMealTable();
            updateArrivalDepartureTable();
            recalculateHeaderDatesFromServices();
            recalculateTotals();
            scheduleRemoveWithUndo({
                categoryKey: 'guides',
                serviceMessage: 'Guide service',
                existingIds: existingIdsToRemove,
                snapshotBefore
            });
        }, window.hasNegotiationHistory, hasExistingItems);
    }
    
    // Update guide field
    function updateGuideField(index, field, value) {
        if (guideList[index]) {
            const guide = guideList[index];
            guide[field] = value;
            
            // If dateTime field is changed, update linked tour date and expand header dates
            if (field === 'dateTime' && value) {
                // Always expand header dates
                expandHeaderDatesIfNeeded(value, false);
                
                // If guide is linked to a tour, update the tour date as well
                if (guide.isStandalone === false) {
                    // Find the tour that has this guide
                    const tourIndex = tourList.findIndex(tour => tour.guideId === guide.id);
                    if (tourIndex !== -1) {
                        tourList[tourIndex].dateTime = value;
                        updateTourTable();
                        
                        // Also update linked transfer if exists
                        if (tourList[tourIndex].transferId) {
                            const transferIndex = transferList.findIndex(t => t.id === tourList[tourIndex].transferId);
                            if (transferIndex !== -1) {
                                transferList[transferIndex].dateTime = value;
                                updateTransferTable();
                            }
                        }
                        console.log('Updated linked tour and transfer dates to:', value);
                    }
                }
                
                // Refresh guide table
                updateGuideTable();
            }
            
            // If cost or sell is changed, recalculate totals to update bottom section
            if (field === 'cost' || field === 'sell') {
                recalculateTotals();
            }
        }
    }
    
    // Update guide supplement checkbox
    // Update guide supplement checkbox - do NOT sync with linked services
    function updateGuideSupplement(index, checked) {
        if (guideList[index]) {
            const guide = guideList[index];
            guide.supplement = checked;
            
            // Update the guide table
            updateGuideTable();
            
            // Recalculate totals after supplement change
            recalculateTotals();
        }
    }

    // ==================== MISCELLANEOUS FUNCTIONS ====================
    
    // Open Miscellaneous Modal
    function openMiscModal() {
        console.log('========================================');
        console.log('openMiscModal() called');
        console.log('========================================');
        
        try {
            window.editingMiscIndex = null;
            
            // Set default date
            const dateInput = document.getElementById('miscDate');
            if (dateInput) {
                const defaultDate = getDefaultServiceDate();
                dateInput.value = defaultDate;
            }
            
            // Reset destination
            const destinationSelect = document.getElementById('miscDestination');
            if (destinationSelect) {
                destinationSelect.value = '';
            }
            
            // Clear items table
            const itemsTableBody = document.getElementById('miscItemsTableBody');
            if (itemsTableBody) {
                itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-muted" style="padding: 20px;">Please select a destination to load miscellaneous items</td></tr>';
            }
            
            // Reset checkboxes
            document.querySelectorAll('.misc-item-checkbox').forEach(cb => cb.checked = false);
            
            // Update modal title for ADD mode
            document.getElementById('miscModalTitleText').textContent = 'Add Miscellaneous Items';
            const saveMiscBtn = document.getElementById('saveMiscBtnText');
            if (saveMiscBtn) saveMiscBtn.textContent = 'Save & Close';
            
            // Auto-fill fields from header
            autoFillModalFields('misc');
            
            const miscModal = new bootstrap.Modal(document.getElementById('miscModal'));
            miscModal.show();
            
            console.log('openMiscModal() completed successfully');
        } catch (error) {
            console.error('Error in openMiscModal():', error);
            alert('Error opening miscellaneous modal: ' + error.message);
        }
    }
    
    // Load miscellaneous items by destination (from API based on DMC)
    function loadMiscItemsByDestination() {
        const destination = document.getElementById('miscDestination').value;
        const itemsTableBody = document.getElementById('miscItemsTableBody');
        
        if (!destination) {
            itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-muted" style="padding: 20px;">Please select a destination to load miscellaneous items</td></tr>';
            return;
        }
        
        // Show loading state
        itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center" style="padding: 20px;"><i class="ri-loader-4-line ri-spin me-2"></i>Loading miscellaneous items...</td></tr>';
        
        // Get DMC ID from the form or session
        const dmcId = '{{ $dmc_id ?? "" }}';
        
        console.log('DMC ID from backend:', dmcId);
        console.log('User role_id:', '{{ auth()->user()->role_id ?? "N/A" }}');
        console.log('User userId:', '{{ auth()->user()->userId ?? "N/A" }}');
        console.log('User created_by:', '{{ auth()->user()->created_by ?? "N/A" }}');
        
        if (!dmcId || dmcId === '') {
            itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-danger" style="padding: 20px;"><i class="ri-error-warning-line me-2"></i>DMC ID not found. Please contact support.<br><small class="text-muted">Role: {{ auth()->user()->role_id ?? "N/A" }}, User ID: {{ auth()->user()->userId ?? "N/A" }}</small></td></tr>';
            console.error('DMC ID not available. User role:', '{{ auth()->user()->role_id ?? "N/A" }}');
            return;
        }
        
        // Fetch items from API
        fetch(`{{ url('/api/miscellaneous/dmc') }}/${dmcId}`)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Failed to load items');
                }
                // Check if response is JSON before parsing
                const contentType = response.headers.get("content-type");
                if (!contentType || !contentType.includes("application/json")) {
                    throw new Error('Server returned non-JSON response');
                }
                return response.json();
            })
            .then(items => {
                console.log('Loaded miscellaneous items:', items);
                
                if (!items || items.length === 0) {
                    itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-muted" style="padding: 20px;">No miscellaneous items available. Please configure items in the DMC panel.</td></tr>';
                    return;
                }
                
                // Render items
                itemsTableBody.innerHTML = items.map(item => `
                    <tr class="misc-item-row" data-item-id="misc_${item.mis_id}" data-item-name="${item.item_name}" data-mis-id="${item.mis_id}">
                        <td style="padding: 2px 8px; text-align: center;">
                            <input type="checkbox" class="misc-item-checkbox" data-item-id="misc_${item.mis_id}">
                        </td>
                        <td style="padding: 2px 8px;">
                            ${item.image ? `<img src="${item.image}" alt="${item.item_name}" style="width: 20px; height: 20px; object-fit: cover; border-radius: 3px; margin-right: 5px;">` : ''}
                            <strong>${item.item_name}</strong>
                            ${item.description ? `<br><small class="text-muted">${item.description}</small>` : ''}
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="number" class="form-control form-control-sm misc-adult-qty" data-item-id="misc_${item.mis_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="text" class="form-control form-control-sm misc-adult-charge" data-item-id="misc_${item.mis_id}" value="${parseFloat(item.adult_price || 0).toFixed(2)}" style="font-size: 10px; padding: 2px 4px;">
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="number" class="form-control form-control-sm misc-child-qty" data-item-id="misc_${item.mis_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="text" class="form-control form-control-sm misc-child-charge" data-item-id="misc_${item.mis_id}" value="${parseFloat(item.child_price || 0).toFixed(2)}" style="font-size: 10px; padding: 2px 4px;">
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="number" class="form-control form-control-sm misc-infant-qty" data-item-id="misc_${item.mis_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
                        </td>
                        <td style="padding: 2px 8px;">
                            <input type="text" class="form-control form-control-sm misc-infant-charge" data-item-id="misc_${item.mis_id}" value="${parseFloat(item.infant_price || 0).toFixed(2)}" style="font-size: 10px; padding: 2px 4px;">
                        </td>
                        <td style="padding: 2px 8px; text-align: center;" class="group-foc-service-discount-ui">
                            <input type="checkbox" class="form-check-input misc-foc-discount" data-item-id="misc_${item.mis_id}" title="FOC discount (this item)">
                        </td>
                    </tr>
                `).join('');
                
                // Auto-fill adult/child/infant counts from header for all newly created rows
                const headerValues = getHeaderValues();
                document.querySelectorAll('.misc-adult-qty').forEach(input => {
                    if (!input.value || input.value == '0') input.value = headerValues.adults;
                    input.setAttribute('max', headerValues.adults);
                    // Remove any existing listeners to avoid duplicates
                    const newInput = input.cloneNode(true);
                    input.parentNode.replaceChild(newInput, input);
                    newInput.addEventListener('input', function() {
                        if (parseInt(this.value) > headerValues.adults) {
                            this.value = headerValues.adults;
                            alert(`Adults cannot exceed ${headerValues.adults} (header value)`);
                        }
                    });
                });
                document.querySelectorAll('.misc-child-qty').forEach(input => {
                    if (!input.value || input.value == '0') input.value = headerValues.children;
                    input.setAttribute('max', headerValues.children);
                    // Remove any existing listeners to avoid duplicates
                    const newInput = input.cloneNode(true);
                    input.parentNode.replaceChild(newInput, input);
                    newInput.addEventListener('input', function() {
                        if (parseInt(this.value) > headerValues.children) {
                            this.value = headerValues.children;
                            alert(`Children cannot exceed ${headerValues.children} (header value)`);
                        }
                    });
                });
                document.querySelectorAll('.misc-infant-qty').forEach(input => {
                    if (!input.value || input.value == '0') input.value = headerValues.infants;
                    input.setAttribute('max', headerValues.infants);
                    // Remove any existing listeners to avoid duplicates
                    const newInput = input.cloneNode(true);
                    input.parentNode.replaceChild(newInput, input);
                    newInput.addEventListener('input', function() {
                        if (parseInt(this.value) > headerValues.infants) {
                            this.value = headerValues.infants;
                            alert(`Infants cannot exceed ${headerValues.infants} (header value)`);
                        }
                    });
                });
            })
            .catch(error => {
                console.error('Error loading miscellaneous items:', error);
                itemsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-danger" style="padding: 20px;"><i class="ri-error-warning-line me-2"></i>Error loading items. Please try again.</td></tr>';
            });
    }
    
    // Toggle select all miscellaneous items (in modal)
    function toggleSelectAllMiscItems() {
        const selectAll = document.getElementById('selectAllMiscItems');
        const checkboxes = document.querySelectorAll('.misc-item-checkbox');
        checkboxes.forEach(cb => cb.checked = selectAll.checked);
    }
    
    // Save and close miscellaneous modal
    function saveAndCloseMisc() {
        console.log('========================================');
        console.log('saveAndCloseMisc() called');
        console.log('========================================');
        
        const selectedRows = Array.from(document.querySelectorAll('.misc-item-checkbox:checked'));
        console.log('Selected rows:', selectedRows.length);
        
        if (selectedRows.length === 0) {
            alert('Please select at least one miscellaneous item');
            return;
        }
        
        const dateTime = document.getElementById('miscDate').value;
        const destination = document.getElementById('miscDestination').value;
        console.log('Date:', dateTime, 'Destination:', destination);
        
        if (!dateTime || !destination) {
            alert('Please select date and destination');
            return;
        }
        
        // If editing, update the existing item
        if (window.editingMiscIndex !== null && window.editingMiscIndex !== undefined) {
            const checkbox = selectedRows[0]; // Only use first selected when editing
            const itemId = checkbox.getAttribute('data-item-id');
            const row = checkbox.closest('tr');
            const itemName = row.getAttribute('data-item-name');
            
            // Get values from the row
            const adultsQty = parseInt(row.querySelector('.misc-adult-qty').value) || 0;
            const adultCharge = row.querySelector('.misc-adult-charge').value || '0.00';
            const childQty = parseInt(row.querySelector('.misc-child-qty').value) || 0;
            const childCharge = row.querySelector('.misc-child-charge').value || '0.00';
            const infantQty = parseInt(row.querySelector('.misc-infant-qty').value) || 0;
            const infantCharge = row.querySelector('.misc-infant-charge').value || '0.00';
            const focServiceDiscount = row.querySelector('.misc-foc-discount')?.checked === true;
            
            // Parse charges
            const adultCost = parseFloat(adultCharge.replace(/[^0-9.]/g, '')) || 0;
            const adultSell = adultCost;
            const childCost = parseFloat(childCharge.replace(/[^0-9.]/g, '')) || 0;
            const childSell = childCost;
            const infantCost = parseFloat(infantCharge.replace(/[^0-9.]/g, '')) || 0;
            const infantSell = infantCost;
            
            // Update the existing item
            miscList[window.editingMiscIndex] = {
                id: miscList[window.editingMiscIndex].id, // Keep existing ID
                itemId: itemId,
                itemName: itemName,
                destination: destination,
                dateTime: dateTime,
                adultsQty: adultsQty,
                adultCost: adultCost,
                adultSell: adultSell,
                childQty: childQty,
                childCost: childCost,
                childSell: childSell,
                infantQty: infantQty,
                infantCost: infantCost,
                infantSell: infantSell,
                supplement: !!miscList[window.editingMiscIndex].supplement,
                focServiceDiscount: focServiceDiscount
            };
            
            window.editingMiscIndex = null;
        } else {
            // Add new items
            selectedRows.forEach(checkbox => {
                const itemId = checkbox.getAttribute('data-item-id');
                const row = checkbox.closest('tr');
                const itemName = row.getAttribute('data-item-name');
                
                // Get values from the row
                const adultsQty = parseInt(row.querySelector('.misc-adult-qty').value) || 0;
                const adultCharge = row.querySelector('.misc-adult-charge').value || '0.00';
                const childQty = parseInt(row.querySelector('.misc-child-qty').value) || 0;
                const childCharge = row.querySelector('.misc-child-charge').value || '0.00';
                const infantQty = parseInt(row.querySelector('.misc-infant-qty').value) || 0;
                const infantCharge = row.querySelector('.misc-infant-charge').value || '0.00';
                const focServiceDiscount = row.querySelector('.misc-foc-discount')?.checked === true;
                
                // Parse charges
                const adultCost = parseFloat(adultCharge.replace(/[^0-9.]/g, '')) || 0;
                const adultSell = adultCost;
                const childCost = parseFloat(childCharge.replace(/[^0-9.]/g, '')) || 0;
                const childSell = childCost;
                const infantCost = parseFloat(infantCharge.replace(/[^0-9.]/g, '')) || 0;
                const infantSell = infantCost;
                
                const miscData = {
                    id: generateId('misc'),
                    itemId: itemId,
                    itemName: itemName,
                    destination: destination,
                    dateTime: dateTime,
                    adultsQty: adultsQty,
                    adultCost: adultCost,
                    adultSell: adultSell,
                    childQty: childQty,
                    childCost: childCost,
                    childSell: childSell,
                    infantQty: infantQty,
                    infantCost: infantCost,
                    infantSell: infantSell,
                    supplement: false,
                    focServiceDiscount: focServiceDiscount
                };
                
                miscList.push(miscData);
            });
        }
        
        updateMiscTable();
        recalculateHeaderDatesFromServices();
        recalculateTotals();
        
        const miscModal = bootstrap.Modal.getInstance(document.getElementById('miscModal'));
        if (miscModal) miscModal.hide();
    }
    
    // Add another miscellaneous item
    function addAnotherMisc() {
        saveAndCloseMisc();
        setTimeout(() => openMiscModal(), 300);
    }
    
    // Update miscellaneous table
    function updateMiscTable() {
        const tbody = document.getElementById('miscTableBody');
        const table = document.getElementById('miscTable');
        const emptyMessage = document.getElementById('emptyMiscMessage');
        
        if (miscList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        tbody.innerHTML = miscList.map((item, index) => `
            <tr>
                <td><input type="checkbox" class="misc-checkbox" value="${item.id}"></td>
                <td><input type="datetime-local" value="${normalizeDateTimeLocal(item.dateTime)}" onchange="updateMiscField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;"></td>
                <td>
                    <a href="javascript:void(0)" onclick="editMisc(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">
                        ${item.itemName}
                    </a>
                </td>
                <td><input type="number" value="${item.adultsQty}" onchange="updateMiscField(${index}, 'adultsQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(item.adultCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(item.adultSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateMiscField(${index}, 'adultSell', this.value)" step="1"></td>
                <td><input type="number" value="${item.childQty}" onchange="updateMiscField(${index}, 'childQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(item.childCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(item.childSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateMiscField(${index}, 'childSell', this.value)" step="1"></td>
                <td><input type="number" value="${item.infantQty}" onchange="updateMiscField(${index}, 'infantQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(item.infantCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(item.infantSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateMiscField(${index}, 'infantSell', this.value)" step="1"></td>
                <td style="text-align: center;" class="group-foc-service-discount-ui"><input type="checkbox" ${item.focServiceDiscount || item.foc_service_discount ? 'checked' : ''} onchange="updateMiscField(${index}, 'focServiceDiscount', this.checked)"></td>
                <td style="text-align: center;"><input type="checkbox" ${item.supplement ? 'checked' : ''} onchange="updateMiscSupplement(${index}, this.checked)"></td>
            </tr>
        `).join('');
    }
    
    // Edit miscellaneous item
    function editMisc(index) {
        const item = miscList[index];
        if (!item) return;
        
        console.log('=== EDITING MISCELLANEOUS ITEM ===');
        console.log('Index:', index);
        console.log('Item:', item);
        
        window.editingMiscIndex = index;
        
        // Set date and time
        const dateInput = document.getElementById('miscDate');
        if (dateInput) {
            // For datetime-local input, we need the full datetime format (YYYY-MM-DDTHH:mm)
            let dateTimeValue = item.dateTime || '';
            // If the datetime doesn't have a time component, add default time 09:00
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T09:00';
            }
            dateInput.value = dateTimeValue;
        }
        
        // Set destination
        const destinationSelect = document.getElementById('miscDestination');
        if (destinationSelect && item.destination) {
            destinationSelect.value = item.destination;
        }
        
        // Load items for this destination
        loadMiscItemsByDestination();
        
        // Function to populate the form after items load
        const populateEditForm = (attempt = 1, maxAttempts = 10) => {
            console.log(`Attempt ${attempt} to populate edit form for item:`, item.itemId);
            
            // Find and check the matching item row
            const rows = Array.from(document.querySelectorAll('.misc-item-row'));
            const targetRow = rows.find(r => {
                const rowItemId = r.getAttribute('data-item-id');
                return String(item.itemId) === rowItemId;
            });
            
            if (targetRow) {
                console.log('Found target row for item:', item.itemId);
                
                // Reset all checkboxes first
                document.querySelectorAll('.misc-item-checkbox').forEach(cb => cb.checked = false);
                
                const itemId = targetRow.getAttribute('data-item-id');
                
                // Check the row
                const checkbox = targetRow.querySelector(`.misc-item-checkbox[data-item-id="${itemId}"]`);
                if (checkbox) {
                    checkbox.checked = true;
                    console.log('Checkbox checked for item:', itemId);
                } else {
                    console.warn('Checkbox not found for item:', itemId);
                }
                
                // Fill editable fields on the row
                const setVal = (selector, value) => {
                    const el = targetRow.querySelector(`${selector}[data-item-id="${itemId}"]`);
                    if (el) el.value = value ?? el.value;
                };
                
                setVal('.misc-adult-qty', item.adultsQty);
                setVal('.misc-adult-charge', parseFloat(String(item.adultCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
                setVal('.misc-child-qty', item.childQty);
                setVal('.misc-child-charge', parseFloat(String(item.childCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
                setVal('.misc-infant-qty', item.infantQty);
                setVal('.misc-infant-charge', parseFloat(String(item.infantCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
                const mFoc = targetRow.querySelector(`.misc-foc-discount[data-item-id="${itemId}"]`);
                if (mFoc) mFoc.checked = !!(item.focServiceDiscount || item.foc_service_discount);
                
                // Scroll the row into view
                targetRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
            } else {
                console.warn(`Row not found for item ${item.itemId}, attempt ${attempt}/${maxAttempts}`);
                
                // Retry if items haven't loaded yet
                if (attempt < maxAttempts) {
                    setTimeout(() => populateEditForm(attempt + 1, maxAttempts), 200);
                } else {
                    console.error('Failed to find item row after', maxAttempts, 'attempts');
                }
            }
        };
        
        // Wait for items to load, then populate the form
        setTimeout(() => populateEditForm(), 500);
        
        document.getElementById('miscModalTitleText').textContent = 'Edit Miscellaneous Item';
        const saveMiscBtn = document.getElementById('saveMiscBtnText');
        if (saveMiscBtn) saveMiscBtn.textContent = 'Update Item';
        
        const miscModal = new bootstrap.Modal(document.getElementById('miscModal'));
        miscModal.show();
    }
    
    // Remove selected miscellaneous items
    function removeSelectedMisc() {
        const checkboxes = document.querySelectorAll('.misc-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select items to remove');
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        const existingIdsToRemove = idsToRemove.filter(id => {
            const item = miscList.find(m => String(m.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        const hasExistingItems = idsToRemove.some(id => {
            const item = miscList.find(m => String(m.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        
        const count = checkboxes.length;
        const itemLabel = count === 1 ? 'item' : 'items';
        showRemoveFormSelectionAlert(count, itemLabel, () => {
            const snapshotBefore = snapshotAllServiceState();
            miscList = miscList.filter(item => !idsToRemove.includes(String(item.id)));
            
            updateMiscTable();
            recalculateHeaderDatesFromServices();
            recalculateTotals();
            scheduleRemoveWithUndo({
                categoryKey: 'miscellaneous',
                serviceMessage: 'Miscellaneous service',
                existingIds: existingIdsToRemove,
                snapshotBefore
            });
        }, window.hasNegotiationHistory, hasExistingItems);
    }

