            // Get adult and child quantities from modal inputs
            const restaurantGuideAdultQty = parseInt(document.getElementById('restaurantGuideAdultQty')?.value || '0') || 0;
            const restaurantGuideChildQty = parseInt(document.getElementById('restaurantGuideChildQty')?.value || '0') || 0;
            
            let guideId = null;
            let guideInfo = null;
            let guideEntryId = null;
            
            if (guideChecked && guideSelect && guideSelect.value) {
                guideId = guideSelect.value;
                const guideOption = guideSelect.selectedOptions[0];
                const hoursSelect = document.getElementById('restaurantGuideHours');
                const hours = parseInt(hoursSelect?.value || '12') || 12;
                
                // Calculate price based on hours
                let price = 0;
                switch(hours) {
                    case 2:
                        price = parseFloat(guideOption?.getAttribute('data-two-hour-price') || '0') || 0;
                        break;
                    case 4:
                        price = parseFloat(guideOption?.getAttribute('data-four-hour-price') || '0') || 0;
                        break;
                    case 6:
                        price = parseFloat(guideOption?.getAttribute('data-six-hour-price') || '0') || 0;
                        break;
                    case 8:
                        price = parseFloat(guideOption?.getAttribute('data-eight-hour-price') || '0') || 0;
                        break;
                    case 10:
                        price = parseFloat(guideOption?.getAttribute('data-ten-hour-price') || '0') || 0;
                        break;
                    case 12:
                    default:
                        price = parseFloat(guideOption?.getAttribute('data-twelve-hour-price') || '0') || 0;
                        break;
                }
                
                // Create guide entry for guide table (ONE guide entry for all meals at this restaurant)
                // Generate guideEntryId FIRST so we can include it in guideInfo
                guideEntryId = generateId('guide');
                
                guideInfo = {
                    id: guideEntryId, // Include entry ID so it can be used for duplicate detection when loading
                    guideId: guideId,
                    guideName: guideOption?.getAttribute('data-name') || guideOption?.text || '',
                    languages: guideOption?.getAttribute('data-languages') || '',
                    hours: hours,
                    cost: price,
                    sell: price,
                    adultsQty: restaurantGuideAdultQty,
                    childQty: restaurantGuideChildQty
                };
                console.log('Guide selected for meals:', guideInfo, 'Hours:', hours, 'Price:', price);
                // Guide entries are pushed per meal in the meal loop below (one guide per meal with distributed date)
            }
            
            // For date distribution: get tour start date and time part from modal dateTime
            const tourStartInput = getHeaderStartInput();
            const tourStartISO = tourStartInput ? getHeaderInputISO(tourStartInput) : null;
            let timePart = '12:00';
            if (dateTime && (dateTime.indexOf('T') !== -1)) {
                const t = dateTime.split('T')[1];
                if (t) timePart = t.substring(0, 5);
            } else if (dateTime && dateTime.length >= 16) {
                timePart = dateTime.substring(11, 16);
            }
            
            // Adding new meals - loop through selected rows, adding mealCount times per row
            selectedRows.forEach((checkbox, index) => {
                const mealItemId = checkbox.getAttribute('data-meal-id');
                const row = checkbox.closest('tr');
                if (!row) {
                    console.warn('Could not find row for checkbox:', checkbox);
                    return;
                }
                const mealName = row.getAttribute('data-meal-name');
                const mealTypeRaw = row.getAttribute('data-meal-type') || '';
                const mealPeriodVal = row.getAttribute('data-meal-period') || '';
                const mealType = mealPeriodVal || mealTypeRaw || mealName;
                const mealTypeId = row.getAttribute('data-meal-type-id') || '';
                let mealSpecificType = '';
                if (mealTypeId == 1) mealSpecificType = '🍽️ Buffet';
                else if (mealTypeId == 2) mealSpecificType = '📋 Set Menu';
                
                const mealCount = parseInt(row.querySelector('.meal-count')?.value) || 1;
                const adultsQty = parseInt(row.querySelector('.meal-adult-qty')?.value) || 0;
                const adultCostValue = row.querySelector('.meal-adult-cost')?.value || '0.00';
                const adultSellValue = row.querySelector('.meal-adult-sell')?.value || '0.00';
                const childQty = parseInt(row.querySelector('.meal-child-qty')?.value) || 0;
                const childCostValue = row.querySelector('.meal-child-cost')?.value || '0.00';
                const childSellValue = row.querySelector('.meal-child-sell')?.value || '0.00';
                const infantQty = parseInt(row.querySelector('.meal-infant-qty')?.value) || 0;
                const infantCostValue = row.querySelector('.meal-infant-cost')?.value || '0.00';
                const infantSellValue = row.querySelector('.meal-infant-sell')?.value || row.querySelector('.meal-infant-cost')?.value || '0.00';
                
                const adultCost = parseFloat(adultCostValue.replace(/[^0-9.]/g, '')) || 0;
                const adultSell = parseFloat(adultSellValue.replace(/[^0-9.]/g, '')) || 0;
                const childCost = parseFloat(childCostValue.replace(/[^0-9.]/g, '')) || 0;
                const childSell = parseFloat(childSellValue.replace(/[^0-9.]/g, '')) || 0;
                const infantCost = parseFloat(infantCostValue.replace(/[^0-9.]/g, '')) || 0;
                const infantSell = parseFloat(infantSellValue.replace(/[^0-9.]/g, '')) || 0;
                const mealRowFoc = row.querySelector('.meal-foc-discount')?.checked === true;
                
                let guide_options = null;
                if (guideChecked && guideId && guideInfo) {
                    const hoursSelect = document.getElementById('restaurantGuideHours');
                    const hours = parseInt(hoursSelect?.value || '12') || 12;
                    const guideOption = guideSelect.selectedOptions[0];
                    let price = 0;
                    switch(hours) {
                        case 2: price = parseFloat(guideOption?.getAttribute('data-two-hour-price') || '0') || 0; break;
                        case 4: price = parseFloat(guideOption?.getAttribute('data-four-hour-price') || '0') || 0; break;
                        case 6: price = parseFloat(guideOption?.getAttribute('data-six-hour-price') || '0') || 0; break;
                        case 8: price = parseFloat(guideOption?.getAttribute('data-eight-hour-price') || '0') || 0; break;
                        case 10: price = parseFloat(guideOption?.getAttribute('data-ten-hour-price') || '0') || 0; break;
                        case 12: default: price = parseFloat(guideOption?.getAttribute('data-twelve-hour-price') || '0') || 0; break;
                    }
                    
                    guide_options = {
                        guideId: guideInfo.guideId, guide_id: guideInfo.guideId,
                        guideName: guideInfo.guideName, guide_name: guideInfo.guideName, name: guideInfo.guideName,
                        languages: guideInfo.languages, language: guideInfo.languages,
                        hours: hours,
                        adultsQty: restaurantGuideAdultQty, adults_qty: restaurantGuideAdultQty,
                        adultQty: restaurantGuideAdultQty, adult_qty: restaurantGuideAdultQty,
                        childQty: restaurantGuideChildQty, child_qty: restaurantGuideChildQty,
                        childrenQty: restaurantGuideChildQty, children_qty: restaurantGuideChildQty,
                        cost: price, sell: price,
                        serviceType: hours >= 12 ? 'Full Day' : 'Half Day',
                        service_type: hours >= 12 ? 'Full Day' : 'Half Day',
                        tourActivity: `Restaurant Guide - ${restaurantName}`,
                        tour_activity: `Restaurant Guide - ${restaurantName}`
                    };
                }
                
                // Add mealCount entries for this meal row
                const rowIds = mealIdsPerRow[index];
                for (let mc = 0; mc < mealCount; mc++) {
                    // Distributed date: meal 0 = tour start, meal 1 = start+1 day, etc.
                    const dateTimeForMc = (tourStartISO && timePart)
                        ? (addDaysToDateString(tourStartISO, mc) + 'T' + timePart)
                        : dateTime;
                    
                    let thisTransferId = null;
                    let thisTransferInfo = null;
                    if (transferChecked && transferInfo && (transferId || transferInfo.id)) {
                        if (mc === 0) {
                            thisTransferId = transferId;
                            thisTransferInfo = transferInfo;
                            const firstTransferEntry = transferList.find(t => t.id === transferId);
                            if (firstTransferEntry && dateTimeForMc) firstTransferEntry.dateTime = dateTimeForMc;
                        } else {
                            const newTransferEntryId = generateId('transfer');
                            const firstTransferEntry = transferList.find(t => t.id === transferId);
                            if (firstTransferEntry) {
                                const cloneEntry = Object.assign({}, firstTransferEntry, { id: newTransferEntryId, sourceId: rowIds[mc], dateTime: dateTimeForMc });
                                transferList.push(cloneEntry);
                            }
                            thisTransferId = newTransferEntryId;
                            thisTransferInfo = Object.assign({}, transferInfo, { id: newTransferEntryId });
                        }
                    }
                    
                    let thisGuideId = null;
                    let thisGuideInfo = null;
                    let thisGuideOptions = null;
                    if (guideChecked && guideInfo) {
                        const hoursSelect = document.getElementById('restaurantGuideHours');
                        const hours = parseInt(hoursSelect?.value || '12') || 12;
                        const currentGuideEntryId = mc === 0 ? guideEntryId : generateId('guide');
                        const guideEntry = {
                            id: currentGuideEntryId,
                            dateTime: dateTimeForMc,
                            tourActivity: `${restaurantName} (Restaurant Guide)`,
                            language: guideInfo.languages || 'N/A',
                            guideName: guideInfo.guideName,
                            guideId: guideInfo.guideId,
                            hours: hours,
                            cost: guideInfo.cost,
                            sell: guideInfo.sell,
                            supplement: false,
                            isStandalone: false,
                            linkedTo: 'restaurant',
                            restaurantName: restaurantName,
                            adultsQty: guideInfo.adultsQty,
                            childQty: guideInfo.childQty,
                            focServiceDiscount: restaurantGuideFocSvc
                        };
                        guideList.push(guideEntry);
                        thisGuideId = currentGuideEntryId;
                        thisGuideInfo = Object.assign({}, guideInfo, { id: currentGuideEntryId });
                        if (guide_options) {
                            thisGuideOptions = Object.assign({}, guide_options);
                        }
                    }
                    
                    const mealData = {
                        id: rowIds[mc],
                        destination: document.getElementById('mealDestination').value || 'Singapore',
                        restaurantId: restaurantId,
                        restaurantName: restaurantName,
                        mealId: mealItemId,
                        mealName: mealName,
                        mealType: mealType,
                        mealSpecificType: mealSpecificType,
                        dateTime: dateTimeForMc,
                        mealCount: 1,
                        adultsQty: adultsQty,
                        adultCost: adultCost,
                        adultSell: adultSell,
                        childQty: childQty,
                        childCost: childCost,
                        childSell: childSell,
                        infantQty: infantQty,
                        infantCost: infantCost,
                        infantSell: infantSell,
                        transferId: thisTransferId,
                        transferInfo: thisTransferInfo,
                        guideId: thisGuideId,
                        guideInfo: thisGuideInfo,
                        guide_options: thisGuideOptions,
                        focServiceDiscount: mealRowFoc
                    };
                    
                    mealList.push(mealData);
                    console.log(`Added meal (${mc + 1}/${mealCount}):`, mealData);
                }
                
                updateHeaderDatesIfNeeded(dateTime);
            });
        }
        
        // Update tables
        updateMealTable();
        updateGuideTable();
        updateTransferTable();
        recalculateTotals();
        
        // Close modal
        const mealModal = bootstrap.Modal.getInstance(document.getElementById('mealModal'));
        if (mealModal) mealModal.hide();
        
        // Reset checkboxes
        document.getElementById('selectAllMeals').checked = false;
        document.querySelectorAll('.meal-checkbox').forEach(cb => cb.checked = false);
    }
    
    // Add another meal (keep modal open)
    async function addAnotherMeal() {
        const selectedRows = document.querySelectorAll('.meal-checkbox:checked');
        
        if (selectedRows.length === 0) {
            alert('Please select at least one meal');
            return;
        }
        
        // Save current selections without closing - wait for it to complete
        await saveAndCloseMeals();
        
        // Reopen the modal after save completes
        const mealModal = new bootstrap.Modal(document.getElementById('mealModal'));
        mealModal.show();
    }
    
    // Save meal
    function saveMeal() {
        const destination = document.getElementById('mealDestination').value;
        const restaurantSelect = document.getElementById('mealRestaurant');
        const restaurantId = restaurantSelect.value;
        const restaurantName = restaurantSelect.options[restaurantSelect.selectedIndex]?.text || '';
        const dateTime = document.getElementById('mealDateTime').value;
        const adultsQty = parseInt(document.getElementById('mealAdultsQty').value);
        const adultCost = parseFloat(document.getElementById('mealAdultCost').value);
        const adultSell = parseFloat(document.getElementById('mealAdultSell').value);
        const childQty = parseInt(document.getElementById('mealChildQty').value);
        const childCost = parseFloat(document.getElementById('mealChildCost').value);
        const childSell = parseFloat(document.getElementById('mealChildSell').value);
        
        if (!restaurantId || !dateTime) {
            alert('Please select restaurant and date/time');
            return;
        }
        
        const isEditing = window.editingMealIndex !== undefined && window.editingMealIndex !== null;
        
        // Get transfer info
        const transferRequired = document.getElementById('mealTransferRequired').value === 'yes';
        let transferInfo = null;
        let transferId = null;
        
        if (transferRequired) {
            const transferType = document.getElementById('mealTransferType').value;
            const transferWay = document.getElementById('mealTransferWay').value;
            const vehicleType = document.getElementById('mealVehicleType').value;
            const transferCost = parseFloat(document.getElementById('mealTransferCost').value);
            const transferSell = parseFloat(document.getElementById('mealTransferSell').value);
            
            transferId = generateId('transfer');
            transferInfo = {
                id: transferId,
                type: transferType,
                way: transferWay,
                vehicleType: vehicleType,
                cost: transferCost,
                sell: transferSell,
                destination: restaurantName,
                dateTime: dateTime,
                adults: adultsQty,
                adultsQty: adultsQty,
                child: childQty,
                childQty: childQty,
                taxIncluded: true,
                transportMode: 'local',
                isStandalone: false,
                sourceType: 'restaurant',
                sourceId: restaurantId
            };
            
            // Add to transfer list
            transferList.push(transferInfo);
        }
        
    const mealData = {
        id: generateId('meal'),
            destination: destination,
            restaurantId: restaurantId,
            restaurantName: restaurantName,
            dateTime: dateTime,
            adultsQty: adultsQty,
            adultCost: adultCost,
            adultSell: adultSell,
            childQty: childQty,
            childCost: childCost,
            childSell: childSell,
            transferId: transferId,
            transferInfo: transferInfo
        };
        
        // Check if editing
        if (isEditing) {
            // Remove old transfer if exists
            const oldMeal = mealList[window.editingMealIndex];
            if (oldMeal.transferId) {
                transferList = transferList.filter(t => t.id !== oldMeal.transferId);
            }
            
            mealData.mealType = oldMeal.mealType || mealData.mealType;
            mealData.mealSpecificType = oldMeal.mealSpecificType || mealData.mealSpecificType;
            mealData.mealName = oldMeal.mealName || mealData.mealName;
            mealData.mealId = oldMeal.mealId || mealData.mealId;
            mealList[window.editingMealIndex] = mealData;
            window.editingMealIndex = null;
        } else {
            mealList.push(mealData);
        }
        
        // Update header dates
        if (isEditing) {
            // When editing, recalculate from all services to handle date changes properly
            recalculateHeaderDatesFromServices();
        } else {
            // When adding new, just expand if needed
            expandHeaderDatesIfNeeded(dateTime, true);
        }
        
        updateMealTable();
        updateTransferTable();
        recalculateTotals();
        
        // Close modal
        const mealModal = bootstrap.Modal.getInstance(document.getElementById('mealModal'));
        if (mealModal) mealModal.hide();
    }
    
    // Update meal table
    function updateMealTable() {
        const tbody = document.getElementById('mealTableBody');
        const table = document.getElementById('mealTable');
        const emptyMessage = document.getElementById('emptyMealMessage');
        
        if (mealList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        tbody.innerHTML = mealList.map((meal, index) => {
            // Ensure dateTime has time component, if not add default time based on meal type
            let dateTimeValue = meal.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                // Default times: Breakfast 08:00, Lunch 12:00, Dinner 19:00
                const mealType = (meal.mealType || '').toLowerCase();
                let defaultTime = '12:00'; // Default to lunch time
                if (mealType.includes('breakfast')) defaultTime = '08:00';
                else if (mealType.includes('dinner')) defaultTime = '19:00';
                dateTimeValue = dateTimeValue + 'T' + defaultTime;
            }
            
            // Format meal type for display (capitalize first letter) - show Breakfast/Lunch/Dinner
            const displayMealType = meal.mealType ? (meal.mealType.charAt(0).toUpperCase() + meal.mealType.slice(1)) : 'Meal';
            
            // Get Buffet or Set Menu text
            const mealSpecificType = meal.mealSpecificType || '';
            const mealSpecificDisplay = mealSpecificType ? ` (${mealSpecificType.replace(/🍽️|📋/g, '').trim()})` : '';
            
            return `
            <tr>
                <td><input type="checkbox" class="meal-checkbox" value="${meal.id}"></td>
                <td><input type="datetime-local" value="${dateTimeValue}" onchange="updateMealField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;"></td>
                <td>
                    <a href="javascript:void(0)" onclick="editMeal(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">
                        ${meal.restaurantName || 'Restaurant'} - ${displayMealType}${mealSpecificDisplay}
                    </a>
                </td>
                <td><input type="number" value="${meal.adultsQty}" onchange="updateMealField(${index}, 'adultsQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(meal.adultCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(meal.adultSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateMealField(${index}, 'adultSell', this.value)" step="1"></td>
                <td><input type="number" value="${meal.childQty}" onchange="updateMealField(${index}, 'childQty', this.value)"></td>
                <td><input type="text" value="${parseFloat(String(meal.childCost).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${parseFloat(String(meal.childSell).replace(/[^0-9.-]/g, '') || 0).toFixed(2)}" onchange="updateMealField(${index}, 'childSell', this.value)" step="1"></td>
                <td style="text-align: center;"><input type="checkbox" ${meal.supplement ? 'checked' : ''} onchange="updateMealSupplement(${index}, this.checked)"></td>
            </tr>
        `;
        }).join('');
    }
    
    // Ensure a meal row exists in the popup table for editing (for dynamically loaded meals)
    function ensureMealRowForEdit(meal) {
        const tbody = document.getElementById('mealsTableBody');
        if (!tbody) return null;
        
        // Use actual mealId from meal data, not restaurantId
        const mealId = meal.mealId || meal.meal_id || meal.id || generateId('meal');
        const mealName = meal.mealName || meal.meal_name || meal.restaurantName || 'Restaurant';
        const mealType = meal.mealType || meal.meal_type || 'custom';
        
        console.log('ensureMealRowForEdit: Looking for mealId:', mealId, 'mealName:', mealName);
        
        // Try to find existing row by mealId or mealName
        const existing = Array.from(tbody.querySelectorAll('tr.meal-row')).find(r => {
            const rowMealId = r.getAttribute('data-meal-id');
            const rowName = r.getAttribute('data-meal-name');
            return (mealId && String(mealId) === String(rowMealId)) || 
                   (mealName && String(mealName) === String(rowName));
        });
        
        if (existing) {
            console.log('Found existing row for meal:', mealId);
            return existing;
        }
        
        // Get transfer info - check transferList first if transferId exists
        let transferInfo = meal.transferInfo || {};
        const hasTransfer = !!meal.transferInfo || !!meal.transferId;
        
        if (meal.transferId && !meal.transferInfo) {
            const linkedTransfer = transferList.find(t => t.id === meal.transferId);
            if (linkedTransfer) {
                transferInfo = {
                    destination: linkedTransfer.destination,
                    vehicleType: linkedTransfer.vehicleType || 'sedan',
                    type: linkedTransfer.mode === 'Private' ? 'private' : 'sic',
                    way: linkedTransfer.way === 'Both Way' ? 'both-way' : 'one-way',
                    isDestinationPickup: linkedTransfer.isDestinationPickup || false
                };
            }
        }
        
        const row = document.createElement('tr');
        row.className = 'meal-row';
        row.setAttribute('data-meal-id', mealId);
        row.setAttribute('data-meal-name', mealName);
        row.setAttribute('data-meal-type', mealType);
        row.innerHTML = `
            <td style="padding: 2px 8px; text-align: center;">
                <input type="checkbox" class="meal-checkbox" data-meal-id="${mealId}">
            </td>
            <td style="padding: 2px 8px;">
                <strong>${mealType}</strong>
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-count" data-meal-id="${mealId}" value="${meal.mealCount ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-adult-qty" data-meal-id="${mealId}" value="${meal.adultsQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-adult-charge" data-meal-id="${mealId}" value="${meal.adultCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-child-qty" data-meal-id="${mealId}" value="${meal.childQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-child-charge" data-meal-id="${mealId}" value="${meal.childCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-infant-qty" data-meal-id="${mealId}" value="${meal.infantQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-infant-charge" data-meal-id="${mealId}" value="${meal.infantCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px; text-align: center;">
                <input type="checkbox" class="form-check-input meal-transfer-checkbox" data-meal-id="${mealId}" ${hasTransfer ? 'checked' : ''}>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-transfer-destination" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="">Select Destination</option>
                    ${getMealDestinationOptionsHTML(transferInfo.destination)}
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-vehicle-type" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="sedan" ${transferInfo.vehicleType === 'sedan' ? 'selected' : ''}>Sedan</option>
                    <option value="combi" ${transferInfo.vehicleType === 'combi' ? 'selected' : ''}>Combi</option>
                    <option value="van" ${transferInfo.vehicleType === 'van' ? 'selected' : ''}>Van</option>
                    <option value="bus" ${transferInfo.vehicleType === 'bus' ? 'selected' : ''}>Bus</option>
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-direction" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="1way" ${transferInfo.way === '1way' || transferInfo.way === 'one-way' ? 'selected' : ''}>One Way</option>
                    <option value="2way" ${transferInfo.way === 'both-way' || transferInfo.way === '2way' ? 'selected' : ''}>Two Way</option>
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-transfer-type" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="S" ${transferInfo.type === 'S' || transferInfo.type === 'sic' ? 'selected' : ''}>Shared</option>
                    <option value="P" ${transferInfo.type === 'P' || transferInfo.type === 'private' ? 'selected' : ''}>Private</option>
                </select>
            </td>
        `;
        
        // Prepend so it's visible immediately
        tbody.prepend(row);
        return row;
    }
    
    // Edit meal
    async function editMeal(index) {
        const meal = mealList[index];
        if (!meal) return;
        
        console.log('=== EDITING MEAL ===');
        console.log('Index:', index);
        console.log('Full meal object:', JSON.parse(JSON.stringify(meal)));
        console.log('Restaurant:', meal.restaurantName, 'ID:', meal.restaurantId);
        console.log('Meal Name:', meal.mealName, 'Type:', meal.mealType);
        console.log('Destination:', meal.destination);
        console.log('Transfer ID:', meal.transferId);
        console.log('Transfer Info:', meal.transferInfo);
        console.log('Current transferList:', JSON.parse(JSON.stringify(transferList)));
        
        if (meal.transferId) {
            const linkedTransfer = transferList.find(t => t.id === meal.transferId);
            console.log('Linked transfer found:', linkedTransfer);
        }
        
        window.editingMealIndex = index;
        
        // Set date and time - for datetime-local input, we need full datetime format (YYYY-MM-DDTHH:mm)
        let dateTimeValue = meal.dateTime || '';
        // If the datetime doesn't have a time component, add default time 09:00
        if (dateTimeValue && !dateTimeValue.includes('T')) {
            dateTimeValue = dateTimeValue + 'T09:00';
        }
        document.getElementById('mealDateTime').value = dateTimeValue;
        
        // Set destination
        const destinationSelect = document.getElementById('mealDestination');
        if (destinationSelect && meal.destination) {
            destinationSelect.value = meal.destination;
        }
        
        // Load restaurants for this destination
        loadRestaurantsByDestination();
        
        // Wait a moment for restaurants to load, then select the restaurant
        await new Promise(resolve => setTimeout(resolve, 100));
        
        const restaurantSelect = document.getElementById('mealRestaurant');
        if (restaurantSelect && meal.restaurantId) {
            restaurantSelect.value = meal.restaurantId;
            
            // Load meals from this restaurant and wait for it to complete
            await updateMealsFromRestaurant();
            
            // Now populate the form - meals are loaded
            populateMealFormForEdit(meal);
            
            // Populate restaurant transfer section if transfer exists
            const restaurantTransferCheckbox = document.getElementById('restaurantTransferCheckbox');
            const restaurantTransferDetailsSection = document.getElementById('restaurantTransferDetailsSection');
            
            if (meal.transferId || meal.transferInfo) {
                console.log('=== Populating Transfer Section for Edit ===');
                console.log('Meal data:', meal);
                
                if (restaurantTransferCheckbox) {
                    restaurantTransferCheckbox.checked = true;
                    // Just show the section directly, don't call toggle which sets defaults
                    if (restaurantTransferDetailsSection) {
                        restaurantTransferDetailsSection.style.display = 'block';
                    }
                }
                
                // Get transfer info - prioritize meal.transferInfo, then lookup from transferList
                let tInfo = null;
                
                if (meal.transferInfo) {
                    // Use the transfer info stored with the meal
                    tInfo = meal.transferInfo;
                    console.log('Using meal.transferInfo:', tInfo);
                } else if (meal.transferId) {
                    // Lookup from transferList
                    const linkedTransfer = transferList.find(t => t.id === meal.transferId);
                    console.log('Looking up transfer with ID:', meal.transferId, 'Found:', linkedTransfer);
                    if (linkedTransfer) {
                        tInfo = {
                            destination: linkedTransfer.destination,
                            destinationId: linkedTransfer.destinationId || null, // Store destination ID if available
                            vehicleId: linkedTransfer.vehicleId || '',
                            vehicleType: linkedTransfer.vehicleType || 'sedan',
                            type: linkedTransfer.type || 'S', // Use type directly (S or P)
                            way: linkedTransfer.way || 'one-way', // Use way directly (one-way or both-way)
                            isDestinationPickup: linkedTransfer.isDestinationPickup || false
                        };
                    }
                }
                
                if (tInfo) {
                    console.log('Final transfer info to populate:', tInfo);
                    
                    // Wait a bit for Select2 to be ready, then populate transfer fields
                    await new Promise(resolve => setTimeout(resolve, 150));
                    
                    const destSelect = document.getElementById('restaurantTransferDestination');
                    if (destSelect && tInfo.destination) {
                        // Try to find option by destination ID first, then by name
                        let destinationValue = null;
                        
                        if (tInfo.destinationId) {
                            // Try to find by value (destination ID)
                            destinationValue = tInfo.destinationId;
                        } else {
                            // Find option by data-name attribute matching destination name
                            const options = Array.from(destSelect.options);
                            const matchingOption = options.find(opt => {
                                const dataName = opt.getAttribute('data-name');
                                return dataName && dataName === tInfo.destination;
                            });
                            
                            if (matchingOption) {
                                destinationValue = matchingOption.value;
                            } else {
                                // Fallback: try to match by text
                                const textMatch = options.find(opt => opt.text === tInfo.destination);
                                if (textMatch) {
                                    destinationValue = textMatch.value;
                                }
                            }
                        }
                        
                        if (destinationValue) {
                            destSelect.value = destinationValue;
                            // Trigger change event for Select2 if it's being used
                            if (window.jQuery && jQuery(destSelect).hasClass('select2-hidden-accessible')) {
                                jQuery(destSelect).trigger('change');
                            }
                            console.log('Set destination to:', destinationValue, 'for destination name:', tInfo.destination);
                        } else {
                            console.warn('Could not find destination option for:', tInfo.destination);
                        }
                    }
                    
                    const vehicleSelect = document.getElementById('restaurantTransferVehicleType');
                    if (vehicleSelect && tInfo.vehicleId) {
                        vehicleSelect.value = tInfo.vehicleId;
                        // Trigger change event for Select2 if it's being used
                        if (window.jQuery && jQuery(vehicleSelect).hasClass('select2-hidden-accessible')) {
                            jQuery(vehicleSelect).trigger('change');
                        }
                        console.log('Set vehicle to:', tInfo.vehicleId);
                    }
                    
                    // Set "Is PickUp?" checkbox state
                    const isPickupCheckbox = document.getElementById('restaurantTransferIsPickup');
                    if (isPickupCheckbox) {
                        isPickupCheckbox.checked = tInfo.isDestinationPickup || false;
                        console.log('Set isDestinationPickup to:', tInfo.isDestinationPickup || false);
                    }
                    
                    const waySelect = document.getElementById('restaurantTransferWay');
                    if (waySelect && tInfo.way) {
                        // Normalize way value
                        let wayValue = tInfo.way;
                        if (wayValue === 'Both Way' || wayValue === 'both' || wayValue === '2way') {
                            wayValue = 'both-way';
                        } else if (wayValue === 'One Way' || wayValue === 'one' || wayValue === '1way') {
                            wayValue = 'one-way';
                        }
                        waySelect.value = wayValue;
                        console.log('Set way to:', wayValue);
                    }
                    
                    const typeSelect = document.getElementById('restaurantTransferType');
                    if (typeSelect && tInfo.type) {
                        // Normalize type value
                        let typeValue = tInfo.type;
                        if (typeValue === 'P' || typeValue === 'private' || typeValue === 'Private') {
                            typeValue = 'P';
                        } else if (typeValue === 'S' || typeValue === 'sic' || typeValue === 'Shared') {
                            typeValue = 'S';
                        }
                        typeSelect.value = typeValue;
                        console.log('Set type to:', typeValue);
                    }
                } else {
                    console.warn('No transfer info found for meal');
                }
            } else {
                console.log('No transfer data for this meal');
                // Ensure checkbox is unchecked and section is hidden when no transfer
                if (restaurantTransferCheckbox) {
                    restaurantTransferCheckbox.checked = false;
                }
                if (restaurantTransferDetailsSection) {
                    restaurantTransferDetailsSection.style.display = 'none';
                }
                // Clear transfer form fields if no transfer data exists
                resetRestaurantTransferFields();
            }
            
            // Populate restaurant guide section if guide exists
            const restaurantGuideCheckbox = document.getElementById('restaurantGuideCheckbox');
            const restaurantGuideDetailsSection = document.getElementById('restaurantGuideDetailsSection');
            
            if (meal.guideId || meal.guideInfo || meal.guide_options) {
                console.log('=== Populating Guide Section for Edit ===');
                console.log('Guide data:', meal.guideInfo || meal.guide_options);
                
                if (restaurantGuideCheckbox) {
                    restaurantGuideCheckbox.checked = true;
                    // Just show the section directly
                    if (restaurantGuideDetailsSection) {
                        restaurantGuideDetailsSection.style.display = 'block';
                    }
                }
                
                await new Promise(resolve => setTimeout(resolve, 100));
                
                const guideSelect = document.getElementById('restaurantGuideSelect');
                const hoursSelect = document.getElementById('restaurantGuideHours');
                const adultQtyInput = document.getElementById('restaurantGuideAdultQty');
                const childQtyInput = document.getElementById('restaurantGuideChildQty');
                
                // Get guide info - prioritize guideInfo or guide_options from meal, then lookup from guideList
                let guideInfo = null;
                if (meal.guideInfo && Object.keys(meal.guideInfo).length > 0) {
                    guideInfo = meal.guideInfo;
                } else if (meal.guide_options && Object.keys(meal.guide_options).length > 0) {
                    guideInfo = meal.guide_options;
                } else if (meal.guideId) {
                    // Find guide entry in guideList to get actual guide ID and hours
                    const guideEntry = guideList.find(g => String(g.id) === String(meal.guideId));
                    if (guideEntry) {
                        guideInfo = guideEntry;
                    }
                }
                
                if (guideSelect && guideInfo) {
                    // Use guideId from guideInfo (could be guideId or guide_id)
                    const guideIdToUse = guideInfo.guideId || guideInfo.guide_id || meal.guideId;
                    guideSelect.value = guideIdToUse;
                    console.log('Set guide to:', guideIdToUse);
                    
                    if (hoursSelect && guideInfo.hours) {
                        hoursSelect.value = guideInfo.hours;
                        console.log('Set hours to:', guideInfo.hours);
                    }
                    
                    if (adultQtyInput && guideInfo.adultsQty !== undefined) {
                        adultQtyInput.value = guideInfo.adultsQty || guideInfo.adults_qty || 0;
                    }
                    
                    if (childQtyInput && guideInfo.childQty !== undefined) {
                        childQtyInput.value = guideInfo.childQty || guideInfo.child_qty || 0;
                    }
                    
                    updateRestaurantGuidePricing(); // Update pricing based on hours
                } else if (guideSelect && meal.guideId) {
                    // Fallback: try using meal.guideId directly (might be actual guide ID)
                    guideSelect.value = meal.guideId;
                    console.log('Set guide to (fallback):', meal.guideId);
                }
            } else {
                console.log('No guide data for this meal');
                // Ensure checkbox is unchecked and section is hidden when no guide
                if (restaurantGuideCheckbox) {
                    restaurantGuideCheckbox.checked = false;
                }
                if (restaurantGuideDetailsSection) {
                    restaurantGuideDetailsSection.style.display = 'none';
                }
                const rgFocClr = document.getElementById('restaurantGuideFocServiceDiscount');
                if (rgFocClr) rgFocClr.checked = false;
            }
        } else {
            // If no restaurant ID, just try to populate what we can
            populateMealFormForEdit(meal);
        }
        
        const linkedXferFocEdit = meal.transferId ? transferList.find(t => String(t.id) === String(meal.transferId)) : null;
        const rtFocEdit = document.getElementById('restaurantTransferFocServiceDiscount');
        if (rtFocEdit) {
            rtFocEdit.checked = enquiryProIsFocDiscountOn(linkedXferFocEdit || meal.transfer_options || meal.transferInfo);
        }
        const linkedGuideFocEdit = meal.guideId ? guideList.find(g => String(g.id) === String(meal.guideId)) : null;
        const rgFocEdit = document.getElementById('restaurantGuideFocServiceDiscount');
        if (rgFocEdit) {
            rgFocEdit.checked = enquiryProIsFocDiscountOn(linkedGuideFocEdit || meal.guide_options || meal.guideInfo);
        }
        
        document.getElementById('mealModalTitleText').textContent = 'Edit Meal / Restaurant';
        const saveMealBtn = document.getElementById('saveMealBtnText');
        if (saveMealBtn) saveMealBtn.textContent = 'Update Meal';
        
        const mealModal = new bootstrap.Modal(document.getElementById('mealModal'));
        mealModal.show();
    }
    
    // Helper function to fill meal row values
    function fillMealRowValues(row, mealId, meal) {
        const setVal = (selector, value) => {
            const el = row.querySelector(`${selector}[data-meal-id="${mealId}"]`);
            if (el) el.value = value ?? el.value;
        };
        
        setVal('.meal-count', meal.mealCount);
        setVal('.meal-adult-qty', meal.adultsQty);
        setVal('.meal-adult-cost', parseFloat(String(meal.adultCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        setVal('.meal-adult-sell', parseFloat(String(meal.adultSell || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        setVal('.meal-child-qty', meal.childQty);
        setVal('.meal-child-cost', parseFloat(String(meal.childCost || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        setVal('.meal-child-sell', parseFloat(String(meal.childSell || 0).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        setVal('.meal-infant-qty', meal.infantQty);
        const infantCostOnly = meal.infantCost ?? meal.infant_cost ?? 0;
        const infantSellOnly = meal.infantSell ?? meal.infant_sell ?? infantCostOnly;
        setVal('.meal-infant-cost', parseFloat(String(infantCostOnly).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        setVal('.meal-infant-sell', parseFloat(String(infantSellOnly).replace(/[^0-9.-]/g, '') || 0).toFixed(2));
        const mfoc = row.querySelector(`.meal-foc-discount[data-meal-id="${mealId}"]`);
        if (mfoc) mfoc.checked = enquiryProIsFocDiscountOn(meal);
    }
    
    // Helper function to populate meal form fields for editing
    function populateMealFormForEdit(meal) {
        console.log('populateMealFormForEdit called with meal:', meal);
        console.log('Looking for mealId:', meal.mealId, 'mealName:', meal.mealName);
        
        // When editing a single meal entry (clicked row), show only that meal type selected.
        // Match by mealId only so we don't check multiple rows that share the same mealName (e.g. two "Breakfast" types).
        const relatedMeals = [meal];
        
        console.log('Related meals to check (single entry):', relatedMeals.map(m => ({ id: m.id, mealName: m.mealName, mealId: m.mealId, mealType: m.mealType })));
        
        // Find matching meal row (by mealId or meal name)
        const rows = Array.from(document.querySelectorAll('.meal-row'));
        console.log('Available meal rows:', rows.length);
        
        const targetRow = rows.find(r => {
            const rowMealId = r.getAttribute('data-meal-id');
            const rowName = r.getAttribute('data-meal-name');
            return (meal.mealId && String(meal.mealId) === String(rowMealId)) || 
                   (meal.mealName && meal.mealName === rowName);
        });
        
        // If no matching row exists, create one dynamically
        let rowToUse = targetRow;
        if (!rowToUse) {
            rowToUse = ensureMealRowForEdit(meal);
        }
        
        // If still no row (e.g. meals still loading), retry once after short delay
        if (!rowToUse) {
            setTimeout(() => {
                const retryRows = Array.from(document.querySelectorAll('.meal-row'));
                document.querySelectorAll('.meal-checkbox').forEach(cb => cb.checked = false);
                const matchingRow = retryRows.find(r => meal.mealId != null && String(meal.mealId) === String(r.getAttribute('data-meal-id')));
                if (matchingRow) {
                    const rowMealId = matchingRow.getAttribute('data-meal-id');
                    const checkbox = matchingRow.querySelector(`.meal-checkbox[data-meal-id="${rowMealId}"]`);
                    if (checkbox) {
                        checkbox.checked = true;
                        fillMealRowValues(matchingRow, rowMealId, meal);
                    }
                    matchingRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }, 500);
            return;
        }
        
        // Reset all checkboxes first
        document.querySelectorAll('.meal-checkbox').forEach(cb => cb.checked = false);
        
        // Check only the one row that matches this meal's mealId (exact match - one meal type only)
        rows.forEach(r => {
            const rowMealId = r.getAttribute('data-meal-id');
            
            // Match by mealId only so only the exact meal type row is checked
            const matchingRelatedMeal = relatedMeals.find(relMeal => 
                relMeal.mealId != null && String(relMeal.mealId) === String(rowMealId)
            );
            
            if (matchingRelatedMeal) {
                const checkbox = r.querySelector(`.meal-checkbox[data-meal-id="${rowMealId}"]`);
                if (checkbox) {
                    checkbox.checked = true;
                    console.log('Checked meal row for edit:', rowMealId, matchingRelatedMeal.mealName || matchingRelatedMeal.mealType);
                    fillMealRowValues(r, rowMealId, matchingRelatedMeal);
                }
            }
        });
        
        // Scroll the primary row into view
        if (rowToUse) {
            rowToUse.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            console.warn('populateMealFormForEdit: no matching meal row found for', meal.mealName || meal.mealId);
        }
    }
    
    // Update meal field
    function updateMealField(index, field, value) {
        if (mealList[index]) {
            const meal = mealList[index];
            meal[field] = value;
            
            // If supplement is changed, do NOT sync with linked services
            
            // If dateTime is changed, sync with linked transfer, guide, and expand header dates
            if (field === 'dateTime' && value) {
                if (meal.transferId) {
                    const transferIndex = transferList.findIndex(t => t.id === meal.transferId);
                    if (transferIndex !== -1) {
                        transferList[transferIndex].dateTime = value;
                        updateTransferTable();
                    }
                }
                
                // Also update linked guide if exists
                if (meal.guideId) {
                    const guideIndex = guideList.findIndex(g => g.id === meal.guideId);
                    if (guideIndex !== -1) {
                        guideList[guideIndex].dateTime = value;
                        updateGuideTable();
                    }
                }
                
                // Expand header dates
                expandHeaderDatesIfNeeded(value, false);
            }
        }
    }
    
    // Update meal supplement - do NOT sync with linked services
    function updateMealSupplement(index, checked) {
        if (mealList[index]) {
            const meal = mealList[index];
            meal.supplement = checked;
            
            // Recalculate totals after supplement change
            recalculateTotals();
        }
    }
    
    // Toggle select all meals (main table)
    function toggleSelectAllMealsMain() {
        const selectAll = document.getElementById('selectAllMealsMain');
        const checkboxes = document.querySelectorAll('.meal-checkbox');
        checkboxes.forEach(cb => cb.checked = selectAll.checked);
    }
    
    // Remove selected meals
    function removeSelectedMeals() {
        const checkboxes = document.querySelectorAll('.meal-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select meals to remove');
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        const existingIdsToRemove = idsToRemove.filter(id => {
            const item = mealList.find(m => String(m.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        const hasExistingItems = idsToRemove.some(id => {
            const item = mealList.find(m => String(m.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        
        const count = checkboxes.length;
        const itemLabel = count === 1 ? 'meal' : 'meals';
        showRemoveFormSelectionAlert(count, itemLabel, () => {
            const snapshotBefore = snapshotAllServiceState();
            mealList.forEach(meal => {
                if (idsToRemove.includes(String(meal.id))) {
                    if (meal.transferId) {
                        transferList = transferList.filter(t => String(t.id) !== String(meal.transferId));
                    }
                    if (meal.guideId) {
                        guideList = guideList.filter(g => String(g.id) !== String(meal.guideId));
                    }
                }
            });
            
            mealList = mealList.filter(meal => !idsToRemove.includes(String(meal.id)));
            
            updateMealTable();
            updateTransferTable();
            updateGuideTable();
            recalculateHeaderDatesFromServices();
            recalculateTotals();
            scheduleRemoveWithUndo({
                categoryKey: 'meals',
                serviceMessage: 'Meal service',
                existingIds: existingIdsToRemove,
                snapshotBefore
            });
        }, window.hasNegotiationHistory, hasExistingItems);
    }

    // ==================== TRANSFER FUNCTIONS ====================
    
    // Update transfer table - displays all transfers from tours and meals
    function updateTransferTable() {
        console.log('=== UPDATE TRANSFER TABLE ===');
        console.log('Total transfers:', transferList.length);
        if (transferList.length > 0) {
            console.log('Sample transfer:', transferList[0]);
        }
        
        const tbody = document.getElementById('transferTableBody');
        const table = document.getElementById('transferTable');
        const emptyMessage = document.getElementById('emptyTransferMessage');
        
        if (transferList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        // Helper function to get transport mode icon
        const getModeIcon = (mode) => {
            const icons = {
                'local': '<i class="ri-car-line" style="font-size: 16px;" title="Local Transfer"></i>',
                'flight': '<i class="ri-flight-takeoff-line" style="font-size: 16px;" title="Flight"></i>',
                'cruise': '<i class="ri-ship-line" style="font-size: 16px;" title="Cruise"></i>',
                'train': '<i class="ri-train-line" style="font-size: 16px;" title="Train"></i>',
                'bus': '<i class="ri-bus-line" style="font-size: 16px;" title="Bus"></i>'
            };
            return icons[mode] || icons['local'];
        };
        
        // Helper function to get destination display text
        const getDestinationText = (transfer) => {
            // Check if this is a hotel transfer (has hotelName)
            if (transfer.hotelName) {
                return `${transfer.hotelName} / ${transfer.hotelDestination || transfer.destination || ''}`;
            }
            
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                return transfer.destination || (transfer.pickup ? transfer.pickup + ' → ' + transfer.drop : '-');
            } else {
                // For flight, train, bus, cruise
                return (transfer.departFrom || '') + (transfer.destination ? ' → ' + transfer.destination : (transfer.arrivalTo ? ' → ' + transfer.arrivalTo : ''));
            }
        };
        
        // Helper function to get vehicle/transport type
        const getVehicleType = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                // Base label: vehicle name if available, otherwise vehicle type
                let label = '-';
                if (transfer.vehicleName && transfer.vehicleName !== '-') {
                    label = transfer.vehicleName;
                } else {
                    const vehicleType = transfer.vehicleType || '-';
                    if (vehicleType !== '-') {
                        label = vehicleType.charAt(0).toUpperCase() + vehicleType.slice(1);
                    }
                }
                
                if (label === '-') return '-';
                
                // Append seating capacity when available (e.g. "Jeep (6 seats)")
                // Guard: don't append if label already contains "(N seats)" to avoid duplication
                const capacity = parseInt(transfer.capacity || transfer.seatingCapacity || transfer.seats || 0);
                if (capacity > 0 && !/\(\d+ seats\)/i.test(label)) {
                    return `${label} (${capacity} seats)`;
                }
                return label;
            } else if (mode === 'flight') {
                return transfer.airline || transfer.operator || '-';
            } else if (mode === 'cruise') {
                return transfer.vessel || transfer.by || '-';
            } else if (mode === 'train' || mode === 'bus') {
                return transfer.operator || '-';
            }
            return '-';
        };
        
        // Helper function to get type/class (Private/Shared from type OR transferType per JSON)
        const getTypeClass = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                return transferServiceTypeDisplayLabel(transfer);
            } else {
                return transfer.class || transfer.cabinClass || '-';
            }
        };
        
        // Helper function to get way/trip type
        const getWayType = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                const way = transfer.way || '-';
                if (way === '-') return '-';
                // Format the way properly
                if (way === 'one-way') return 'One Way';
                if (way === 'both-way') return 'Both Way';
                return way;
            } else {
                return transfer.tripType || '-';
            }
        };
        
        tbody.innerHTML = transferList.map((transfer, index) => {
            console.log(`Rendering transfer ${index}:`, {
                vehicleType: transfer.vehicleType,
                vehicleName: transfer.vehicleName,
                type: transfer.type,
                way: transfer.way,
                cost: transfer.cost,
                sell: transfer.sell,
                zonePrivatePrice: transfer.zonePrivatePrice,
                zoneSharedPrice: transfer.zoneSharedPrice
            });
            
            // Determine display name based on source
            let displayName = '';
            
            // Detect arrival/departure transfers so we can show labels like \"Arrival:\" / \"Departure:\"
            const isArrival = transfer.sourceType === 'arrival' || transfer.sourceType === 'Arrival' ||
                (transfer.destination && String(transfer.destination).indexOf('Arrival:') === 0) ||
                (transfer.service && String(transfer.service).indexOf('Arrival:') === 0);
            const isDeparture = transfer.sourceType === 'departure' || transfer.sourceType === 'Departure' ||
                (transfer.destination && String(transfer.destination).indexOf('Departure:') === 0) ||
                (transfer.service && String(transfer.service).indexOf('Departure:') === 0);
            const isArrivalOrDeparture = isArrival || isDeparture;
            
            // For Arrival/Departure, prefer the destination/service text which already includes the label
            if (isArrivalOrDeparture && transfer.destination && (String(transfer.destination).indexOf('Arrival:') === 0 || String(transfer.destination).indexOf('Departure:') === 0)) {
                displayName = transfer.destination;
            } else if (isArrivalOrDeparture && transfer.service && (String(transfer.service).indexOf('Arrival:') === 0 || String(transfer.service).indexOf('Departure:') === 0)) {
                displayName = transfer.service;
            } else if (transfer.pickupName && transfer.dropName) {
                // General case: pickup → drop
                displayName = `${transfer.pickupName} → ${transfer.dropName}`;
            } else if (transfer.pickup && transfer.dropoff) {
                displayName = `${transfer.pickup} → ${transfer.dropoff}`;
            } else if (transfer.isStandalone) {
                // For standalone transfers, show destination or pickup → drop
                displayName = transfer.destination || `${transfer.pickupName || transfer.pickup || '-'} → ${transfer.dropName || transfer.dropoff || '-'}`;
            } else if (transfer.hotelName) {
                // For hotel transfers without pickup/dropoff, show hotel name with destination
                if (transfer.hotelDestination) {
                    displayName = `${transfer.hotelName} / ${transfer.hotelDestination}`;
                } else if (transfer.destination) {
                    displayName = `${transfer.hotelName} / ${transfer.destination}`;
                } else {
                    displayName = transfer.hotelName;
                }
            } else if (transfer.service) {
                // For other services with service field
                displayName = transfer.service;
            } else if (transfer.destination) {
                // For attraction/restaurant transfers - show the destination name
                displayName = transfer.destination;
            } else {
                // For transfers from other services (fallback)
                displayName = transfer.portName || '-';
            }
            
            // Ensure dateTime has time component, if not add default time 09:00
            let dateTimeValue = transfer.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T09:00';
            }
            
            // Show checkbox for all transfers (both standalone and linked)
            const checkboxHtml = `<input type="checkbox" class="transfer-checkbox" value="${transfer.id}">`;
            
            // Make service name clickable for both standalone and linked transfers
            const serviceHtml = `<a href="javascript:void(0)" onclick="editTransfer(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">${displayName || '-'}</a>`;
            
            // Get adult and child values - support both field name formats
            const adults = transfer.adults || transfer.adultsQty || 0;
            const child = transfer.child || transfer.childQty || 0;
            
            // Determine supplement checkbox display - show checkbox for linked transfers too
            const supplementCheckboxHtml = transfer.isStandalone 
                ? `<input type="checkbox" ${transfer.supplement ? 'checked' : ''} onchange="updateTransferSupplement(${index}, this.checked)">`
                : `<input type="checkbox" ${transfer.supplement ? 'checked' : ''} onchange="updateTransferSupplement(${index}, this.checked)" style="opacity: 0.7;">`;
            
            // Display cost/sell: use base price (same as create form - shared/private oneway/both-way, not × pax)
            // Prefer basePrice/base_price from loaded JSON so edit matches create form
            const storedSell = parseFloat(transfer.sell || 0);
            const storedCost = parseFloat(transfer.cost || 0);
            const storedBase = parseFloat(transfer.basePrice || transfer.base_price || 0);
            let displayCost = storedBase > 0 ? storedBase : storedCost;
            let displaySell = storedBase > 0 ? storedBase : (storedSell > 0 ? storedSell : storedCost);
            
            // Get current type and way for dropdowns (honour transferType from API as well as type)
            const currentType = transferServiceRawToPS(transfer);
            const currentWay = transfer.way || 'one-way';
            
            // Create type dropdown (only for local transfers; read-only for Arrival/Departure)
            const typeDropdown = (transfer.transportMode === 'local' || !transfer.transportMode) && !isArrivalOrDeparture
                ? `<select onchange="updateTransferField(${index}, 'type', this.value)" style="width: 70px; font-size: 11px; padding: 2px 4px;">
                    <option value="S" ${currentType === 'S' ? 'selected' : ''}>Shared</option>
                    <option value="P" ${currentType === 'P' ? 'selected' : ''}>Private</option>
                   </select>`
                : getTypeClass(transfer);
            
            // Create way dropdown (only for local transfers; read-only for Arrival/Departure)
            const wayDropdown = (transfer.transportMode === 'local' || !transfer.transportMode) && !isArrivalOrDeparture
                ? `<select onchange="updateTransferField(${index}, 'way', this.value)" style="width: 80px; font-size: 11px; padding: 2px 4px;">
                    <option value="one-way" ${(currentWay === 'one-way' || currentWay === 'One Way') ? 'selected' : ''}>One Way</option>
                    <option value="both-way" ${(currentWay === 'both-way' || currentWay === 'Both Way' || currentWay === 'both' || currentWay === 'two-way' || currentWay === 'return' || currentWay === '2way') ? 'selected' : ''}>Both Way</option>
                   </select>`
                : getWayType(transfer);
            
            return `
            <tr>
                <td>${checkboxHtml}</td>
                <td><input type="datetime-local" value="${dateTimeValue}" onchange="updateTransferField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;"></td>
                <td>
                    ${serviceHtml}
                </td>
                <td>${getModeIcon(transfer.transportMode || 'local')}</td>
                <td>${getVehicleType(transfer)}</td>
                <td>${typeDropdown}</td>
                <td>${wayDropdown}</td>
                <td><input type="number" value="${adults}" onchange="updateTransferField(${index}, 'adults', this.value)" style="width: 50px;"></td>
                <td><input type="number" value="${child}" onchange="updateTransferField(${index}, 'child', this.value)" style="width: 50px;"></td>
                <td><input type="text" value="${displayCost}" readonly style="width: 70px; background-color: #f5f5f5;"></td>
                <td><input type="number" value="${displaySell}" onchange="updateTransferField(${index}, 'sell', this.value)" step="1" style="width: 70px;"></td>
                <td style="text-align: center;">${supplementCheckboxHtml}</td>
            </tr>
        `;
        }).join('');

        // Ensure footer totals refresh whenever transfer table renders
        recalculateTotals();
    }
    
    // Update transfer field
    async function updateTransferField(index, field, value) {
        if (transferList[index]) {
            const transfer = transferList[index];
            transfer[field] = value;
            
            // Also update alternate field names for consistency
            if (field === 'adults') {
                transfer.adultsQty = value;
            } else if (field === 'child') {
                transfer.childQty = value;
            } else if (field === 'type') {
                transfer.transferType = value;
            }
            
            // If dateTime field is changed, expand header dates and sync to linked services and guides
            if (field === 'dateTime' && value) {
                expandHeaderDatesIfNeeded(value, false);
                const srcType = (transfer.sourceType || '').toLowerCase();
                if (srcType === 'arrival' || srcType === 'departure') {
                    const arrDepIndex = arrivalDepartureList.findIndex(item => 
                        (item.transferId === transfer.id || item.id === transfer.sourceId) &&
                        ((srcType === 'arrival' && (item.type === 'Arrival' || item.type === 'arrival')) ||
                         (srcType === 'departure' && (item.type === 'Departure' || item.type === 'departure')))
                    );
                    if (arrDepIndex !== -1) {
                        arrivalDepartureList[arrDepIndex].dateTime = value;
                        const item = arrivalDepartureList[arrDepIndex];
                        if (item.guideId) {
                            const gIdx = guideList.findIndex(g => String(g.id) === String(item.guideId));
                            if (gIdx !== -1) {
                                guideList[gIdx].dateTime = value;
                                if (typeof updateGuideTable === 'function') updateGuideTable();
                            }
                        }
                        if (typeof updateArrivalDepartureTable === 'function') updateArrivalDepartureTable();
                    }
                } else if (srcType === 'tour' || srcType === 'attraction') {
                    // Sync to linked attraction/tour service
                    const tourIndex = tourList.findIndex(t =>
                        t.transferId === transfer.id || String(t.id) === String(transfer.sourceId)
                    );
                    if (tourIndex !== -1) {
                        tourList[tourIndex].dateTime = value;
                        if (typeof updateTourTable === 'function') updateTourTable();
                        // Also update linked guide
                        if (tourList[tourIndex].guideId) {
                            const gIdx = guideList.findIndex(g => String(g.id) === String(tourList[tourIndex].guideId));
                            if (gIdx !== -1) {
                                guideList[gIdx].dateTime = value;
                                if (typeof updateGuideTable === 'function') updateGuideTable();
                            }
                        }
                        console.log('Synced transfer date to linked tour and guide:', value);
                    }
                } else if (srcType === 'meal' || srcType === 'restaurant') {
                    // Sync to linked restaurant/meal service
                    const mealIndex = mealList.findIndex(m =>
                        m.transferId === transfer.id || String(m.id) === String(transfer.sourceId)
                    );
                    if (mealIndex !== -1) {
                        mealList[mealIndex].dateTime = value;
                        if (typeof updateMealTable === 'function') updateMealTable();
                        // Also update linked guide
                        if (mealList[mealIndex].guideId) {
                            const gIdx = guideList.findIndex(g => String(g.id) === String(mealList[mealIndex].guideId));
                            if (gIdx !== -1) {
                                guideList[gIdx].dateTime = value;
                                if (typeof updateGuideTable === 'function') updateGuideTable();
                            }
                        }
                        console.log('Synced transfer date to linked meal and guide:', value);
                    }
                }
                updateTransferTable();
            }
            
            // If type or way changes for local transfers, recalculate cost/sell based on zone prices
            if ((field === 'type' || field === 'way') && transfer.transportMode === 'local') {
                let zonePrivatePrice = parseFloat(transfer.zonePrivatePrice) || 0;
                let zoneSharedPrice = parseFloat(transfer.zoneSharedPrice) || 0;
                
                // If zone prices are missing (e.g. older bookings), try to fetch them so price can update
                if (zonePrivatePrice === 0 && zoneSharedPrice === 0 && transfer.vehicleId && (transfer.pickupId || transfer.fromZoneId) && (transfer.dropId || transfer.toZoneId)) {
                    const dmcId = '{{ $dmc_id ?? "" }}';
                    const pickupIdForFetch = transfer.pickupId || transfer.fromZoneId || '';
                    const dropIdForFetch = transfer.dropId || transfer.toZoneId || '';
                    const pickupTypeForFetch = transfer.pickupType || 'hotel';
                    const dropTypeForFetch = transfer.dropType || 'hotel';
                    try {
                        const zonePrice = await fetchZonePrice(transfer.vehicleId, pickupIdForFetch, pickupTypeForFetch, dropIdForFetch, dropTypeForFetch, dmcId);
                        zonePrivatePrice = parseFloat(zonePrice.private_price) || 0;
                        zoneSharedPrice = parseFloat(zonePrice.shared_price) || 0;
                        if (zonePrivatePrice > 0 || zoneSharedPrice > 0) {
                            transfer.zonePrivatePrice = zonePrivatePrice;
                            transfer.zoneSharedPrice = zoneSharedPrice;
                            console.log('Fetched zone prices for transfer type/way change:', { zonePrivatePrice, zoneSharedPrice });
                        }
                    } catch (err) {
                        console.warn('Could not fetch zone price for transfer recalculation:', err);
                    }
                }
                
                // If we still don't have any zone prices, keep existing cost/sell (do not overwrite with 0)
                if (zonePrivatePrice === 0 && zoneSharedPrice === 0) {
                    console.warn('Skipping automatic transfer price recalculation because zone prices are missing.', {
                        index,
                        transferId: transfer.id,
                        existingCost: transfer.cost,
                        existingSell: transfer.sell
                    });
                    updateTransferTable();
                    if ((field === 'sell' || field === 'adults' || field === 'child' || field === 'type' || field === 'way') && transfer.transportMode === 'local') {
                        recalculateTotals();
                    }
                    return;
                }
                
                // Get current type and way
                const currentType = transfer.type || 'P';
                const currentWay = transfer.way || 'one-way';
                
                // Get base price based on type (shared or private)
                let basePrice = 0;
                if (currentType === 'S' || currentType === 'sic' || currentType === 'Shared') {
                    basePrice = zoneSharedPrice;
                } else {
                    basePrice = zonePrivatePrice;
                }
                
                // Apply way multiplier - both-way costs double
                const isBothway = currentWay === 'both-way' || currentWay === 'Both Way' || 
                                  currentWay === 'both' || currentWay === 'two-way' || currentWay === 'return' || currentWay === '2way';
                const wayMultiplier = isBothway ? 2 : 1;
                
                // Update cost and sell with new calculated values
                transfer.cost = basePrice * wayMultiplier;
                transfer.sell = basePrice * wayMultiplier;
                
                console.log('Recalculated transfer price:', {
                    type: currentType,
                    way: currentWay,
                    basePrice: basePrice,
                    wayMultiplier: wayMultiplier,
                    newCost: transfer.cost,
                    newSell: transfer.sell
                });
                
                // Refresh the transfer table to show new prices
                updateTransferTable();
            }
            
            // If sell price, adults, child, type, or way changes for local transfers, recalculate totals
            // This ensures Package Total is updated with new transfer contributions
            if ((field === 'sell' || field === 'adults' || field === 'child' || field === 'type' || field === 'way') && 
                transfer.transportMode === 'local') {
                recalculateTotals();
            }
        }
    }
    
    // Update transfer supplement checkbox
