            } else {
                console.log('  Drop is', actualDropType.toUpperCase(), '- zone_id will be extracted from zone_assignments for DMC:', dmcId);
            }
            
            // Query vehicle_zone_mappings directly for prices
            // Query: vehicle_id, (from_zone_id = pickupid AND to_zone_id = dropid) OR (from_zone_id = dropid AND to_zone_id = pickupid)
            // Also includes from_zone_type and to_zone_type to match SingleTourPackageController logic
            const apiUrl = `{{ route('enquiry-form-pro.get-zone-prices') }}?vehicle_id=${encodeURIComponent(vehicleId)}&pickup_id=${encodeURIComponent(actualPickupId)}&drop_id=${encodeURIComponent(actualDropId)}&pickup_type=${encodeURIComponent(actualPickupType)}&drop_type=${encodeURIComponent(actualDropType)}`;
            console.log('API URL:', apiUrl);
            console.log('Querying vehicle_zone_mappings with:');
            console.log('  vehicle_id:', vehicleId);
            console.log('  pickup_id (from_zone_id):', actualPickupId);
            console.log('  drop_id (to_zone_id):', actualDropId);
            console.log('  pickup_type (from_zone_type):', actualPickupType);
            console.log('  drop_type (to_zone_type):', actualDropType);
            
            const response = await fetch(apiUrl, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
                }
            });
            
            if (!response.ok) {
                console.error('API request failed:', response.status, response.statusText);
                const errorText = await response.text();
                console.error('Error response:', errorText);
                return { private_price: 0, shared_price: 0 };
            }
            
            // Check if response is JSON before parsing
            const contentType = response.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                console.error('Server returned non-JSON response:', contentType);
                return { private_price: 0, shared_price: 0 };
            }
            
            const result = await response.json();
            console.log('API Response:', result);
            
            // Handle case where API returns error message
            if (!result.success) {
                console.warn('API returned error message:', result.message);
                
                // Log warning but don't throw error - allow zero prices
                const errorMsg = result.message || 'Zone mapping not found';
                console.warn('⚠️ ZONE MAPPING WARNING:', errorMsg);
                console.warn('   Pickup Type:', actualPickupType, 'ID:', actualPickupId);
                console.warn('   Drop Type:', actualDropType, 'ID:', actualDropId);
                console.warn('   Vehicle ID:', vehicleId);
                console.warn('   Continuing with zero prices...');
                
                // Return zero prices instead of throwing error
                return { private_price: 0, shared_price: 0 };
            }
            
            // Extract prices from the response
            const privatePrice = parseFloat(result.data?.private_price || 0);
            const sharedPrice = parseFloat(result.data?.shared_price || 0);
            
            console.log('Extracted prices from vehicle_zone_mappings:');
            console.log('  private_price:', privatePrice);
            console.log('  shared_price:', sharedPrice);
            console.log('=== FETCH ZONE PRICE DEBUG END ===');
            
            return {
                private_price: privatePrice,
                shared_price: sharedPrice
            };
        } catch (error) {
            console.error('Error fetching zone price:', error);
            console.error('Error stack:', error.stack);
            console.log('=== FETCH ZONE PRICE DEBUG END ===');
            
            // Re-throw zone mapping errors to stop the save process
            if (error.message && error.message.includes('Zone mapping missing')) {
                throw error;
            }
            
            // For other errors, return zero prices (network errors, etc.)
            return { private_price: 0, shared_price: 0 };
        }
    }
    
    // Calculate transfer price based on type and way (UI price only)
    function calculateTransferPrice(zonePrice, type, way, adults, child, vehicleOption = null) {
        // Get zone prices
        let zonePrivatePrice = zonePrice.private_price || 0;
        let zoneSharedPrice = zonePrice.shared_price || 0;
        
        // DO NOT fall back to vehicle base prices if zone mapping is missing
        // Zone prices should remain 0 to indicate missing mapping
        // User must either: 1) Add zone mapping in settings, or 2) Manually enter prices
        
        // Calculate base price based on type
        // Shared: per person price (per way), Private: per vehicle price (per way)
        let basePrice = 0;
        
        if (type === 'S' || type === 'sic' || type === 'Shared') {
            // Shared: per person price (do NOT multiply by pax here)
            basePrice = zoneSharedPrice || 0;
        } else {
            // Private: fixed per-vehicle price
            basePrice = zonePrivatePrice || 0;
        }
        
        // Apply way multiplier - both-way costs double
        const isBothway = way === 'both-way' || way === 'Both Way' || 
                          way === 'both' || way === 'two-way' || way === 'return' || way === '2way';
        const wayMultiplier = isBothway ? 2 : 1;
        
        // Final price includes way multiplier
        let costPrice = basePrice * wayMultiplier;
        let sellPrice = basePrice * wayMultiplier;
        
        return {
            cost: costPrice,
            sell: sellPrice,
            basePrice: basePrice,
            sharedPrice: zoneSharedPrice,
            privatePrice: zonePrivatePrice,
            totalPax: Math.max(1, (parseInt(adults) || 0) + (parseInt(child) || 0))
        };
    }
    
    // Save Transfer Package
    async function saveTransferPackage() {
        // Get selected transport mode
        const transportModeRadio = document.querySelector('input[name="transferMode"]:checked');
        const transportMode = transportModeRadio ? transportModeRadio.value : 'local';
        
    let transferData = {
        id: generateId('transfer'),
            transportMode: transportMode,
            isStandalone: true
        };
        
        // Collect data based on transport mode
        if (transportMode === 'local') {
            const dateTime = document.getElementById('localDateTime').value;
            const pickupSelect = document.getElementById('localPickup');
            const dropSelect = document.getElementById('localDrop');
            
            if (!dateTime) {
                alert('Please select date/time');
                return;
            }
            if (!pickupSelect.value || !dropSelect.value) {
                alert('Please select both pickup and drop locations');
                return;
            }
            
            // Use jQuery to get selected option data (works with Select2)
            const pickupOption = $('#localPickup').find(':selected');
            const dropOption = $('#localDrop').find(':selected');
            
            const pickupName = pickupOption.attr('data-name') || pickupOption.text() || '';
            const dropName = dropOption.attr('data-name') || dropOption.text() || '';
            const pickupType = pickupOption.attr('data-type') || '';
            const dropType = dropOption.attr('data-type') || '';
            
            // Get vehicle ID, type, and name
            const vehicleSelect = document.getElementById('localVehicleType');
            const vehicleId = vehicleSelect.value;
            const vehicleOption = vehicleSelect.selectedOptions[0];
            const vehicleType = vehicleOption?.getAttribute('data-type') || '';
            const vehicleName = (vehicleOption?.text || '').replace(/\s*\(\d+ seats\)\s*$/i, '').trim();
            
            const type = document.getElementById('localType').value;
            const way = document.getElementById('localWay').value;
            const adults = parseInt(document.getElementById('localAdults').value) || 0;
            const child = parseInt(document.getElementById('localChild').value) || 0;
            
            console.log('=== SAVE LOCAL TRANSFER DEBUG ===');
            console.log('Vehicle:', { vehicleId, vehicleType, vehicleName });
            console.log('Type:', type, 'Way:', way, 'Adults:', adults, 'Child:', child);
            console.log('Pickup:', { id: pickupSelect.value, type: pickupType, name: pickupName });
            console.log('Dropoff:', { id: dropSelect.value, type: dropType, name: dropName });
            
            // Fetch zone price
            const dmcId = '{{ $dmc_id ?? "" }}';
            let zonePrice;
            try {
                zonePrice = await fetchZonePrice(vehicleId, pickupSelect.value, pickupType, dropSelect.value, dropType, dmcId);
                console.log('Zone prices fetched:', zonePrice);
            } catch (error) {
                console.error('Failed to fetch zone price:', error.message);
                // Stop the save process and return early
                return;
            }
            
            // Calculate prices with vehicle option for fallback to base prices
            const prices = calculateTransferPrice(zonePrice, type, way, adults, child, vehicleOption);
            
            console.log('Calculated prices:', prices);
            
            transferData = {
                ...transferData,
                dateTime: dateTime,
                pickupId: pickupSelect.value,
                pickupName: pickupName,
                pickup: pickupName, // Add for consistency with transformation
                pickupType: pickupType,
                dropId: dropSelect.value,
                dropName: dropName,
                dropoff: dropName, // Add for consistency with transformation
                dropType: dropType,
                destination: `${pickupName} → ${dropName}`,
                vehicleId: vehicleId,
                vehicleType: vehicleType,
                vehicleName: vehicleName,
                type: type,
                way: way,
                hasTransfer: true,
                adults: adults,
                child: child,
                cost: prices.cost,
                sell: prices.sell,
                zonePrivatePrice: prices.privatePrice,
                zoneSharedPrice: prices.sharedPrice,
                taxIncluded: false
            };
            
            // Get guide info for local transport
            const guideChecked = document.getElementById('localTransportGuideCheckbox')?.checked || false;
            const guideSelect = document.getElementById('localTransportGuideSelect');
            
            // Get adult and child quantities from modal inputs
            const localTransportGuideAdultQty = parseInt(document.getElementById('localTransportGuideAdultQty')?.value || '0') || 0;
            const localTransportGuideChildQty = parseInt(document.getElementById('localTransportGuideChildQty')?.value || '0') || 0;
            
            let guideId = null;
            let guideInfo = null;
            
            if (guideChecked && guideSelect && guideSelect.value) {
                guideId = guideSelect.value;
                const guideOption = guideSelect.selectedOptions[0];
                const hoursSelect = document.getElementById('localTransportGuideHours');
                const hours = parseInt(hoursSelect?.value || '12') || 12;
                
                // Calculate price based on hours
                let price = 0;
                switch(hours) {
                    case 2:
                        price = parseFloat(guideOption?.getAttribute('data-two-hour-price') || '0') || 0;
                        break;
                    case 4:
                        price = parseFloat(guideOption?.getAttribute('data-four-hour-price') || '0') || 0;
                        break;
                    case 6:
                        price = parseFloat(guideOption?.getAttribute('data-six-hour-price') || '0') || 0;
                        break;
                    case 8:
                        price = parseFloat(guideOption?.getAttribute('data-eight-hour-price') || '0') || 0;
                        break;
                    case 10:
                        price = parseFloat(guideOption?.getAttribute('data-ten-hour-price') || '0') || 0;
                        break;
                    case 12:
                    default:
                        price = parseFloat(guideOption?.getAttribute('data-twelve-hour-price') || '0') || 0;
                        break;
                }
                
                guideInfo = {
                    guideId: guideId,
                    guideName: guideOption?.getAttribute('data-name') || guideOption?.text || '',
                    languages: guideOption?.getAttribute('data-languages') || ''
                };
                
                // Handle guide update/removal when editing
                const isEditing = window.editingTransferIndex !== null && window.editingTransferIndex !== undefined;
                if (isEditing) {
                    const oldTransfer = transferList[window.editingTransferIndex];
                    if (oldTransfer && oldTransfer.guideId) {
                        // Remove old guide from guideList
                        guideList = guideList.filter(g => String(g.id) !== String(oldTransfer.guideId));
                    }
                }
                
                // Add guide entry to guideList (with quantity loop)
                const guideEntryId = generateId('guide');
                const localTransportGuideQuantity = parseInt(document.getElementById('localTransportGuideQuantity')?.value || '1') || 1;
                const transferGuideFocSvc = document.getElementById('transferPackageGuideFocDiscount')?.checked === true;
                for (let gq = 0; gq < localTransportGuideQuantity; gq++) {
                    const currentGuideId = gq === 0 ? guideEntryId : generateId('guide');
                    const guideEntry = {
                        id: currentGuideId,
                        dateTime: dateTime,
                        tourActivity: `${pickupName} → ${dropName} (Local Transfer Guide)`,
                        language: guideInfo.languages || 'N/A',
                        guideName: guideInfo.guideName,
                        guideId: guideInfo.guideId,
                        hours: hours,
                        cost: price,
                        sell: price,
                        supplement: false,
                        isStandalone: false,
                        linkedTo: 'local_transport',
                        sourceType: 'transfer',
                        sourceId: transferData.id,
                        adultsQty: localTransportGuideAdultQty,
                        childQty: localTransportGuideChildQty,
                        focServiceDiscount: transferGuideFocSvc
                    };
                    guideList.push(guideEntry);
                }
                transferData.guideId = guideEntryId;
                transferData.guideInfo = guideInfo;
            } else {
                // Guide unchecked, handle removal when editing
                const isEditing = window.editingTransferIndex !== null && window.editingTransferIndex !== undefined;
                if (isEditing) {
                    const oldTransfer = transferList[window.editingTransferIndex];
                    if (oldTransfer && oldTransfer.guideId) {
                        // Remove old guide from guideList
                        guideList = guideList.filter(g => String(g.id) !== String(oldTransfer.guideId));
                    }
                }
                transferData.guideId = null;
                transferData.guideInfo = null;
            }
        } 
        else if (transportMode === 'flight') {
            const departureDate = document.getElementById('flightDepartureDate').value;
            const departFrom = document.getElementById('flightDepartFrom').value;
            const destination = document.getElementById('flightDestination').value;
            
            if (!departureDate || !departFrom || !destination) {
                alert('Please fill in departure date, depart from, and destination');
                return;
            }
            
            transferData = {
                ...transferData,
                dateTime: departureDate,
                departFrom: departFrom,
                destination: destination,
                tripType: document.getElementById('flightTripType').value,
                returnDate: document.getElementById('flightReturnDate').value,
                airline: document.getElementById('flightAirline').value,
                flightNumber: document.getElementById('flightNumber').value,
                operator: document.getElementById('flightOperator').value,
                class: document.getElementById('flightClass').value,
                adults: parseInt(document.getElementById('flightAdults').value) || 0,
                child: parseInt(document.getElementById('flightChild').value) || 0,
                cost: parseFloat(document.getElementById('flightCost').value) || 0,
                sell: parseFloat(document.getElementById('flightSell').value) || 0,
                taxIncluded: document.getElementById('flightTaxIncluded').checked
            };
        }
        else if (transportMode === 'cruise') {
            const departureDate = document.getElementById('cruiseDepartureDate').value;
            const departFrom = document.getElementById('cruiseDepartFrom').value;
            
            if (!departureDate || !departFrom) {
                alert('Please fill in departure date and depart from');
                return;
            }
            
            transferData = {
                ...transferData,
                dateTime: departureDate,
                departFrom: departFrom,
                fromTerminal: document.getElementById('cruiseFromTerminal').value,
                by: document.getElementById('cruiseBy').value,
                cruiseType: document.getElementById('cruiseType').value,
                vessel: document.getElementById('cruiseVessel').value,
                arrivalTo: document.getElementById('cruiseArrivalTo').value,
                arrivalDate: document.getElementById('cruiseArrivalDate').value,
                operator: document.getElementById('cruiseOperator').value,
                cabinClass: document.getElementById('cruiseCabinClass').value,
                adults: parseInt(document.getElementById('cruiseAdults').value) || 0,
                child: parseInt(document.getElementById('cruiseChild').value) || 0,
                cost: parseFloat(document.getElementById('cruiseCost').value) || 0,
                sell: parseFloat(document.getElementById('cruiseSell').value) || 0,
                taxIncluded: document.getElementById('cruiseTaxIncluded').checked
            };
        }
        else if (transportMode === 'train') {
            const departureDate = document.getElementById('trainDepartureDate').value;
            const departFrom = document.getElementById('trainDepartFrom').value;
            const destination = document.getElementById('trainDestination').value;
            
            if (!departureDate || !departFrom || !destination) {
                alert('Please fill in departure date, depart from, and destination');
                return;
            }
            
            transferData = {
                ...transferData,
                dateTime: departureDate,
                departFrom: departFrom,
                destination: destination,
                tripType: document.getElementById('trainTripType').value,
                returnDate: document.getElementById('trainReturnDate').value,
                operator: document.getElementById('trainOperator').value,
                class: document.getElementById('trainClass').value,
                stationTransfer: document.getElementById('trainStationTransfer').value,
                adults: parseInt(document.getElementById('trainAdults').value) || 0,
                child: parseInt(document.getElementById('trainChild').value) || 0,
                cost: parseFloat(document.getElementById('trainCost').value) || 0,
                sell: parseFloat(document.getElementById('trainSell').value) || 0,
                taxIncluded: document.getElementById('trainTaxIncluded').checked
            };
        }
        else if (transportMode === 'bus') {
            const departureDate = document.getElementById('busDepartureDate').value;
            const departFrom = document.getElementById('busDepartFrom').value;
            const destination = document.getElementById('busDestination').value;
            
            if (!departureDate || !departFrom || !destination) {
                alert('Please fill in departure date, depart from, and destination');
                return;
            }
            
            transferData = {
                ...transferData,
                dateTime: departureDate,
                departFrom: departFrom,
                destination: destination,
                tripType: document.getElementById('busTripType').value,
                returnDate: document.getElementById('busReturnDate').value,
                operator: document.getElementById('busOperator').value,
                class: document.getElementById('busClass').value,
                stationTransfer: document.getElementById('busStationTransfer').value,
                adults: parseInt(document.getElementById('busAdults').value) || 0,
                child: parseInt(document.getElementById('busChild').value) || 0,
                cost: parseFloat(document.getElementById('busCost').value) || 0,
                sell: parseFloat(document.getElementById('busSell').value) || 0,
                taxIncluded: document.getElementById('busTaxIncluded').checked
            };
        }
        
        transferData.focServiceDiscount = document.getElementById('transferPackageFocDiscount')?.checked || false;

        const isEditing = window.editingTransferIndex !== null && window.editingTransferIndex !== undefined;
        
        if (isEditing) {
            transferList[window.editingTransferIndex] = transferData;
            window.editingTransferIndex = null;
        } else {
            transferList.push(transferData);
        }
        
        // Update header dates
        if (isEditing) {
            // When editing, recalculate from all services to handle date changes properly
            recalculateHeaderDatesFromServices();
        } else {
            // When adding new, just expand if needed
            if (transferData.dateTime) {
                updateHeaderDatesIfNeeded(transferData.dateTime);
            }
        }
        
        updateTransferTable();
        updateGuideTable();
        recalculateTotals();
        
        const transferModal = bootstrap.Modal.getInstance(document.getElementById('transferModal'));
        if (transferModal) transferModal.hide();
    }
    
    // Edit transfer
    function editTransfer(index) {
        const transfer = transferList[index];
        if (!transfer) return;

        // Port arrival / departure rows (including legacy shapes): always open Edit Arrival / Edit Departure, not Transfer Package.
        const destStr = String(transfer.destination || transfer.service || '');
        const isPortArrDepLocal = (transfer.transportMode === 'local' || !transfer.transportMode) &&
            (destStr.indexOf('Arrival:') === 0 || destStr.indexOf('Departure:') === 0);
        if (isPortArrDepLocal) {
            const wantArrival = destStr.indexOf('Arrival:') === 0;
            let adIdx = arrivalDepartureList.findIndex(item => String(item.transferId) === String(transfer.id));
            if (adIdx === -1) {
                adIdx = arrivalDepartureList.findIndex(item => String(item.id) === String(transfer.sourceId));
            }
            if (adIdx === -1) {
                adIdx = arrivalDepartureList.findIndex(item => {
                    if (item.sourceType !== 'hotel') return false;
                    const isArr = item.type === 'Arrival' || item.type === 'arrival';
                    if (wantArrival) {
                        return isArr || item.travel_type === 'entry_port';
                    }
                    return !isArr && (item.type === 'Departure' || item.type === 'departure' || item.travel_type === 'exit_port');
                });
            }
            if (adIdx !== -1) {
                editArrivalDeparture(adIdx);
                return;
            }
        }
        
        // If it's linked to a service, open the source modal instead
        // Check both isStandalone flag and hotel-related fields
        const isLinked = transfer.isStandalone === false || transfer.sourceType === 'hotel' || transfer.sourceType === 'accommodation' || transfer.hotelName || transfer.linkedHotelBookingId;
        if (isLinked) {
            // Check sourceType to determine which modal to open
            if (transfer.sourceType === 'tour' || transfer.linkedTo === 'tour' || transfer.linkedTo === 'attraction') {
                // Find the tour that has this transfer
                const tourIndex = tourList.findIndex(tour => tour.transferId === transfer.id);
                if (tourIndex !== -1) {
                    editTour(tourIndex);
                    return;
                }
            } else if (transfer.sourceType === 'meal' || transfer.linkedTo === 'restaurant') {
                // Find the meal that has this transfer
                const mealIndex = mealList.findIndex(meal => meal.transferId === transfer.id);
                if (mealIndex !== -1) {
                    editMeal(mealIndex);
                    return;
                }
            } else if (transfer.sourceType === 'arrival' || transfer.sourceType === 'Arrival') {
                // Find the arrival that has this transfer
                const arrivalIndex = arrivalDepartureList.findIndex(item => 
                    (item.type === 'Arrival' || item.type === 'arrival') && (item.transferId === transfer.id || item.id === transfer.sourceId)
                );
                if (arrivalIndex !== -1) {
                    editArrivalDeparture(arrivalIndex);
                    return;
                }
            } else if (transfer.sourceType === 'departure' || transfer.sourceType === 'Departure') {
                // Find the departure that has this transfer
                const departureIndex = arrivalDepartureList.findIndex(item => 
                    (item.type === 'Departure' || item.type === 'departure') && (item.transferId === transfer.id || item.id === transfer.sourceId)
                );
                if (departureIndex !== -1) {
                    editArrivalDeparture(departureIndex);
                    return;
                }
            } else if (transfer.sourceType === 'hotel' || transfer.sourceType === 'accommodation' || transfer.hotelName || transfer.linkedHotelBookingId) {
                // First, try to use accommodationIndex if available (most reliable)
                if (transfer.accommodationIndex !== undefined && transfer.accommodationIndex !== null) {
                    const hotelIndex = transfer.accommodationIndex;
                    if (accommodationList[hotelIndex]) {
                        console.log('Opening hotel popup for transfer (using accommodationIndex):', hotelIndex);
                        editAccommodation(hotelIndex);
                        return;
                    }
                }
                
                // Fallback: Find the hotel that has this transfer in transferIds array
                const hotelIndex = accommodationList.findIndex(hotel => {
                    // Check if transfer ID is in the transferIds array
                    if (hotel.transferIds && Array.isArray(hotel.transferIds) && hotel.transferIds.includes(transfer.id)) {
                        return true;
                    }
                    // Check if sourceId matches hotel id
                    if (hotel.id === transfer.sourceId) {
                        return true;
                    }
                    // Check if bookingId matches linkedHotelBookingId
                    if (transfer.linkedHotelBookingId && hotel.bookingId === transfer.linkedHotelBookingId) {
                        return true;
                    }
                    // Check if hotel name matches
                    if (transfer.hotelName && hotel.hotelName === transfer.hotelName) {
                        return true;
                    }
                    // Legacy check for single transferId (if still used)
                    if (hotel.transferId === transfer.id) {
                        return true;
                    }
                    return false;
                });
                
                if (hotelIndex !== -1) {
                    console.log('Opening hotel popup for transfer (found hotel at index):', hotelIndex);
                    editAccommodation(hotelIndex);
                    return;
                } else {
                    console.warn('Could not find hotel for transfer:', transfer);
                }
            }
            
            // If we can't find the source, just open transfer modal
            console.warn('Could not find source for linked transfer, opening transfer modal');
        }
        
        window.editingTransferIndex = index;
        
        // Reset all forms first
        resetAllTransferForms();
        
        // Set transport mode
        const transportMode = transfer.transportMode || 'local';
        const modeRadio = document.querySelector(`input[name="transferMode"][value="${transportMode}"]`);
        if (modeRadio) {
            modeRadio.checked = true;
            switchTransferMode(transportMode);
        }
        
        // Load data based on transport mode
        if (transportMode === 'local') {
            // For datetime-local input, we need the full datetime format (YYYY-MM-DDTHH:mm)
            let dateTimeValue = transfer.dateTime || '';
            // If the datetime doesn't have a time component, add default time 09:00
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T09:00';
            }
            document.getElementById('localDateTime').value = dateTimeValue;
            if (transfer.pickupId) {
                setTimeout(() => {
                    $('#localPickup').val(transfer.pickupId).trigger('change');
                }, 100);
            }
            if (transfer.dropId) {
                setTimeout(() => {
                    $('#localDrop').val(transfer.dropId).trigger('change');
                }, 100);
            }
            // Set vehicle by vehicleId (not vehicleType) since the dropdown value is vehicleId
            document.getElementById('localVehicleType').value = transfer.vehicleId || '';
            document.getElementById('localType').value = transfer.type || 'S';
            document.getElementById('localWay').value = transfer.way || 'both-way';
            document.getElementById('localAdults').value = transfer.adults || 2;
            document.getElementById('localChild').value = transfer.child || 0;
            
            // Load guide info if available
            const guideCheckbox = document.getElementById('localTransportGuideCheckbox');
            const guideSelect = document.getElementById('localTransportGuideSelect');
            const hoursSelect = document.getElementById('localTransportGuideHours');
            const guideDetailsSection = document.getElementById('localTransportGuideDetailsSection');
            const guideAdultQtyInput = document.getElementById('localTransportGuideAdultQty');
            const guideChildQtyInput = document.getElementById('localTransportGuideChildQty');
            
            if (transfer.guideInfo && transfer.guideInfo.guideId) {
                if (guideCheckbox && guideSelect) {
                    guideCheckbox.checked = true;
                    guideSelect.value = transfer.guideInfo.guideId;
                    if (guideDetailsSection) {
                        guideDetailsSection.style.display = 'block';
                    }
                    // Find guide entry in guideList to get hours and quantities
                    let guideEntry = null;
                    if (transfer.guideId) {
                        guideEntry = guideList.find(g => String(g.id) === String(transfer.guideId));
                    }
                    // If not found by entry ID, try finding by guideId
                    if (!guideEntry && transfer.guideInfo.guideId) {
                        guideEntry = guideList.find(g => String(g.guideId) === String(transfer.guideInfo.guideId));
                    }
                    
                    if (hoursSelect && guideEntry && guideEntry.hours) {
                        hoursSelect.value = guideEntry.hours;
                    }
                    // Populate adult and child quantities
                    if (guideAdultQtyInput && guideEntry) {
                        guideAdultQtyInput.value = guideEntry.adultsQty || 0;
                    }
                    if (guideChildQtyInput && guideEntry) {
                        guideChildQtyInput.value = guideEntry.childQty || 0;
                    }
                    updateLocalTransportGuidePricing(); // Update pricing based on hours
                    const tpgfEd = document.getElementById('transferPackageGuideFocDiscount');
                    if (tpgfEd) {
                        let lg = null;
                        if (transfer.guideId) lg = guideList.find(g => String(g.id) === String(transfer.guideId));
                        if (!lg && transfer.guideInfo && transfer.guideInfo.guideId) {
                            lg = guideList.find(g => String(g.guideId) === String(transfer.guideInfo.guideId));
                        }
                        tpgfEd.checked = !!(lg && (lg.focServiceDiscount || lg.foc_service_discount));
                    }
                }
            } else {
                // No guide info - ensure checkbox is unchecked and section is hidden
                if (guideCheckbox) {
                    guideCheckbox.checked = false;
                }
                if (guideDetailsSection) {
                    guideDetailsSection.style.display = 'none';
                }
                const tpgfClr = document.getElementById('transferPackageGuideFocDiscount');
                if (tpgfClr) tpgfClr.checked = false;
            }
        }
        else if (transportMode === 'flight') {
            document.getElementById('flightDepartFrom').value = transfer.departFrom || '';
            document.getElementById('flightDestination').value = transfer.destination || '';
            document.getElementById('flightTripType').value = transfer.tripType || 'return';
            // Normalize date to YYYY-MM-DD format for date input
            const normalizedDate = normalizeDateToYYYYMMDD(transfer.dateTime);
            document.getElementById('flightDepartureDate').value = normalizedDate || '';
            // Normalize return date
            const normalizedReturnDate = normalizeDateToYYYYMMDD(transfer.returnDate);
            document.getElementById('flightReturnDate').value = normalizedReturnDate || '';
            document.getElementById('flightAirline').value = transfer.airline || '';
            document.getElementById('flightNumber').value = transfer.flightNumber || '';
            document.getElementById('flightOperator').value = transfer.operator || '';
            document.getElementById('flightClass').value = transfer.class || 'economy';
            document.getElementById('flightAdults').value = transfer.adults || 2;
            document.getElementById('flightChild').value = transfer.child || 0;
            document.getElementById('flightCost').value = transfer.cost || 0;
            document.getElementById('flightSell').value = transfer.sell || 0;
            document.getElementById('flightTaxIncluded').checked = transfer.taxIncluded || false;
        }
        else if (transportMode === 'cruise') {
            document.getElementById('cruiseDepartFrom').value = transfer.departFrom || '';
            document.getElementById('cruiseFromTerminal').value = transfer.fromTerminal || '';
            document.getElementById('cruiseBy').value = transfer.by || 'cruise';
            document.getElementById('cruiseType').value = transfer.cruiseType || '';
            document.getElementById('cruiseVessel').value = transfer.vessel || '';
            document.getElementById('cruiseArrivalTo').value = transfer.arrivalTo || '';
            // Normalize date to YYYY-MM-DD format for date input
            const normalizedDate = normalizeDateToYYYYMMDD(transfer.dateTime);
            document.getElementById('cruiseDepartureDate').value = normalizedDate || '';
            // Normalize arrival date
            const normalizedArrivalDate = normalizeDateToYYYYMMDD(transfer.arrivalDate);
            document.getElementById('cruiseArrivalDate').value = normalizedArrivalDate || '';
            document.getElementById('cruiseOperator').value = transfer.operator || '';
            document.getElementById('cruiseCabinClass').value = transfer.cabinClass || 'economy';
            document.getElementById('cruiseAdults').value = transfer.adults || 2;
            document.getElementById('cruiseChild').value = transfer.child || 0;
            document.getElementById('cruiseCost').value = transfer.cost || 0;
            document.getElementById('cruiseSell').value = transfer.sell || 0;
            document.getElementById('cruiseTaxIncluded').checked = transfer.taxIncluded || false;
        }
        else if (transportMode === 'train') {
            document.getElementById('trainDepartFrom').value = transfer.departFrom || '';
            document.getElementById('trainDestination').value = transfer.destination || '';
            document.getElementById('trainTripType').value = transfer.tripType || 'return';
            // Normalize date to YYYY-MM-DD format for date input
            const normalizedDate = normalizeDateToYYYYMMDD(transfer.dateTime);
            document.getElementById('trainDepartureDate').value = normalizedDate || '';
            // Normalize return date
            const normalizedReturnDate = normalizeDateToYYYYMMDD(transfer.returnDate);
            document.getElementById('trainReturnDate').value = normalizedReturnDate || '';
            document.getElementById('trainOperator').value = transfer.operator || '';
            document.getElementById('trainClass').value = transfer.class || '1st-class';
            document.getElementById('trainStationTransfer').value = transfer.stationTransfer || '';
            document.getElementById('trainAdults').value = transfer.adults || 2;
            document.getElementById('trainChild').value = transfer.child || 0;
            document.getElementById('trainCost').value = transfer.cost || 0;
            document.getElementById('trainSell').value = transfer.sell || 0;
            document.getElementById('trainTaxIncluded').checked = transfer.taxIncluded || false;
        }
        else if (transportMode === 'bus') {
            document.getElementById('busDepartFrom').value = transfer.departFrom || '';
            document.getElementById('busDestination').value = transfer.destination || '';
            document.getElementById('busTripType').value = transfer.tripType || 'return';
            // Normalize date to YYYY-MM-DD format for date input
            const normalizedDate = normalizeDateToYYYYMMDD(transfer.dateTime);
            document.getElementById('busDepartureDate').value = normalizedDate || '';
            // Normalize return date
            const normalizedReturnDate = normalizeDateToYYYYMMDD(transfer.returnDate);
            document.getElementById('busReturnDate').value = normalizedReturnDate || '';
            document.getElementById('busOperator').value = transfer.operator || '';
            document.getElementById('busClass').value = transfer.class || 'executive';
            document.getElementById('busStationTransfer').value = transfer.stationTransfer || '';
            document.getElementById('busAdults').value = transfer.adults || 2;
            document.getElementById('busChild').value = transfer.child || 0;
            document.getElementById('busCost').value = transfer.cost || 0;
            document.getElementById('busSell').value = transfer.sell || 0;
            document.getElementById('busTaxIncluded').checked = transfer.taxIncluded || false;
        }
        
        const _tpFoc = document.getElementById('transferPackageFocDiscount');
        if (_tpFoc) _tpFoc.checked = !!transfer.focServiceDiscount;

        document.getElementById('transferModalTitleText').textContent = 'Edit Transfer Package';
        document.getElementById('saveTransferBtnText').textContent = 'Save & Close';
        
        // Initialize Select2 for pickup and drop dropdowns in transfer modal
        if (typeof $.fn.select2 !== 'undefined') {
            $('#localPickup').select2({
                placeholder: 'Search and select pickup location',
                allowClear: true,
                width: '100%',
                dropdownParent: $('#transferModal')
            });
            $('#localDrop').select2({
                placeholder: 'Search and select drop location',
                allowClear: true,
                width: '100%',
                dropdownParent: $('#transferModal')
            });
            
            // Auto-set pickup to same as drop off when drop off changes
            $('#localDrop').on('change', function() {
                const dropValue = $(this).val();
                if (dropValue) {
                    $('#localPickup').val(dropValue).trigger('change');
                }
            });
        }
        
        const transferModal = new bootstrap.Modal(document.getElementById('transferModal'));
        transferModal.show();
    }
    
    // Remove selected transfers
    function removeSelectedTransfers() {
        const checkboxes = document.querySelectorAll('.transfer-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select transfers to remove');
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        const existingIdsToRemove = idsToRemove.filter(id => {
            const item = transferList.find(t => String(t.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        const hasExistingItems = idsToRemove.some(id => {
            const item = transferList.find(t => String(t.id) === String(id));
            return item && (item.orderId != null && item.orderId !== '');
        });
        
        const count = checkboxes.length;
        const itemLabel = count === 1 ? 'transfer' : 'transfers';
        showRemoveFormSelectionAlert(count, itemLabel, () => {
            const snapshotBefore = snapshotAllServiceState();
            
            const guideIdsToRemove = [];
            
            idsToRemove.forEach(transferIdToRemove => {
            // Find the transfer being removed to check for linked guide
            const transferToRemove = transferList.find(t => String(t.id) === String(transferIdToRemove));
            if (transferToRemove && transferToRemove.guideId) {
                // Add linked guide to removal list
                guideIdsToRemove.push(String(transferToRemove.guideId));
                console.log('Will remove linked guide for local transfer:', transferToRemove.guideId);
            }
            
            // Remove from tours
            tourList.forEach(tour => {
                if (tour.transferId && String(tour.transferId) === String(transferIdToRemove)) {
                    tour.transferId = null;
                    tour.transferInfo = null;
                    // Update transfer_options in the tour to reflect removal
                    if (tour.transfer_options) {
                        delete tour.transfer_options;
                    }
                }
            });
            
            // Remove from hotels
            accommodationList.forEach(hotel => {
                if (hotel.transferIds && Array.isArray(hotel.transferIds)) {
                    hotel.transferIds = hotel.transferIds.filter(id => String(id) !== String(transferIdToRemove));
                }
                // Also remove from transfer_options if it exists
                if (hotel.transfer_options && hotel.transfer_options.transferId && String(hotel.transfer_options.transferId) === String(transferIdToRemove)) {
                    delete hotel.transfer_options;
                }
            });
            
            // Remove from meals/restaurants
            mealList.forEach(meal => {
                if (meal.transferId && String(meal.transferId) === String(transferIdToRemove)) {
                    // Uncheck the transfer checkbox
                    meal.transferId = null;
                    meal.transferInfo = null;
                    // Note: Do NOT clear guideId - guide checkbox should remain checked
                    console.log('Unchecked transfer checkbox for meal/restaurant (guide remains if checked):', meal);
                }
                // Also remove from transfer_options if it exists
                if (meal.transfer_options && meal.transfer_options.transferId && String(meal.transfer_options.transferId) === String(transferIdToRemove)) {
                    delete meal.transfer_options;
                }
            });
            
            // Remove from arrival/departure
            arrivalDepartureList.forEach(item => {
                if (item.transferId && String(item.transferId) === String(transferIdToRemove)) {
                    // Uncheck the transfer checkbox
                    item.hasTransfer = false;
                    item.transferId = null;
                    // Clear transfer-related fields
                    item.transferDestinationId = null;
                    item.vehicleId = null;
                    item.transferType = null;
                    // Reset costs if transfer was associated
                    item.adultCost = 0;
                    item.adultSell = 0;
                    item.childCost = 0;
                    item.childSell = 0;
                    item.cost = 0;
                    item.sell = 0;
                    // Note: Do NOT clear guideId - guide checkbox should remain checked
                    console.log('Unchecked transfer checkbox for arrival/departure (guide remains if checked):', item);
                }
            });
            });
            
            transferList = transferList.filter(transfer => !idsToRemove.includes(String(transfer.id)));
            
            // Remove linked guides from guideList
            if (guideIdsToRemove.length > 0) {
                guideList = guideList.filter(guide => !guideIdsToRemove.includes(String(guide.id)));
            }
            
            // Update all affected tables
            updateTransferTable();
            updateTourTable();
            updateAccommodationTable();
            updateMealTable();
            updateArrivalDepartureTable();
            updateGuideTable();
            recalculateHeaderDatesFromServices();
            recalculateTotals();
            scheduleRemoveWithUndo({
                categoryKey: 'transfers',
                serviceMessage: 'Transfer service',
                existingIds: existingIdsToRemove,
                snapshotBefore
            });
        }, window.hasNegotiationHistory, hasExistingItems);
    }

    // Helper: normalize local transfer pricing with type and way
    function getTransferWayMultiplier(way) {
        const normalizedWay = (way || '').toString().toLowerCase();
        return (normalizedWay === 'both-way' || normalizedWay === 'both' || normalizedWay === 'two-way' || normalizedWay === 'return') ? 2 : 1;
    }
    
    function getLocalTransferPricing(transfer) {
        const type = (transfer.type || '').toString().toLowerCase();
        const isShared = type === 's' || type === 'sic' || type === 'shared';
        const isPrivate = type === 'p' || type === 'private';
        const wayMultiplier = getTransferWayMultiplier(transfer.way || 'one-way');
        
        const sharedZone = parseFloat(transfer.zoneSharedPrice || transfer.sharedPrice || 0);
        const privateZone = parseFloat(transfer.zonePrivatePrice || transfer.privatePrice || 0);
        const storedSell = parseFloat(transfer.sell || 0);
        const storedCost = parseFloat(transfer.cost || 0);
        
        let basePrice = 0;
        if (isShared) {
            basePrice = sharedZone || storedSell || storedCost;
        } else if (isPrivate) {
            basePrice = privateZone || storedSell || storedCost;
        } else {
            basePrice = storedSell || storedCost || sharedZone || privateZone;
        }
        
        if (basePrice === 0) {
            basePrice = sharedZone || privateZone || storedSell || storedCost || 0;
        }
        
        const totalPrice = basePrice * wayMultiplier;
        
        const adults = parseInt(transfer.adults || transfer.adultsQty || 0) || 0;
        const child = parseInt(transfer.child || transfer.childQty || 0) || 0;
        const totalPax = adults + child;
        
        const perPaxPrice = (isPrivate && totalPax > 0) ? Math.ceil(totalPrice / totalPax) : totalPrice;
        
        return { basePrice, totalPrice, perPaxPrice, isShared, isPrivate, wayMultiplier, totalPax };
    }

    // Footer summary expand/collapse: 1 row by default; arrow at top-right toggles with smooth transition
    function toggleFooterSummaryExpand() {
        var wrap = document.getElementById('footerSummaryScrollWrap');
        var btn = document.getElementById('footerSummaryToggleArrow');
        if (!wrap || !btn) return;
        var expanded = wrap.getAttribute('data-expanded') === 'true';
        if (expanded) {
            wrap.style.maxHeight = '72px';
            wrap.style.overflowY = 'hidden';
            wrap.setAttribute('data-expanded', 'false');
            btn.innerHTML = '▲';
            btn.title = 'Show all rows';
        } else {
            wrap.style.maxHeight = '280px';
            wrap.style.overflowY = 'auto';
            wrap.setAttribute('data-expanded', 'true');
            btn.innerHTML = '▼';
            btn.title = 'Show 1 row';
        }
    }

    /**
     * Show per-service FOC discount UI + footer "FOC" discount type only when GROUP has FOC pax
     * and "Treat FOC pax as discount (free)" (#enquiryProGroupDiscount) is on.
     */
    function refreshGroupFocDiscountUiVisibility() {
        const wrap = document.querySelector('.enquiry-pro-container');
        let active = false;
        if (typeof getEnquiryProGroupFocFactors === 'function') {
            const f = getEnquiryProGroupFocFactors();
            active = !!(f.isGroup && f.focSize > 0 && f.discountOn);
        }
        if (wrap) {
            wrap.classList.toggle('enquiry-pro-group-foc-discount-active', active);
        }
        const focOpt = document.querySelector('#discountType option[value="foc"]');
        const dt = document.getElementById('discountType');
        // Clear invalid "FOC" selection BEFORE hiding the option — some browsers keep the old
        // value if the selected <option> is hidden first, which broke the edit form footer.
        if (!active && dt && dt.value === 'foc') {
            if (focOpt) focOpt.hidden = false;
            dt.value = '';
            if (typeof handleDiscountTypeChange === 'function') handleDiscountTypeChange();
        }
        if (focOpt) focOpt.hidden = !active;
    }

    /**
     * GROUP + FOC factors aligned with App\Helpers\CommonHelper::calculateTourPrices.
     *  - totalPax  = adults + children (infants excluded, same as the backend headcount).
     *  - payingPax = max(0, adults - foc_size) + children (FOC applies to adults only).
     *  - focFactor = totalPax / payingPax when distribution applies (e.g. 7/5 for 7 pax, foc=2).
     *  - discount = 1 ("Treat FOC pax as discount (free)"):
     *      → FOC pax pay NOTHING; paying pax pay their normal per-pax share (factor 5/5 = 1).
     *      → hotelFactor = 1, otherFactor = 1.
     *  - discount = 0:
     *      → cost is distributed over paying pax for ALL services.
     *      → hotelFactor = focFactor, otherFactor = focFactor.
     */
    function getEnquiryProGroupFocFactors() {
        const typeEl = document.querySelector('input[name="type"]:checked') || document.querySelector('input[name="type"]');
        const tourType = (typeEl && typeEl.value ? String(typeEl.value) : 'FIT').toUpperCase();
        if (tourType !== 'GROUP') {
            return { isGroup: false, totalPax: 0, payingPax: 0, payingAdults: 0, focSize: 0, discountOn: false, focFactor: 1, hotelFactor: 1, otherFactor: 1 };
        }
        const adults = parseInt(document.getElementById('adultCountInput')?.value || '0', 10) || 0;
        const children = parseInt(document.getElementById('childCountInput')?.value || '0', 10) || 0;
        const focSize = Math.max(0, parseInt(document.getElementById('enquiryProFocSize')?.value || '0', 10) || 0);
        const totalPax = adults + children;
        const payingAdults = Math.max(0, adults - focSize);
        let payingPax = payingAdults + children;
        if (payingPax < 1) payingPax = totalPax > 0 ? totalPax : 1;
        let focFactor = 1;
        if (payingPax > 0 && totalPax > payingPax) focFactor = totalPax / payingPax;
        const hasFocDistribution = focFactor !== 1;
        const discountOn = parseInt(document.getElementById('enquiryProGroupDiscount')?.value || '0', 10) === 1;
        // discount=1 → FOC pax are TOTALLY FREE: paying pax pay their normal share for every service,
        //              so both hotel and non-hotel factors collapse to 1 (5/5 in the user's example).
        // discount=0 → cost is redistributed over paying pax for every service (focFactor, e.g. 7/5).
        const distributionFactor = (hasFocDistribution && !discountOn) ? focFactor : 1;
        const hotelFactor = distributionFactor;
        const otherFactor = distributionFactor;
        return { isGroup: true, totalPax, payingPax, payingAdults, focSize, discountOn, focFactor, hotelFactor, otherFactor };
    }

    // Recalculate all totals and populate footer table
    function recalculateTotals() {
        if (typeof refreshGroupFocDiscountUiVisibility === 'function') {
            refreshGroupFocDiscountUiVisibility();
        }
        const tbody = document.getElementById('footerSummaryBody');
        const thead = document.getElementById('footerSummaryHeader');
        let rows = [];
        // GROUP + FOC scaling factors (FIT: both 1). Hotel uses hotelFactor (no spread when discount=1),
        // everything else uses otherFactor — same contract as App\Helpers\CommonHelper::calculateTourPrices.
        const __focFactors = getEnquiryProGroupFocFactors();
        const __htlF = __focFactors.hotelFactor;
        const __othF = __focFactors.otherFactor;
        // Flat-rate services (private vehicle, guide): divide total by paying adults — do not multiply by otherFactor.
        const __flatFocDivisor = (__focFactors.isGroup && !__focFactors.discountOn && __focFactors.focSize > 0)
            ? Math.max(1, __focFactors.payingAdults) : 0;
        const scaleFlatRateFoc = (amount) => (__flatFocDivisor > 0 ? amount : amount * __othF);
        
        // Determine if we have hotels (non-supplement hotels)
        const nonSupplementHotels = accommodationList.filter(hotel => !hotel.supplement);
        const hasHotels = nonSupplementHotels.length > 0;
        
        // Update table header based on whether hotels exist
        if (hasHotels) {
            // Show hotel-style columns (Single, Twin, Triple, Child w/bed, Child w/o bed, Infant)
            thead.innerHTML = `
                <tr>
                    <th rowspan="2" style="padding: 3px 5px; vertical-align: middle; border-right: 2px solid #dee2e6; min-width: 180px; background: #e9ecef;">
                        <input type="checkbox" style="width: 12px; height: 12px;"> Hotel / Room
                    </th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #fff3cd; min-width: 100px;">Single</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #d1ecf1; min-width: 100px;">Twin</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #f8d7da; min-width: 100px;">Triple</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #d4edda; min-width: 120px;">Child w/ bed</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #e7d6f5; min-width: 120px;">Child w/o bed</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #e2e3e5; min-width: 100px;">Infant</th>
                </tr>
                <tr>
                    <th style="padding: 3px 5px; text-align: center; background: #fff3cd; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #fff3cd; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d1ecf1; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d1ecf1; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #f8d7da; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #f8d7da; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d4edda; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d4edda; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #e7d6f5; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #e7d6f5; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #e2e3e5; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #e2e3e5; font-size: 8px; font-weight: normal;">Sell</th>
                </tr>
            `;
        } else {
            // Show simplified columns (Adult and Child only)
            thead.innerHTML = `
                <tr>
                    <th rowspan="2" style="padding: 3px 5px; vertical-align: middle; border-right: 2px solid #dee2e6; min-width: 180px; background: #e9ecef;">
                        <input type="checkbox" style="width: 12px; height: 12px;"> Package Total
                    </th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #fff3cd; min-width: 120px;">Adult</th>
                    <th colspan="2" style="padding: 3px 5px; text-align: center; background: #d4edda; min-width: 120px;">Child</th>
                </tr>
                <tr>
                    <th style="padding: 3px 5px; text-align: center; background: #fff3cd; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #fff3cd; font-size: 8px; font-weight: normal;">Sell</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d4edda; font-size: 8px; font-weight: normal;">Cost</th>
                    <th style="padding: 3px 5px; text-align: center; background: #d4edda; font-size: 8px; font-weight: normal;">Sell</th>
                </tr>
            `;
        }
        
        // Calculate per-pax costs for tours, transfers, meals
        let tourCostPerPax = 0, tourSellPerPax = 0;
        let transferCostPerPax = 0, transferSellPerPax = 0;
        let childCostPerPax = 0, childSellPerPax = 0;
        
        const adults = parseInt(document.getElementById('adultCountInput')?.value || 0);
        const children = parseInt(document.getElementById('childCountInput')?.value || 0);
        
        // Calculate tour costs per pax (exclude items with supplement checked)
        // Read from table inputs for current values
        const tourTableBody = document.getElementById('tourTableBody');
        tourList.forEach((tour, tourIndex) => {
            // Only include if supplement is not checked
            if (!tour.supplement) {
                let adultCost = parseFloat(tour.adultCost || 0);
                let adultSell = parseFloat(tour.adultSell || 0);
                let childCost = parseFloat(tour.childCost || 0);
                let childSell = parseFloat(tour.childSell || 0);
                
                // Try to get current values from table row if available
                if (tourTableBody) {
                    const tableRows = Array.from(tourTableBody.querySelectorAll('tr'));
                    if (tourIndex < tableRows.length) {
                        // Tour table columns: 1-checkbox, 2-date, 3-tour name, 4-adult qty, 5-adult cost, 6-adult sell, 7-child qty, 8-child cost, 9-child sell, 10-supplement
                        const adultCostInput = tableRows[tourIndex].querySelector('td:nth-child(5) input');
                        const adultSellInput = tableRows[tourIndex].querySelector('td:nth-child(6) input');
                        const childCostInput = tableRows[tourIndex].querySelector('td:nth-child(8) input');
                        const childSellInput = tableRows[tourIndex].querySelector('td:nth-child(9) input');
                        
                        if (adultCostInput && adultCostInput.value !== '') {
                            adultCost = parseFloat(adultCostInput.value) || 0;
                        }
                        if (adultSellInput && adultSellInput.value !== '') {
                            adultSell = parseFloat(adultSellInput.value) || 0;
                        }
                        if (childCostInput && childCostInput.value !== '') {
                            childCost = parseFloat(childCostInput.value) || 0;
                        }
                        if (childSellInput && childSellInput.value !== '') {
                            childSell = parseFloat(childSellInput.value) || 0;
                        }
                    }
                }
                
                tourCostPerPax += adultCost;
                tourSellPerPax += adultSell;
                childCostPerPax += childCost;
                childSellPerPax += childSell;
            }
        });
        
        // Calculate transfer costs per pax (for non-local transfers only - local transfers are handled separately)
        // Exclude items with supplement checked
        transferList.forEach(transfer => {
            // Only include non-local transfers (local transfers are calculated in localTransferSingleCost/TwinCost/TripleCost)
            // Only include if supplement is not checked
            if (transfer.transportMode !== 'local' && !transfer.supplement) {
                const paxCount = (parseInt(transfer.adults) || 0) + (parseInt(transfer.child) || 0);
                if (paxCount > 0) {
                    transferCostPerPax += (parseFloat(transfer.cost) || 0) / paxCount;
                    transferSellPerPax += (parseFloat(transfer.sell) || 0) / paxCount;
                }
            }
        });
        
        // Calculate meal costs per pax (exclude items with supplement checked)
        // Read from table inputs for current values
        const mealTableBody = document.getElementById('mealTableBody');
        mealList.forEach((meal, mealIndex) => {
            // Only include if supplement is not checked
            if (!meal.supplement) {
                let adultCost = parseFloat(meal.adultCost || 0);
                let adultSell = parseFloat(meal.adultSell || 0);
                let childCost = parseFloat(meal.childCost || 0);
                let childSell = parseFloat(meal.childSell || 0);
                
                // Try to get current values from table row if available
                if (mealTableBody) {
                    const tableRows = Array.from(mealTableBody.querySelectorAll('tr'));
                    if (mealIndex < tableRows.length) {
                        // Meal table columns: 1-checkbox, 2-date, 3-restaurant, 4-adult qty, 5-adult cost, 6-adult sell, 7-child qty, 8-child cost, 9-child sell, 10-supplement
                        const adultCostInput = tableRows[mealIndex].querySelector('td:nth-child(5) input');
                        const adultSellInput = tableRows[mealIndex].querySelector('td:nth-child(6) input');
                        const childCostInput = tableRows[mealIndex].querySelector('td:nth-child(8) input');
                        const childSellInput = tableRows[mealIndex].querySelector('td:nth-child(9) input');
                        
                        if (adultCostInput && adultCostInput.value !== '') {
                            adultCost = parseFloat(adultCostInput.value) || 0;
                        }
                        if (adultSellInput && adultSellInput.value !== '') {
                            adultSell = parseFloat(adultSellInput.value) || 0;
                        }
                        if (childCostInput && childCostInput.value !== '') {
                            childCost = parseFloat(childCostInput.value) || 0;
                        }
                        if (childSellInput && childSellInput.value !== '') {
                            childSell = parseFloat(childSellInput.value) || 0;
                        }
                    }
                }
                
                tourCostPerPax += adultCost;
                tourSellPerPax += adultSell;
                childCostPerPax += childCost;
                childSellPerPax += childSell;
            }
        });
        
        // Calculate miscellaneous costs per pax (exclude items with supplement checked)
        // Read from table inputs for current values
        const miscTableBody = document.getElementById('miscTableBody');
        miscList.forEach((misc, miscIndex) => {
            // Only include if supplement is not checked
            if (!misc.supplement) {
                let adultCost = parseFloat(misc.adultCost || 0);
                let adultSell = parseFloat(misc.adultSell || 0);
                let childCost = parseFloat(misc.childCost || 0);
                let childSell = parseFloat(misc.childSell || 0);
                
                // Try to get current values from table row if available
                if (miscTableBody) {
                    const tableRows = Array.from(miscTableBody.querySelectorAll('tr'));
                    if (miscIndex < tableRows.length) {
                        // Misc table columns: 1-checkbox, 2-date, 3-item, 4-adult qty, 5-adult cost, 6-adult sell, 7-child qty, 8-child cost, 9-child sell, 10-infant qty, 11-infant cost, 12-infant sell, 13-FOC, 14-supplement
                        const adultCostInput = tableRows[miscIndex].querySelector('td:nth-child(5) input');
                        const adultSellInput = tableRows[miscIndex].querySelector('td:nth-child(6) input');
                        const childCostInput = tableRows[miscIndex].querySelector('td:nth-child(8) input');
                        const childSellInput = tableRows[miscIndex].querySelector('td:nth-child(9) input');
                        
                        if (adultCostInput && adultCostInput.value !== '') {
                            adultCost = parseFloat(adultCostInput.value) || 0;
                        }
                        if (adultSellInput && adultSellInput.value !== '') {
                            adultSell = parseFloat(adultSellInput.value) || 0;
                        }
                        if (childCostInput && childCostInput.value !== '') {
                            childCost = parseFloat(childCostInput.value) || 0;
                        }
                        if (childSellInput && childSellInput.value !== '') {
                            childSell = parseFloat(childSellInput.value) || 0;
                        }
                    }
                }
                
                tourCostPerPax += adultCost;
                tourSellPerPax += adultSell;
                childCostPerPax += childCost;
                childSellPerPax += childSell;
            }
        });
        
        // Calculate guide costs for each occupancy type (for standalone guides only)
        // Guide price is divided by occupancy (1 for single, 2 for twin, 3 for triple) with ceiling
        let guideSingleCost = 0, guideSingleSell = 0;
        let guideTwinCost = 0, guideTwinSell = 0;
        let guideTripleCost = 0, guideTripleSell = 0;
        
        // Helper function: only round to ceiling if there's a decimal part
        // If the value is already a whole number (e.g., 44), return it as is
        // If it has a decimal (e.g., 44.1, 44.5), round up to ceiling
        const ceilIfDecimal = (value) => {
            // If the value is already a whole number, return it as is
            // Otherwise, return the ceiling value
            return (value % 1 === 0) ? value : Math.ceil(value);
        };
        
        // Get guide table to read current values from inputs
        const guideTableBody = document.getElementById('guideTableBody');
        guideList.forEach((guide, guideIndex) => {
            // Include standalone guides, restaurant guides, or attraction-linked guides
            // All guides should be included in the bottom section pricing (Single, Twin, Triple)
            const isStandalone = guide.isStandalone !== false;
            const isRestaurantGuide = guide.linkedTo === 'restaurant';
            const isAttractionGuide = guide.isStandalone === false && guide.linkedTo !== 'restaurant' && guide.linkedTo !== 'arrival' && guide.linkedTo !== 'departure' && guide.linkedTo !== 'local_transport';
            const isArrivalGuide = guide.linkedTo === 'arrival';
            const isDepartureGuide = guide.linkedTo === 'departure';
            const isLocalTransportGuide = guide.linkedTo === 'local_transport';
            
            if (isStandalone || isRestaurantGuide || isAttractionGuide || isArrivalGuide || isDepartureGuide || isLocalTransportGuide) {
                // Only include if supplement is not checked
                if (!guide.supplement) {
                    let guideCost = parseFloat(guide.cost || 0);
                    let guideSell = parseFloat(guide.sell || 0);
                    
                    // Try to get current value from table row if available
                    if (guideTableBody) {
                        const tableRows = Array.from(guideTableBody.querySelectorAll('tr'));
                        if (guideIndex < tableRows.length) {
                            // Cost is in column 9 (readonly text input), Sell is in column 10 (number input)
                            const costInput = tableRows[guideIndex].querySelector('td:nth-child(9) input');
                            const sellInput = tableRows[guideIndex].querySelector('td:nth-child(10) input[type="number"]');
                            if (costInput && costInput.value !== '') {
                                guideCost = parseFloat(costInput.value) || 0;
                            }
                            if (sellInput && sellInput.value !== '') {
                                guideSell = parseFloat(sellInput.value) || 0;
                            }
                        }
                    }
                    
                    // Debug logging for restaurant guides
                    if (isRestaurantGuide) {
                        console.log('Restaurant guide included in totals:', {
                            guideIndex,
                            guideId: guide.id,
                            guideName: guide.guideName || guide.name,
                            restaurantName: guide.restaurantName,
                            costFromObject: guide.cost,
                            sellFromObject: guide.sell,
                            costFromInput: guideCost,
                            sellFromInput: guideSell,
                            isStandalone,
                            isRestaurantGuide
                        });
                    }
                    
                    // Debug logging for attraction guides
                    if (isAttractionGuide) {
                        console.log('Attraction guide included in totals:', {
                            guideIndex,
                            guideId: guide.id,
                            guideName: guide.name,
                            tourName: guide.tourName,
                            costFromObject: guide.cost,
                            sellFromObject: guide.sell,
                            costFromInput: guideCost,
                            sellFromInput: guideSell,
                            isStandalone: guide.isStandalone,
                            isAttractionGuide
                        });
                    }
                    
                    // GROUP + FOC (no discount): flat guide total ÷ paying adults. Else: occupancy split.
                    if (__flatFocDivisor > 0) {
                        const perPayingCost = ceilIfDecimal(guideCost / __flatFocDivisor);
                        const perPayingSell = ceilIfDecimal(guideSell / __flatFocDivisor);
                        guideSingleCost += perPayingCost;
                        guideSingleSell += perPayingSell;
                        guideTwinCost += perPayingCost;
                        guideTwinSell += perPayingSell;
                        guideTripleCost += perPayingCost;
                        guideTripleSell += perPayingSell;
                    } else {
                        guideSingleCost += ceilIfDecimal(guideCost / 1);
                        guideSingleSell += ceilIfDecimal(guideSell / 1);
                        guideTwinCost += ceilIfDecimal(guideCost / 2);
                        guideTwinSell += ceilIfDecimal(guideSell / 2);
                        guideTripleCost += ceilIfDecimal(guideCost / 3);
                        guideTripleSell += ceilIfDecimal(guideSell / 3);
                    }
                }
            }
        });
        
        // Calculate local transfer contributions from all sources:
        // Arrival, Departure, Hotel, Restaurant, Attraction, and Local Transport
        // All local transfers are in transferList with transportMode === 'local'
        let localTransferSingleCost = 0;
        let localTransferSingleSell = 0;
        let localTransferTwinCost = 0;
        let localTransferTwinSell = 0;
        let localTransferTripleCost = 0;
        let localTransferTripleSell = 0;
        let localPrivSingleCost = 0, localPrivSingleSell = 0;
        let localPrivTwinCost = 0, localPrivTwinSell = 0;
        let localPrivTripleCost = 0, localPrivTripleSell = 0;
        let localSharedSingleCost = 0, localSharedSingleSell = 0;
        let localSharedTwinCost = 0, localSharedTwinSell = 0;
        let localSharedTripleCost = 0, localSharedTripleSell = 0;
        
        // Get all local transfers (from all sources: Arrival, Departure, Hotel, Restaurant, Attraction, Local Transport)
        // Exclude items with supplement checked
        transferList.forEach((transfer, transferIndex) => {
            if (transfer.transportMode !== 'local') return;
            
            // Only include if supplement is not checked
            if (transfer.supplement) return;
            
            // Get sell value from table input (list sell value) - this is the actual displayed value
            let listSellValue = parseFloat(transfer.sell || 0);
            let listCostValue = parseFloat(transfer.cost || 0);
            
            // Try to get current value from table row if available (use original transferList index)
            const transferTableBody = document.getElementById('transferTableBody');
            if (transferTableBody) {
                const tableRows = Array.from(transferTableBody.querySelectorAll('tr'));
                if (transferIndex < tableRows.length) {
                    // Cost is type="text" (readonly), Sell is type="number"
                    const sellInput = tableRows[transferIndex].querySelector('td:nth-child(11) input');
                    const costInput = tableRows[transferIndex].querySelector('td:nth-child(10) input');
                    if (sellInput && sellInput.value !== '') {
                        listSellValue = parseFloat(sellInput.value) || 0;
                    }
                    if (costInput && costInput.value !== '') {
                        listCostValue = parseFloat(costInput.value) || 0;
                    }
                }
            }
            
            // Use direct row cost/sell values - NO multiplication for bothway
            // The cost/sell in the table already represents the total price for this transfer
            let baseCost = listCostValue;
            let baseSell = listSellValue;
            
            // If sell is not set, fall back to cost value
            if (baseSell === 0 && baseCost > 0) {
                baseSell = baseCost;
            }
            
            // Check if this is a private transfer - for private transfers, divide by occupancy
            const transferType = (transfer.type || '').toString().toLowerCase();
            const isPrivate = transferType === 'p' || transferType === 'private';
            
            // Add to totals — private flat-rate vs shared per-pax (FOC uses paying-adult divisor for private/guide)
            if (baseSell > 0 || baseCost > 0) {
                if (isPrivate) {
                    if (__flatFocDivisor > 0) {
                        const perPayingCost = ceilIfDecimal(baseCost / __flatFocDivisor);
                        const perPayingSell = ceilIfDecimal(baseSell / __flatFocDivisor);
                        localPrivSingleCost += perPayingCost;
                        localPrivSingleSell += perPayingSell;
                        localPrivTwinCost += perPayingCost;
                        localPrivTwinSell += perPayingSell;
                        localPrivTripleCost += perPayingCost;
                        localPrivTripleSell += perPayingSell;
                    } else {
                        localPrivSingleCost += baseCost;
                        localPrivSingleSell += baseSell;
                        localPrivTwinCost += ceilIfDecimal(baseCost / 2);
                        localPrivTwinSell += ceilIfDecimal(baseSell / 2);
                        localPrivTripleCost += ceilIfDecimal(baseCost / 3);
                        localPrivTripleSell += ceilIfDecimal(baseSell / 3);
                    }
                } else {
                    localSharedSingleCost += baseCost;
                    localSharedSingleSell += baseSell;
                    localSharedTwinCost += baseCost;
                    localSharedTwinSell += baseSell;
                    localSharedTripleCost += baseCost;
                    localSharedTripleSell += baseSell;
                }
            }
        });

        localTransferSingleCost = localPrivSingleCost + localSharedSingleCost;
        localTransferSingleSell = localPrivSingleSell + localSharedSingleSell;
        localTransferTwinCost = localPrivTwinCost + localSharedTwinCost;
        localTransferTwinSell = localPrivTwinSell + localSharedTwinSell;
        localTransferTripleCost = localPrivTripleCost + localSharedTripleCost;
        localTransferTripleSell = localPrivTripleSell + localSharedTripleSell;

        const sTourCost = tourCostPerPax * __othF;
        const sTourSell = tourSellPerPax * __othF;
        const sTransferCost = transferCostPerPax * __othF;
        const sTransferSell = transferSellPerPax * __othF;
        const sChildCost = childCostPerPax * __othF;
        const sChildSell = childSellPerPax * __othF;
        const sGuideSingleCost = scaleFlatRateFoc(guideSingleCost);
        const sGuideSingleSell = scaleFlatRateFoc(guideSingleSell);
        const sGuideTwinCost = scaleFlatRateFoc(guideTwinCost);
        const sGuideTwinSell = scaleFlatRateFoc(guideTwinSell);
        const sGuideTripleCost = scaleFlatRateFoc(guideTripleCost);
        const sGuideTripleSell = scaleFlatRateFoc(guideTripleSell);
        const sLocalSingleCost = scaleFlatRateFoc(localPrivSingleCost) + localSharedSingleCost * __othF;
        const sLocalSingleSell = scaleFlatRateFoc(localPrivSingleSell) + localSharedSingleSell * __othF;
        const sLocalTwinCost = scaleFlatRateFoc(localPrivTwinCost) + localSharedTwinCost * __othF;
        const sLocalTwinSell = scaleFlatRateFoc(localPrivTwinSell) + localSharedTwinSell * __othF;
        const sLocalTripleCost = scaleFlatRateFoc(localPrivTripleCost) + localSharedTripleCost * __othF;
        const sLocalTripleSell = scaleFlatRateFoc(localPrivTripleSell) + localSharedTripleSell * __othF;
        
        // Add accommodation rows (exclude items with supplement checked)
        if (accommodationList.length > 0) {
            accommodationList.forEach((hotel, index) => {
                // Only include if supplement is not checked
                if (hotel.supplement) return;
                
                let nights = parseInt(hotel.nights) || 0;
                // Initialize with object values as fallback
                let hotelCostPerNight = parseFloat(hotel.cost || hotel.roomPrice || 0);
                let hotelSellPerNight = parseFloat(hotel.sell || hotel.roomPrice || 0);
                
                // Check if extra bed, cwb, cnb, infant checkboxes are selected
                // If not selected, these prices should be 0 (not included in calculations)
                const hasExtraBed = hotel.hasExtraBed === true;
                const hasCwb = hotel.hasCwb === true;
                const hasCnb = hotel.hasCnb === true;
                const hasInfant = hotel.hasInfant === true;
                
                // Only use prices if the corresponding checkbox is checked
                let extraBedPrice = hasExtraBed ? parseFloat(hotel.extraBedPrice || 0) : 0;
                let cwbPrice = hasCwb ? parseFloat(hotel.cwbPrice || 0) : 0;
                let cnbPrice = hasCnb ? parseFloat(hotel.cnbPrice || 0) : 0;
                let infantPrice = hasInfant ? parseFloat(hotel.infantPrice || 0) : 0;
                
                // ALWAYS try to get current value from table row (for edit form)
                // Table values are the source of truth - they show what user sees/edits
                const accommodationTableBody = document.getElementById('accommodationTableBody');
                if (accommodationTableBody) {
                    const tableRows = Array.from(accommodationTableBody.querySelectorAll('tr'));
                    // Match by hotel ID if available, otherwise use index
                    let matchingRow = null;
                    if (hotel.id) {
                        matchingRow = tableRows.find(row => {
                            const checkbox = row.querySelector('input.accommodation-checkbox');
                            return checkbox && checkbox.value == hotel.id;
                        });
                    }
                    // If no match by ID, use index
                    if (!matchingRow && index < tableRows.length) {
                        matchingRow = tableRows[index];
                    }
                    
                    if (matchingRow) {
                        // Get values from table - updated column indices for new structure
                        // Column 5: Nights, Column 7: Avg Cost, Column 8: Sell
                        // Column 9: Extra Bed, Column 10: CWB, Column 11: CNB, Column 12: Infant
                        const nightsInput = matchingRow.querySelector('td:nth-child(5) input');
                        const costInput = matchingRow.querySelector('td:nth-child(7) input');
                        const sellInput = matchingRow.querySelector('td:nth-child(8) input[type="number"]');
                        const extraBedInput = matchingRow.querySelector('td:nth-child(9) input');
                        const cwbInput = matchingRow.querySelector('td:nth-child(10) input');
                        const cnbInput = matchingRow.querySelector('td:nth-child(11) input');
                        const infantInput = matchingRow.querySelector('td:nth-child(12) input');
                        
                        // Always use table values - they are the displayed/actual values
                        if (nightsInput && nightsInput.value !== '') {
                            const tableNights = parseInt(nightsInput.value);
                            if (!isNaN(tableNights)) nights = tableNights;
                        }
                        if (costInput && costInput.value !== '') {
                            const tableCostValue = parseFloat(costInput.value);
                            if (!isNaN(tableCostValue)) hotelCostPerNight = tableCostValue;
                        }
                        if (sellInput && sellInput.value !== '') {
                            const tableSellValue = parseFloat(sellInput.value);
                            if (!isNaN(tableSellValue)) hotelSellPerNight = tableSellValue;
                        }
                        // Only read table values if the corresponding checkbox is checked
                        if (hasExtraBed && extraBedInput && extraBedInput.value !== '') {
                            const tableValue = parseFloat(extraBedInput.value);
                            if (!isNaN(tableValue)) extraBedPrice = tableValue;
                        }
                        if (hasCwb && cwbInput && cwbInput.value !== '') {
                            const tableValue = parseFloat(cwbInput.value);
                            if (!isNaN(tableValue)) cwbPrice = tableValue;
                        }
                        if (hasCnb && cnbInput && cnbInput.value !== '') {
                            const tableValue = parseFloat(cnbInput.value);
                            if (!isNaN(tableValue)) cnbPrice = tableValue;
                        }
                        if (hasInfant && infantInput && infantInput.value !== '') {
                            const tableValue = parseFloat(infantInput.value);
                            if (!isNaN(tableValue)) infantPrice = tableValue;
                        }
                    }
                }
                
                // NEW FORMULAS as per requirements (now FOC-scaled to mirror CommonHelper::calculateTourPrices):
                // Single = sell * nights
                // Twin = (sell * nights) / 2
                // Triple = ((sell * nights) + (extra bed amount * nights)) / 3
                // Child with bed = cwb price * nights
                // Child without bed = cnb price * nights
                // Infant = infant price * nights
                // GROUP + FOC: hotel cost scaled by hotelFactor (1 when "Treat FOC as discount/free" is ON);
                //              tour/transfer/guide/child/local transfer scaled by otherFactor.

                const totalSell = (hotelSellPerNight * nights) * __htlF;
                const totalCost = (hotelCostPerNight * nights) * __htlF;
                const totalExtraBed = (extraBedPrice * nights) * __htlF;
                const cwbNightCost = (cwbPrice * nights) * __htlF;
                const cnbNightCost = (cnbPrice * nights) * __htlF;

                // Single = sell * nights (full room cost for single occupancy)
                const singleCost = totalCost + sTourCost + sTransferCost + sGuideSingleCost + sLocalSingleCost;
                const singleSell = totalSell + sTourSell + sTransferSell + sGuideSingleSell + sLocalSingleSell;

                // Twin = (sell * nights) / 2 (share room between 2)
                const twinCost = (totalCost / 2) + sTourCost + sTransferCost + sGuideTwinCost + sLocalTwinCost;
                const twinSell = (totalSell / 2) + sTourSell + sTransferSell + sGuideTwinSell + sLocalTwinSell;

                // Triple = ((sell * nights) + (extra bed * nights)) / 3 (share room + extra bed between 3)
                const tripleCost = ((totalCost + totalExtraBed) / 3) + sTourCost + sTransferCost + sGuideTripleCost + sLocalTripleCost;
                const tripleSell = ((totalSell + totalExtraBed) / 3) + sTourSell + sTransferSell + sGuideTripleSell + sLocalTripleSell;

                // Child prices = (hotel child price per night * nights) + child costs from other services
                const childWithBedCost = cwbNightCost + sChildCost;
                const childWithBedSell = cwbNightCost + sChildSell;

                const childWithoutBedCost = cnbNightCost + sChildCost;
                const childWithoutBedSell = cnbNightCost + sChildSell;

                // Infants don't have an occupancy slot, so we leave them on the raw room infant supplement.
                const infantCost = infantPrice * nights;
                const infantSell = infantPrice * nights;
                
                // Round all prices to next 0 (ceiling)
                const singleCostRounded = roundToNextZero(singleCost);
                const singleSellRounded = roundToNextZero(singleSell);
                const twinCostRounded = roundToNextZero(twinCost);
                const twinSellRounded = roundToNextZero(twinSell);
                const tripleCostRounded = roundToNextZero(tripleCost);
                const tripleSellRounded = roundToNextZero(tripleSell);
                const childWithBedCostRounded = roundToNextZero(childWithBedCost);
                const childWithBedSellRounded = roundToNextZero(childWithBedSell);
                const childWithoutBedCostRounded = roundToNextZero(childWithoutBedCost);
                const childWithoutBedSellRounded = roundToNextZero(childWithoutBedSell);
                const infantCostRounded = roundToNextZero(infantCost);
                const infantSellRounded = roundToNextZero(infantSell);
                
                // Generate unique IDs for sell inputs
                const hotelId = `hotel_${index}_${Date.now()}`;
                
                rows.push(`
                    <tr>
                        <td style="padding: 3px 5px; border-right: 2px solid #dee2e6;">
                            <input type="checkbox" style="width: 12px; height: 12px; margin-right: 3px;">
                            ${hotel.hotelName}
                            <br><small class="text-muted" style="font-size: 8px;">${hotel.roomType || ''} | ${hotel.bedType || ''} | ${hotel.mealPlan || 'CP'}</small>
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${singleCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${singleSellRounded.toFixed(2)}" data-original-value="${singleSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${twinCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${twinSellRounded.toFixed(2)}" data-original-value="${twinSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${tripleCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${tripleSellRounded.toFixed(2)}" data-original-value="${tripleSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${childWithBedCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${childWithBedSellRounded.toFixed(2)}" data-original-value="${childWithBedSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${childWithoutBedCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${childWithoutBedSellRounded.toFixed(2)}" data-original-value="${childWithoutBedSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="text" value="${infantCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                        </td>
                        <td style="padding: 3px 5px; text-align: center;">
                            <input type="number" value="${infantSellRounded.toFixed(2)}" data-original-value="${infantSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                        </td>
                    </tr>
                `);
        });
    }
    
    // Check if all hotels are marked as supplement
    // Reuse the nonSupplementHotels variable already declared at the top of this function
    const allHotelsAreSupplement = accommodationList.length > 0 && nonSupplementHotels.length === 0;
        
        // Show Package Total Tours, Meals & Transfers row when:
        // 1. There are NO hotels at all, OR
        // 2. All hotels are marked as supplement
        // AND there are some services (tours, meals, transfers, guides, etc.)
        const shouldShowPackageTotal = (accommodationList.length === 0 || allHotelsAreSupplement) && 
                                      (tourList.length > 0 || mealList.length > 0 || transferList.length > 0 || 
                                       guideList.length > 0 || miscList.length > 0 ||
                                       localTransferSingleSell > 0 || localTransferTwinSell > 0 || localTransferTripleSell > 0);
        
        if (shouldShowPackageTotal) {
            // Calculate adult and child costs (private/guide flat-rate FOC already in s* totals)
            const adultCost = sTourCost + sTransferCost + sGuideSingleCost + sLocalSingleCost;
            const adultSell = sTourSell + sTransferSell + sGuideSingleSell + sLocalSingleSell;
            const childCost = sChildCost;
            const childSell = sChildSell;
            
            // Round prices
            const adultCostRounded = roundToNextZero(adultCost);
            const adultSellRounded = roundToNextZero(adultSell);
            const childCostRounded = roundToNextZero(childCost);
            const childSellRounded = roundToNextZero(childSell);
            
            // Show simplified Package Total row with Adult and Child columns only
            rows.push(`
                <tr>
                    <td style="padding: 3px 5px; border-right: 2px solid #dee2e6;">
                        <input type="checkbox" style="width: 12px; height: 12px; margin-right: 3px;">
                        Package Total
                        <br><small class="text-muted" style="font-size: 8px;">Tours, Meals, Transfers & Misc</small>
                    </td>
                    <td style="padding: 3px 5px; text-align: center;">
                        <input type="text" value="${adultCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                    </td>
                    <td style="padding: 3px 5px; text-align: center;">
                        <input type="number" value="${adultSellRounded.toFixed(2)}" data-original-value="${adultSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                    </td>
                    <td style="padding: 3px 5px; text-align: center;">
                        <input type="text" value="${childCostRounded.toFixed(0)}" readonly style="width: 60px; background-color: #f5f5f5;">
                    </td>
                    <td style="padding: 3px 5px; text-align: center;">
                        <input type="number" value="${childSellRounded.toFixed(2)}" data-original-value="${childSellRounded.toFixed(2)}" step="1" min="0" style="width: 60px;">
                    </td>
                </tr>
            `);
        }
        
        // Note: Local transfers (standalone and arrival/departure) are now added to accommodation rows
        // instead of creating separate transfer rows in the footer
        
        tbody.innerHTML = rows.join('');
        
        // Show/hide footer summary section based on whether there are rows
        const footerSummarySection = document.getElementById('footerSummarySection');
        if (footerSummarySection) {
            if (rows.length > 0) {
                footerSummarySection.style.display = 'block';
            } else {
                footerSummarySection.style.display = 'none';
            }
        }
        
        // After recalculating totals, reapply markup and discount if any
        setTimeout(() => {
            applyMarkupDiscount();
        }, 50);
    }

    // Handle markup type change - enable/disable value input
    function handleMarkupTypeChange() {
        const markupType = document.getElementById('markupType');
        const markupValue = document.getElementById('markupValue');
        
        if (markupType.value === '') {
            markupValue.disabled = true;
            markupValue.value = 0;
        } else {
            markupValue.disabled = false;
        }
        applyMarkupDiscount();
    }

    /**
     * While the accommodation modal is open, keep transferList / arrivalDepartureList FOC flags
     * in sync with the modal checkboxes so FOC discount in the footer updates without Save & Close.
     */
    function syncModalTransferFocFromModal() {
        try {
            if (window.isArrivalDepartureOnlyMode && window.editingArrivalDepartureIndex !== null && window.editingArrivalDepartureIndex !== undefined) {
                const item = arrivalDepartureList[window.editingArrivalDepartureIndex];
                if (item) {
                    const isArr = (item.type === 'Arrival' || item.type === 'arrival');
                    const foc = isArr
                        ? (document.getElementById('arrivalFocServiceDiscount')?.checked === true)
                        : (document.getElementById('departureFocServiceDiscount')?.checked === true);
                    item.focServiceDiscount = foc;
                    if (item.transferId) {
                        const ti = transferList.findIndex(t => String(t.id) === String(item.transferId));
                        if (ti !== -1) {
                            transferList[ti] = { ...transferList[ti], focServiceDiscount: foc };
                        }
                    }
                    if (typeof updateTransferTable === 'function') updateTransferTable();
                }
            } else {
                const section = document.getElementById('arrivalDepartureSection');
                const depWrap = document.getElementById('departureTransferFocRowWrap');
                if (section && section.style.display !== 'none') {
                    const arrEntry = arrivalDepartureList.find(e => e.sourceType === 'hotel' && e.travel_type === 'entry_port');
                    const depEntry = arrivalDepartureList.find(e => e.sourceType === 'hotel' && e.travel_type === 'exit_port');
                    if (arrEntry && arrEntry.transferId) {
                        const focA = document.getElementById('arrivalFocServiceDiscount')?.checked === true;
                        arrEntry.focServiceDiscount = focA;
                        const ti = transferList.findIndex(t => String(t.id) === String(arrEntry.transferId));
                        if (ti !== -1) transferList[ti] = { ...transferList[ti], focServiceDiscount: focA };
                    }
                    if (depEntry && depEntry.transferId && !(depWrap && depWrap.style.display === 'none')) {
                        const focD = document.getElementById('departureFocServiceDiscount')?.checked === true;
                        depEntry.focServiceDiscount = focD;
                        const ti = transferList.findIndex(t => String(t.id) === String(depEntry.transferId));
                        if (ti !== -1) transferList[ti] = { ...transferList[ti], focServiceDiscount: focD };
                    }
                    if (typeof updateTransferTable === 'function') updateTransferTable();
                }
            }
        } catch (e) {
            console.warn('syncModalTransferFocFromModal', e);
        }
        if (typeof recalculateTotals === 'function') recalculateTotals();
    }

    /** Standalone arrival/departure edit: sync guide FOC checkbox to guideList for live footer FOC. */
    function syncModalGuideFocFromCheckboxes() {
        try {
            if (!window.isArrivalDepartureOnlyMode || window.editingArrivalDepartureIndex === null || window.editingArrivalDepartureIndex === undefined) {
                if (typeof recalculateTotals === 'function') recalculateTotals();
                return;
            }
            const item = arrivalDepartureList[window.editingArrivalDepartureIndex];
            if (!item || !item.guideId) {
                if (typeof recalculateTotals === 'function') recalculateTotals();
                return;
            }
            const isArr = item.type === 'Arrival' || item.type === 'arrival';
            const foc = document.getElementById(isArr ? 'arrivalGuideFocServiceDiscount' : 'departureGuideFocServiceDiscount')?.checked === true;
            const gi = guideList.findIndex(g => String(g.id) === String(item.guideId));
            if (gi !== -1) {
                guideList[gi] = { ...guideList[gi], focServiceDiscount: foc };
            }
        } catch (e) {
            console.warn('syncModalGuideFocFromCheckboxes', e);
        }
        if (typeof recalculateTotals === 'function') recalculateTotals();
    }

    /**
     * GROUP + FOC: monetary value absorbed for FOC adults (× foc_size).
     * - Hotels: only when "Treat FOC pax as discount (free)" is on (no per-room checkbox).
     * - Attractions, meals, misc, guides, transfers: only services with "FOC discount" checked in their modal.
     * Mirrors hotelFactor / otherFactor from getEnquiryProGroupFocFactors (same as footer totals).
     */
    function computeAutoFocDiscount() {
        const f = (typeof getEnquiryProGroupFocFactors === 'function')
            ? getEnquiryProGroupFocFactors()
            : { isGroup: false, focSize: 0, discountOn: false, hotelFactor: 1, otherFactor: 1 };
        if (!f.isGroup || f.focSize <= 0) return 0;
        if (!f.discountOn) return 0;

        const htlF = f.hotelFactor;
        const othF = f.otherFactor;
        const foc = f.focSize;

        const ceilIfDecimal = (value) => ((value % 1 === 0) ? value : Math.ceil(value));

        let total = 0;

        accommodationList.forEach((hotel) => {
            if (hotel.supplement) return;
            if (hotel.focServiceDiscount === false) return;
            if (!focServiceHasPositiveSell(hotel, 'hotel')) return;
            const nights = parseInt(String(hotel.nights || 0), 10) || 0;
            const sell = parseFloat(hotel.sell) || 0;
            const scaledTotalHotelSell = nights * sell * htlF;
            const twinHotelPerPax = scaledTotalHotelSell / 2;
            if (twinHotelPerPax > 0) total += twinHotelPerPax * foc;
        });

        const tourTableBody = document.getElementById('tourTableBody');
        const transferTableBody = document.getElementById('transferTableBody');
        const guideTableBody = document.getElementById('guideTableBody');

        tourList.forEach((tour, tourIndex) => {
            if (tour.supplement || !tour.focServiceDiscount) return;
            if (!focServiceHasPositiveSell(tour, 'tour')) return;
            const adultsQty = parseInt(tour.adultsQty, 10) || 0;
            const childQty = parseInt(tour.childQty, 10) || 0;
            const infantQty = parseInt(tour.infantQty, 10) || 0;
            let adultSell = parseFloat(tour.adultSell) || 0;
            let childSell = parseFloat(tour.childSell) || 0;
            let infantSell = parseFloat(tour.infantSell) || 0;
            if (tourTableBody) {
                const tableRows = Array.from(tourTableBody.querySelectorAll('tr'));
                if (tourIndex < tableRows.length) {
                    const tr = tableRows[tourIndex];
                    const adultSellInput = tr.querySelector('td:nth-child(6) input');
                    const childSellInput = tr.querySelector('td:nth-child(9) input');
                    if (adultSellInput && adultSellInput.value !== '') adultSell = parseFloat(adultSellInput.value) || 0;
                    if (childSellInput && childSellInput.value !== '') childSell = parseFloat(childSellInput.value) || 0;
                }
            }
            const ticketTotal = adultSell * adultsQty + childSell * childQty + infantSell * infantQty;
            const ticketPax = adultsQty + childQty + infantQty;
            if (ticketPax > 0 && ticketTotal > 0) {
                total += (ticketTotal / ticketPax) * othF * foc;
            } else if (adultSell > 0) {
                total += adultSell * othF * foc;
            }

            if (tour.transferId) {
                const ti = transferList.findIndex(t => String(t.id) === String(tour.transferId));
                if (ti !== -1) {
                    const tr = transferList[ti];
                    if (!tr.supplement && tr.transportMode === 'local') {
                        let listSellValue = parseFloat(tr.sell || 0);
                        if (transferTableBody) {
                            const rows = Array.from(transferTableBody.querySelectorAll('tr'));
                            if (ti < rows.length) {
                                const sellInput = rows[ti].querySelector('td:nth-child(11) input');
                                if (sellInput && sellInput.value !== '') listSellValue = parseFloat(sellInput.value) || 0;
                            }
                        }
                        const baseSell = listSellValue;
                        const transferType = (tr.type || '').toString().toLowerCase();
                        const isPrivateXfer = transferType === 'p' || transferType === 'private';
                        if (baseSell > 0) {
                            if (isPrivateXfer) {
                                const paxCount = (parseInt(tr.adults, 10) || 0) + (parseInt(tr.child, 10) || 0);
                                if (paxCount > 0) {
                                    total += (baseSell / paxCount) * othF * foc;
                                } else {
                                    total += ceilIfDecimal(baseSell / 2) * othF * foc;
                                }
                            } else {
                                total += baseSell * othF * foc;
                            }
                        }
                    }
                }
            }

            guideList.forEach((guide, guideIndex) => {
                if (guide.supplement) return;
                if (String(guide.sourceTourId || '') !== String(tour.id)) return;
                let guideSell = parseFloat(guide.sell || 0);
                if (guideTableBody) {
                    const gRows = Array.from(guideTableBody.querySelectorAll('tr'));
                    if (guideIndex < gRows.length) {
                        const sellInput = gRows[guideIndex].querySelector('td:nth-child(9) input[type="number"]');
                        if (sellInput && sellInput.value !== '') guideSell = parseFloat(sellInput.value) || 0;
                    }
                }
                if (guideSell <= 0) return;
                const adultQ = parseInt(guide.adultsQty ?? guide.adults ?? 0, 10) || 0;
                const childQ = parseInt(guide.childQty ?? guide.child ?? 0, 10) || 0;
                const paxCountG = adultQ + childQ;
                if (paxCountG > 0) {
                    total += (guideSell / paxCountG) * othF * foc;
                } else {
                    const twinPartG = ceilIfDecimal(guideSell / 2) * othF;
                    if (twinPartG > 0) total += twinPartG * foc;
                }
            });
        });

        const mealTableBody = document.getElementById('mealTableBody');
        mealList.forEach((meal, mealIndex) => {
            if (meal.supplement || !meal.focServiceDiscount) return;
            if (!focServiceHasPositiveSell(meal, 'meal')) return;
            let adultSell = parseFloat(meal.adultSell) || 0;
            if (mealTableBody) {
                const tableRows = Array.from(mealTableBody.querySelectorAll('tr'));
                if (mealIndex < tableRows.length) {
                    const adultSellInput = tableRows[mealIndex].querySelector('td:nth-child(6) input');
                    if (adultSellInput && adultSellInput.value !== '') adultSell = parseFloat(adultSellInput.value) || 0;
                }
            }
            if (adultSell > 0) total += adultSell * othF * foc;
        });

        const miscTableBody = document.getElementById('miscTableBody');
        miscList.forEach((misc, miscIndex) => {
            if (misc.supplement || !misc.focServiceDiscount) return;
            if (!focServiceHasPositiveSell(misc, 'misc')) return;
            let adultSell = parseFloat(misc.adultSell) || 0;
            if (miscTableBody) {
                const tableRows = Array.from(miscTableBody.querySelectorAll('tr'));
                if (miscIndex < tableRows.length) {
                    const adultSellInput = tableRows[miscIndex].querySelector('td:nth-child(6) input');
                    if (adultSellInput && adultSellInput.value !== '') adultSell = parseFloat(adultSellInput.value) || 0;
                }
            }
            if (adultSell > 0) total += adultSell * othF * foc;
        });

        transferList.forEach((transfer, transferIndex) => {
            if (transfer.supplement || !transfer.focServiceDiscount) return;
            if (!focServiceHasPositiveSell(transfer, 'transfer')) return;
            if (transfer.sourceType === 'tour' && transfer.sourceId) {
                const ownerTour = tourList.find(tu => String(tu.id) === String(transfer.sourceId));
                if (ownerTour && ownerTour.focServiceDiscount) return;
            }
            if (transfer.transportMode === 'local') {
                let listSellValue = parseFloat(transfer.sell || 0);
                if (transferTableBody) {
                    const tableRows = Array.from(transferTableBody.querySelectorAll('tr'));
                    if (transferIndex < tableRows.length) {
                        const sellInput = tableRows[transferIndex].querySelector('td:nth-child(11) input');
                        if (sellInput && sellInput.value !== '') listSellValue = parseFloat(sellInput.value) || 0;
                    }
                }
                const baseSell = listSellValue;
                const transferType = (transfer.type || '').toString().toLowerCase();
                const isPrivate = transferType === 'p' || transferType === 'private';
                if (baseSell > 0) {
                    if (isPrivate) {
                        const paxCount = (parseInt(transfer.adults, 10) || 0) + (parseInt(transfer.child, 10) || 0);
                        if (paxCount > 0) {
                            total += (baseSell / paxCount) * othF * foc;
                        } else {
                            total += ceilIfDecimal(baseSell / 2) * othF * foc;
                        }
                    } else {
                        total += baseSell * othF * foc;
                    }
                }
                return;
            }
            const paxCount = (parseInt(transfer.adults) || 0) + (parseInt(transfer.child) || 0);
            const sell = parseFloat(transfer.sell) || 0;
            if (paxCount <= 0 || sell <= 0) return;
            const perPax = sell / paxCount;
            total += perPax * othF * foc;
        });

        guideList.forEach((guide, guideIndex) => {
            if (guide.supplement || !guide.focServiceDiscount) return;
            if (guide.sourceTourId) {
                const ownerTour = tourList.find(tu => String(tu.id) === String(guide.sourceTourId));
                if (ownerTour && ownerTour.focServiceDiscount) return;
            }
            const isStandalone = guide.isStandalone !== false;
            const isRestaurantGuide = guide.linkedTo === 'restaurant';
            const isAttractionGuide = guide.isStandalone === false && guide.linkedTo !== 'restaurant' && guide.linkedTo !== 'arrival' && guide.linkedTo !== 'departure' && guide.linkedTo !== 'local_transport';
            const isArrivalGuide = guide.linkedTo === 'arrival';
            const isDepartureGuide = guide.linkedTo === 'departure';
            const isLocalTransportGuide = guide.linkedTo === 'local_transport';
            if (!(isStandalone || isRestaurantGuide || isAttractionGuide || isArrivalGuide || isDepartureGuide || isLocalTransportGuide)) return;

            let guideSell = parseFloat(guide.sell || 0);
            if (guideTableBody) {
                const tableRows = Array.from(guideTableBody.querySelectorAll('tr'));
                if (guideIndex < tableRows.length) {
                    const sellInput = tableRows[guideIndex].querySelector('td:nth-child(9) input[type="number"]');
                    if (sellInput && sellInput.value !== '') guideSell = parseFloat(sellInput.value) || 0;
                }
            }
            if (guideSell <= 0) return;
            const adultQ = parseInt(guide.adultsQty ?? guide.adults ?? 0, 10) || 0;
            const childQ = parseInt(guide.childQty ?? guide.child ?? 0, 10) || 0;
            const paxCount = adultQ + childQ;
            if (paxCount > 0) {
                const perPax = guideSell / paxCount;
                total += perPax * othF * foc;
            } else {
                const twinPart = ceilIfDecimal(guideSell / 2) * othF;
                if (twinPart > 0) total += twinPart * foc;
            }
        });

        return Math.ceil(total);
    }

    // Handle discount type change - enable/disable value input
    function handleDiscountTypeChange() {
        const discountType = document.getElementById('discountType');
        const discountValue = document.getElementById('discountValue');
        
        if (discountType.value === '') {
            discountValue.disabled = true;
            discountValue.value = 0;
            discountValue.style.backgroundColor = '';
            discountValue.title = 'Discount value. When type = FOC, this is auto-computed and locked.';
        } else if (discountType.value === 'foc') {
            const f = (typeof getEnquiryProGroupFocFactors === 'function') ? getEnquiryProGroupFocFactors() : { isGroup: false, focSize: 0, discountOn: false };
            if (!f.isGroup || f.focSize <= 0 || !f.discountOn) {
                discountType.value = '';
                discountValue.disabled = true;
                discountValue.value = 0;
                discountValue.style.backgroundColor = '';
                discountValue.title = 'Discount value. When type = FOC, this is auto-computed and locked.';
                applyMarkupDiscount();
                return;
            }
            // Auto-computed; field is locked so the value can't drift from the live calculation.
            discountValue.disabled = true;
            discountValue.value = computeAutoFocDiscount();
            discountValue.style.backgroundColor = '#fff8e1';
            discountValue.title = 'Auto-computed FOC discount: hotels when “Free” is on, plus checked services (adult/twin share × FOC size).';
        } else {
            discountValue.disabled = false;
            discountValue.style.backgroundColor = '';
            discountValue.title = 'Discount value. When type = FOC, this is auto-computed and locked.';
        }
        applyMarkupDiscount();
    }

    // Apply Markup and Discount to footer sell values
    function applyMarkupDiscount() {
        console.log('=== applyMarkupDiscount() called ===');
        
        const markupValueElem = document.getElementById('markupValue');
        const markupTypeElem = document.getElementById('markupType');
        const discountValueElem = document.getElementById('discountValue');
        const discountTypeElem = document.getElementById('discountType');
        
        if (!markupValueElem || !markupTypeElem || !discountValueElem || !discountTypeElem) {
            console.error('❌ Markup/Discount elements not found yet');
            return;
        }
        
        const markupValue = parseFloat(markupValueElem.value || 0);
        const markupType = markupTypeElem.value || '';
        const discountType = discountTypeElem.value || '';
        const focHdr = (typeof getEnquiryProGroupFocFactors === 'function') ? getEnquiryProGroupFocFactors() : null;
        const focDiscountUiActive = focHdr && focHdr.isGroup && focHdr.focSize > 0 && focHdr.discountOn;

        // FOC discount type: auto-recompute the absorbed-cost value on every pass so it stays
        // in sync as services are added/removed. The value is purely informational and is NOT
        // subtracted from per-pax sells (paying pax already pay their normal share with factor = 1).
        let discountValue;
        if (discountType === 'foc' && focDiscountUiActive) {
            discountValue = computeAutoFocDiscount();
            discountValueElem.value = discountValue;
        } else if (discountType === 'foc') {
            discountValue = 0;
            discountValueElem.value = 0;
        } else {
            discountValue = parseFloat(discountValueElem.value || 0);
        }
        
        console.log('📊 Markup/Discount Values:', {
            markupValue,
            markupType,
            discountValue,
            discountType
        });
        
        const tbody = document.getElementById('footerSummaryBody');
        if (!tbody) {
            console.error('❌ Footer summary body not found');
            return;
        }
        
        // Get all rows
        const rows = tbody.querySelectorAll('tr');
        
        if (rows.length === 0) {
            console.warn('⚠️ No rows found in footer summary - add hotels/tours first');
            return;
        }
        
        console.log(`✓ Found ${rows.length} rows to process`);
        
        let inputsProcessed = 0;
        
        rows.forEach((row, rowIndex) => {
            // Get all sell input fields (columns: Single(2), Twin(4), Triple(6), Child w/bed(8), Child w/o bed(10), Infant(12))
            const cells = row.querySelectorAll('td');
            
            // Process each sell column with input fields (0-indexed)
            const sellColumns = [2, 4, 6, 8, 10, 12];
            
            sellColumns.forEach(colIndex => {
                if (cells[colIndex]) {
                    const input = cells[colIndex].querySelector('input[type="number"]');
                    if (input) {
                        // Get original value
                        let originalValue = parseFloat(input.getAttribute('data-original-value'));
                        
                        // If no original value stored, store current value as original
                        if (isNaN(originalValue)) {
                            originalValue = parseFloat(input.value) || 0;
                            input.setAttribute('data-original-value', originalValue);
                        }
                        
                        // If original value is 0, don't apply any markup or discount (0 stays 0)
                        if (originalValue === 0) {
                            input.value = '0.00';
                            inputsProcessed++;
                            return;
                        }
                        
                        let newValue = originalValue;
                        const oldValue = parseFloat(input.value);
                        
                        // Apply markup (only if type is selected and value > 0)
                        if (markupValue > 0 && markupType !== '') {
                            if (markupType === 'percentage') {
                                newValue += (originalValue * markupValue / 100);
                            } else {
                                newValue += markupValue;
                            }
                        }
                        
                        // Apply discount (only if type is selected and value > 0).
                        // FOC type is intentionally skipped — its value is informational only
                        // (paying-pax sells are already correct at factor = 1).
                        if (discountValue > 0 && discountType !== '' && discountType !== 'foc') {
                            if (discountType === 'percentage') {
                                newValue -= (newValue * discountValue / 100);
                            } else {
                                newValue -= discountValue;
                            }
                        }
                        
                        // Apply ceiling if there's any decimal part
                        // If 50.01, it becomes 51; if 50.00, it stays 50
                        if (newValue % 1 !== 0) {
                            newValue = Math.ceil(newValue);
                        }
                        
                        // Update the input value
                        input.value = newValue.toFixed(2);
                        
                        if (inputsProcessed < 3) { // Only log first 3 to avoid console spam
                            console.log(`  Row ${rowIndex}, Col ${colIndex}: ${oldValue.toFixed(2)} → ${newValue.toFixed(2)} (original: ${originalValue.toFixed(2)})`);
                        }
                        inputsProcessed++;
                    }
                }
            });
        });
        
        console.log(`✅ Successfully updated ${inputsProcessed} sell values`);
        console.log('=== applyMarkupDiscount() complete ===\n');
    }

    // Select all accommodation
    document.addEventListener('DOMContentLoaded', function() {
        const selectAll = document.getElementById('selectAllAccommodation');
        if (selectAll) {
            selectAll.addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.accommodation-checkbox');
                checkboxes.forEach(cb => cb.checked = this.checked);
            });
        }

        // Select all arrival/departure
        const selectAllArrivalDeparture = document.getElementById('selectAllArrivalDeparture');
        if (selectAllArrivalDeparture) {
            selectAllArrivalDeparture.addEventListener('change', function() {
                const checkboxes = document.querySelectorAll('.arrivalDeparture-checkbox');
                checkboxes.forEach(cb => cb.checked = this.checked);
            });
        }

        // Initialize Select2 for port dropdowns - will be initialized per modal
        // Removed global initialization to allow per-modal initialization

        // Auto-load agents if agency is pre-selected from initial data
        @if(isset($initialData) && isset($initialData['agency_id']))
        const agencyId = {{ $initialData['agency_id'] }};
        if (agencyId) {
            // Trigger the loadAgentsByAgency function after a short delay
            setTimeout(function() {
                loadAgentsByAgency();
            }, 500);
        }
        @endif

        // Add event listeners for markup and discount controls
        const markupValue = document.getElementById('markupValue');
        const markupType = document.getElementById('markupType');
        const discountValue = document.getElementById('discountValue');
        const discountType = document.getElementById('discountType');

        if (markupValue) {
            // Add multiple event types for better browser compatibility
            ['input', 'change', 'keyup', 'blur'].forEach(eventType => {
                markupValue.addEventListener(eventType, function() {
                    console.log(`Markup value ${eventType}:`, this.value);
                    applyMarkupDiscount();
                });
            });
        }

        if (markupType) {
            markupType.addEventListener('change', function() {
                console.log('Markup type changed:', this.value);
                handleMarkupTypeChange();
            });
        }

        if (discountValue) {
            // Add multiple event types for better browser compatibility
            ['input', 'change', 'keyup', 'blur'].forEach(eventType => {
                discountValue.addEventListener(eventType, function() {
                    console.log(`Discount value ${eventType}:`, this.value);
                    applyMarkupDiscount();
                });
            });
        }

        if (discountType) {
            discountType.addEventListener('change', function() {
                console.log('Discount type changed:', this.value);
                handleDiscountTypeChange();
            });
        }

        (function syncFooterFocWhenTreatFocFreeOnInit() {
            const h = document.getElementById('enquiryProGroupDiscount');
            if (!h || String(h.value) !== '1') return;
            if (discountType && discountType.value !== 'foc') {
                discountType.value = 'foc';
                if (typeof handleDiscountTypeChange === 'function') handleDiscountTypeChange();
            }
        })();

        console.log('✅ Markup/Discount event listeners registered');
        console.log('Markup Value Element:', markupValue);
        console.log('Discount Value Element:', discountValue);
        
        // Apply markup/discount on page load if values are set
        @if(isset($markupType) && $markupType != '')
            if (markupType) {
                markupType.value = '{{ $markupType }}';
                handleMarkupTypeChange();
            }
        @endif
        
        @if(isset($discountType) && $discountType != '')
            if (discountType) {
                discountType.value = '{{ $discountType }}';
                handleDiscountTypeChange();
            }
        @endif

        if (typeof refreshGroupFocDiscountUiVisibility === 'function') {
            refreshGroupFocDiscountUiVisibility();
        }
        
        // Apply markup/discount after a short delay to ensure all data is loaded
        setTimeout(function() {
            if (typeof refreshGroupFocDiscountUiVisibility === 'function') refreshGroupFocDiscountUiVisibility();
            applyMarkupDiscount();
        }, 500);
    });

    // Collapse sidebar on page load for Enquiry Pro
    window.addEventListener('load', function() {
        setTimeout(function() {
            const html = document.documentElement;
            const layoutMenu = document.querySelector('.layout-menu');
            const menuToggle = document.querySelector('.layout-menu-toggle');
            
            // Check if Helpers object exists (from helpers.js)
            if (typeof Helpers !== 'undefined' && Helpers.toggleCollapsed) {
                // Use the template's built-in collapse function
                if (!html.classList.contains('layout-menu-collapsed')) {
                    Helpers.toggleCollapsed();
                }
            } else {
                // Fallback method if Helpers not available
                if (html) {
                    html.classList.remove('layout-menu-expanded');
                    html.classList.add('layout-menu-collapsed');
                }
                
                if (layoutMenu) {
                    layoutMenu.classList.add('closed');
                }
                
                // Update body/content margin
                const layoutPage = document.querySelector('.layout-page');
                if (layoutPage) {
                    layoutPage.style.marginLeft = '0';
                    layoutPage.style.marginInlineStart = '0';
                }
            }
        }, 100); // Small delay to ensure all scripts are loaded
    });

    // ==================== SAVE ENQUIRY DATA FUNCTIONS ====================
    
    // Helper function to fetch vehicle details by vehicle_id
    async function fetchVehicleDetails(vehicleId, dmcId) {
        if (!vehicleId || !dmcId) {
            return {
                vehicles_name: "",
                vehicle_type: "",
                vehicle_model: "",
                model_year: "",
                image: ""
            };
        }
        
        try {
            const response = await fetch(`/api/vehicle-details?vehicle_id=${vehicleId}&dmc_id=${dmcId}&mode=dmc`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json'
                }
            });
            
            if (!response.ok) {
                console.error('Failed to fetch vehicle details:', response.statusText);
                return {
                    vehicles_name: "",
                    vehicle_type: "",
                    vehicle_model: "",
                    model_year: "",
                    image: ""
                };
            }
            
            // Check if response is JSON before parsing
            const contentType = response.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                console.error('Server returned non-JSON response:', contentType);
                return {
                    vehicles_name: "",
                    vehicle_type: "",
                    vehicle_model: "",
                    model_year: "",
                    image: ""
                };
            }
            
            const data = await response.json();
            return {
                vehicles_name: data.vehicle_name || "",
                vehicle_type: data.vehicle_type || "",
                vehicle_model: data.vehicle_model || "",
                model_year: data.model_year || "",
                image: data.image || ""
            };
        } catch (error) {
            console.error('Error fetching vehicle details:', error);
            return {
                vehicles_name: "",
                vehicle_type: "",
                vehicle_model: "",
                model_year: "",
                image: ""
            };
        }
    }
    
    function getCustomerInfo() {
        return {
            fullName: document.getElementById('customerNameInput')?.value || "",
            email: document.getElementById('emailInput')?.value || "",
            phone: document.getElementById('contactNumberInput')?.value || "",
            countryCode: "",
            address1: "",
            address2: null,
            state: null,
            zip: "",
            specialRequests: null
        };
    }
    
    // Create unique key for deduplication (include rowIndex so multiple arrival/departure services are all sent)
    function createUniqueKey(item, type, rowIndex) {
        try {
            switch(type) {
                case 'entry_port':
                case 'exit_port':
                    const rowId = (item && (item.id != null && item.id !== '')) ? String(item.id) : ('idx-' + (rowIndex != null ? rowIndex : ''));
                    const portKey = [
                        rowId,
                        item.portName || item.port_name || '',
                        item.transferDestinationName || item.transfer_destination_name || '',
                        item.dateTime || item.bookingDate || '',
                        item.vehicleId || item.vehicle_id || '',
                        item.transferType || item.type || ''
                    ].join('|');
                    return portKey;
                default:
                    return null;
            }
        } catch (e) {
            console.error('Error creating unique key:', e);
            return null;
        }
    }

    /** Total tour adults stored as beds[].head_count (not per-room capacity). */
    function getHotelHeadCount(hotel) {
        const headerAdults = parseInt(document.getElementById('adultCountInput')?.value || document.getElementById('adults')?.value || '0', 10) || 0;
        if (headerAdults > 0) return headerAdults;
        const stored = parseInt(hotel?.headCount ?? hotel?.head_count ?? 0, 10);
        if (stored > 0) return stored;
        return parseInt(hotel?.adultsPerRoom, 10) || 2;
    }

    function getFocDiscountContext() {
        const discountType = document.getElementById('discountType')?.value || '';
        const f = (typeof getEnquiryProGroupFocFactors === 'function')
            ? getEnquiryProGroupFocFactors()
            : { isGroup: false, focSize: 0, discountOn: false, hotelFactor: 1, otherFactor: 1 };
        const active = discountType === 'foc' && f.isGroup && f.focSize > 0 && f.discountOn;
        return {
            active,
            focSize: active ? f.focSize : 0,
            hotelFactor: f.hotelFactor || 1,
            otherFactor: f.otherFactor || 1,
        };
    }

    function focCeilIfDecimal(value) {
        return (value % 1 === 0) ? value : Math.ceil(value);
    }

    function computeHotelServiceDiscountAmount(hotel) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || hotel.supplement || hotel.focServiceDiscount === false) return 0;
        if (!focServiceHasPositiveSell(hotel, 'hotel')) return 0;
        const nights = parseInt(String(hotel.nights || 0), 10) || 0;
        const sell = parseFloat(hotel.sell) || 0;
        const scaledTotalHotelSell = nights * sell * ctx.hotelFactor;
        const twinHotelPerPax = scaledTotalHotelSell / 2;
        return twinHotelPerPax > 0 ? twinHotelPerPax * ctx.focSize : 0;
    }

    function computeArrivalDepartureVehicleDiscountAmount(item) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || item.supplement || !item.focServiceDiscount) return 0;
        if (!focServiceHasPositiveSell(item, 'arrival')) return 0;
        const adults = parseInt(item.adultsQty, 10) || 0;
        const child = parseInt(item.childQty, 10) || 0;
        const paxCount = adults + child;
        const adultSell = parseFloat(item.adultSell) || 0;
        const typeVal = (item.transferType || item.type || '').toString().toLowerCase();
        const isShared = typeVal === 's' || typeVal === 'shared' || typeVal === 'sic';
        if (isShared) {
            return adultSell > 0 ? adultSell * ctx.otherFactor * ctx.focSize : 0;
        }
        const sell = parseFloat(item.adultSell || item.sell || item.cost) || 0;
        if (paxCount > 0 && sell > 0) {
            return (sell / paxCount) * ctx.otherFactor * ctx.focSize;
        }
        return sell > 0 ? focCeilIfDecimal(sell / 2) * ctx.otherFactor * ctx.focSize : 0;
    }

    function computeGuideServiceDiscountAmount(guide, focEnabled) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || !guide || guide.supplement) return 0;
        if (focEnabled === false) return 0;
        if (focEnabled !== true && !(guide.focServiceDiscount || guide.foc_service_discount)) return 0;
        const guideSell = parseFloat(guide.sell || 0);
        if (guideSell <= 0) return 0;
        const adultQ = parseInt(guide.adultsQty ?? guide.adults ?? 0, 10) || 0;
        const childQ = parseInt(guide.childQty ?? guide.child ?? 0, 10) || 0;
        const paxCountG = adultQ + childQ;
        if (paxCountG > 0) {
            return (guideSell / paxCountG) * ctx.otherFactor * ctx.focSize;
        }
        return focCeilIfDecimal(guideSell / 2) * ctx.otherFactor * ctx.focSize;
    }

    function computeTourTicketDiscountAmount(tour) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || tour.supplement || !tour.focServiceDiscount) return 0;
        if (!focServiceHasPositiveSell(tour, 'tour')) return 0;
        const adultsQty = parseInt(tour.adultsQty, 10) || 0;
        const childQty = parseInt(tour.childQty, 10) || 0;
        const infantQty = parseInt(tour.infantQty, 10) || 0;
        const adultSell = parseFloat(tour.adultSell) || 0;
        const childSell = parseFloat(tour.childSell) || 0;
        const infantSell = parseFloat(tour.infantSell) || 0;
        const ticketTotal = adultSell * adultsQty + childSell * childQty + infantSell * infantQty;
        const ticketPax = adultsQty + childQty + infantQty;
        if (ticketPax > 0 && ticketTotal > 0) {
            return (ticketTotal / ticketPax) * ctx.otherFactor * ctx.focSize;
        }
        if (adultSell > 0) {
            return adultSell * ctx.otherFactor * ctx.focSize;
        }
        return 0;
    }

    function computeTransferOptionsDiscountAmount(transfer, parentFocEnabled) {
        if (!transfer) return 0;
        const ctx = getFocDiscountContext();
        if (!ctx.active || transfer.supplement) return 0;
        const focOn = parentFocEnabled === true || !!(transfer.focServiceDiscount || transfer.foc_service_discount);
        if (!focOn) return 0;
        if (!focServiceHasPositiveSell(transfer, 'transfer')) return 0;
        const sell = parseFloat(transfer.sell ?? transfer.adultSell ?? transfer.cost ?? 0) || 0;
        const adults = parseInt(transfer.adults ?? transfer.adultsQty ?? 0, 10) || 0;
        const child = parseInt(transfer.child ?? transfer.childQty ?? 0, 10) || 0;
        const paxCount = adults + child;
        const typeVal = (transfer.type || transfer.transferType || '').toString().toLowerCase();
        const isShared = typeVal === 's' || typeVal === 'shared' || typeVal === 'sic';
        const isPrivate = typeVal === 'p' || typeVal === 'private';
        if (transfer.transportMode === 'local') {
            if (isShared) {
                return sell > 0 ? sell * ctx.otherFactor * ctx.focSize : 0;
            }
            if (isPrivate) {
                if (paxCount > 0 && sell > 0) {
                    return (sell / paxCount) * ctx.otherFactor * ctx.focSize;
                }
                return sell > 0 ? focCeilIfDecimal(sell / 2) * ctx.otherFactor * ctx.focSize : 0;
            }
        }
        if (isShared && sell > 0) {
            return sell * ctx.otherFactor * ctx.focSize;
        }
        if (paxCount > 0 && sell > 0) {
            return (sell / paxCount) * ctx.otherFactor * ctx.focSize;
        }
        return 0;
    }

    function computeMealDiscountAmount(meal) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || meal.supplement || !meal.focServiceDiscount) return 0;
        if (!focServiceHasPositiveSell(meal, 'meal')) return 0;
        const adultSell = parseFloat(meal.adultSell) || 0;
        return adultSell > 0 ? adultSell * ctx.otherFactor * ctx.focSize : 0;
    }

    function computeStandaloneGuideDiscountAmount(guide) {
        return computeGuideServiceDiscountAmount(guide, !!(guide.focServiceDiscount || guide.foc_service_discount));
    }

    function computeMiscDiscountAmount(misc) {
        const ctx = getFocDiscountContext();
        if (!ctx.active || misc.supplement || !(misc.focServiceDiscount || misc.foc_service_discount)) return 0;
        if (!focServiceHasPositiveSell(misc, 'misc')) return 0;
        const adultSell = parseFloat(misc.adultSell) || 0;
        return adultSell > 0 ? adultSell * ctx.otherFactor * ctx.focSize : 0;
    }

    /** FOC discount checkbox on for a service row (matches UI). */
    function enquiryProIsFocDiscountOn(entity) {
        if (!entity) return false;
        if (entity.focServiceDiscount === false || entity.foc_service_discount === false) return false;
        if (parseInt(entity.discount, 10) === 0) return false;
        if (parseInt(entity.discount, 10) === 1) return true;
        return !!(entity.focServiceDiscount || entity.foc_service_discount);
    }

    /** Order JSON: discount 1=on / 0=off and discount_amount (0 when off). */
    function enquiryProOrderDiscountPayload(entity, amountComputer) {
        const on = enquiryProIsFocDiscountOn(entity);
        const amount = on && typeof amountComputer === 'function' ? (parseFloat(amountComputer()) || 0) : 0;
        return { discount: on ? 1 : 0, discount_amount: amount };
    }

    /** Restaurant meal transfer for order JSON — prefer transferList (has FOC flag + prices). */
    function getMealLinkedTransferForOrder(meal) {
        if (!meal) return null;
        const fromList = meal.transferId
            ? (transferList.find(t => String(t.id) === String(meal.transferId)) || null)
            : null;
        const fromInfo = meal.transferInfo && Object.keys(meal.transferInfo).length > 0 ? meal.transferInfo : null;
        if (fromList) {
            return fromInfo ? Object.assign({}, fromInfo, fromList) : fromList;
        }
        return fromInfo;
    }

    /** True when GROUP tour has FOC + "Treat FOC pax as discount (free)" and footer type is FOC. */
    function isGroupFocDiscountActive() {
        const f = (typeof getEnquiryProGroupFocFactors === 'function')
            ? getEnquiryProGroupFocFactors()
            : { isGroup: false, focSize: 0, discountOn: false };
        const discountType = document.getElementById('discountType')?.value || '';
        return discountType === 'foc' && f.isGroup && f.focSize > 0 && f.discountOn;
    }

    /** True when saved/loaded JSON row has a positive sell (or per-pax sell) — not only discount_amount. */
    function servicePayloadHasPositivePrice(data, opts) {
        opts = opts || {};
        if (!data) return false;
        const num = (v) => {
            const n = parseFloat(v);
            return (!isNaN(n) && n > 0) ? n : 0;
        };
        const fromObj = (obj) => {
            if (!obj || typeof obj !== 'object') return false;
            const adultsQty = parseInt(obj.adults ?? obj.adultsQty ?? obj.adult ?? 0, 10) || 0;
            const childQty = parseInt(obj.children ?? obj.childQty ?? obj.child ?? 0, 10) || 0;
            const infantQty = parseInt(obj.infants ?? obj.infantQty ?? obj.infant ?? 0, 10) || 0;
            const adultSell = num(obj.adultSell ?? obj.adult_sell);
            const childSell = num(obj.childSell ?? obj.child_sell);
            const infantSell = num(obj.infantSell ?? obj.infant_sell);
            if (adultSell * adultsQty + childSell * childQty + infantSell * infantQty > 0) return true;
            if (adultSell > 0 || childSell > 0 || infantSell > 0) return true;
            if (num(obj.sell ?? obj.Sell ?? obj.totalPrice ?? obj.total_price ?? obj.price ?? obj.cost) > 0) return true;
            if (Array.isArray(obj.beds)) {
                for (const bed of obj.beds) {
                    if (num(bed?.sell ?? bed?.price) > 0) return true;
                }
            }
            if (Array.isArray(obj.rooms)) {
                for (const room of obj.rooms) {
                    const beds = room?.beds || [];
                    for (const bed of beds) {
                        if (num(bed?.sell ?? bed?.price) > 0) return true;
                    }
                }
            }
            return false;
        };
        if (fromObj(data)) return true;
        if (opts.nested && fromObj(opts.nested)) return true;
        if (data.transfer_options && fromObj(data.transfer_options)) return true;
        if (data.guide_options && fromObj(data.guide_options)) return true;
        return false;
    }

    /** Live in-memory service has sell > 0 (skip FOC discount when price is zero). */
    function focServiceHasPositiveSell(service, kind) {
        if (!service) return false;
        const num = (v) => {
            const n = parseFloat(v);
            return (!isNaN(n) && n > 0) ? n : 0;
        };
        if (kind === 'hotel') {
            return num(service.sell ?? service.roomPrice) > 0;
        }
        if (kind === 'tour') {
            const adultsQty = parseInt(service.adultsQty, 10) || 0;
            const childQty = parseInt(service.childQty, 10) || 0;
            const infantQty = parseInt(service.infantQty, 10) || 0;
            const ticketTotal = num(service.adultSell) * adultsQty + num(service.childSell) * childQty + num(service.infantSell) * infantQty;
            return ticketTotal > 0 || num(service.adultSell) > 0 || num(service.childSell) > 0;
        }
        if (kind === 'guide') {
            return num(service.sell) > 0;
        }
        if (kind === 'transfer') {
            return num(service.sell ?? service.adultSell ?? service.cost) > 0;
        }
        if (kind === 'meal' || kind === 'misc') {
            return num(service.adultSell) > 0;
        }
        if (kind === 'arrival') {
            return num(service.adultSell ?? service.sell) > 0;
        }
        return num(service.sell ?? service.adultSell) > 0;
    }

    /**
     * Restore FOC checkbox state when loading orders: honour saved flags / discount_amount,
     * otherwise default to included (same as create form modals).
     * discount_amount alone does not enable FOC when the service sell price is 0.
     */
    function resolveFocServiceDiscountFromPayload(data, opts) {
        opts = opts || {};
        if (!data) {
            return isGroupFocDiscountActive();
        }
        if (data.focServiceDiscount === false || data.foc_service_discount === false) {
            return false;
        }
        if (parseInt(data.discount, 10) === 0) {
            return false;
        }
        if (parseInt(data.discount, 10) === 1) {
            return servicePayloadHasPositivePrice(data, opts);
        }
        if (data.focServiceDiscount === true || data.foc_service_discount === true) {
            return servicePayloadHasPositivePrice(data, opts);
        }
        const disc = parseFloat(data.discount_amount ?? data.discountAmount ?? 0);
        if (!isNaN(disc) && disc > 0 && servicePayloadHasPositivePrice(data, opts)) {
            return true;
        }
        const nested = opts.nested;
        if (nested) {
            if (parseInt(nested.discount, 10) === 0) {
                /* explicit off on nested transfer/guide */
            } else if (parseInt(nested.discount, 10) === 1 && servicePayloadHasPositivePrice(nested, {})) {
                return true;
            } else {
                const nestedDisc = parseFloat(nested.discount_amount ?? nested.discountAmount ?? 0);
                if (!isNaN(nestedDisc) && nestedDisc > 0 && servicePayloadHasPositivePrice(nested, {})) {
                    return true;
                }
            }
        }
        return isGroupFocDiscountActive();
    }

    /** Fill guide pax from parent service or header when saved JSON has 0 (FOC per-pax math). */
    function applyGuidePaxFallback(guideEntry, parentAdults, parentChildren) {
        const headerAdults = parseInt(document.getElementById('adultCountInput')?.value || document.getElementById('adults')?.value || '0', 10) || 0;
        const headerChildren = parseInt(document.getElementById('childCountInput')?.value || document.getElementById('child')?.value || '0', 10) || 0;
        const pAdults = parseInt(parentAdults, 10) || headerAdults || 0;
        const pChildren = parseInt(parentChildren, 10) || headerChildren || 0;
        if (!(parseInt(guideEntry.adultsQty, 10) || parseInt(guideEntry.adults, 10))) {
            guideEntry.adultsQty = pAdults;
            guideEntry.adults = pAdults;
        }
        if (!(parseInt(guideEntry.childQty, 10) || parseInt(guideEntry.children, 10))) {
            guideEntry.childQty = pChildren;
            guideEntry.children = pChildren;
        }
    }

    /** Recompute footer FOC total after all services are loaded (edit mode). */
    function syncFocDiscountAfterOrdersLoaded() {
        if (typeof refreshGroupFocDiscountUiVisibility === 'function') {
            refreshGroupFocDiscountUiVisibility();
        }
        const discountType = document.getElementById('discountType');
        if (discountType && discountType.value === 'foc' && typeof handleDiscountTypeChange === 'function') {
            handleDiscountTypeChange();
        } else if (typeof applyMarkupDiscount === 'function') {
            applyMarkupDiscount();
        }
    }
    
    // Transform arrival/departure data to required format
    async function transformArrivalDepartureData() {
        const customerInfo = getCustomerInfo();
        const destination = document.getElementById('destinationSelect')?.value || 'Singapore';
        const dmcId = '{{ $dmc_id ?? "" }}';
        
        const entryPortData = [];
        const exitPortData = [];
        const seenKeys = {
            entry_port: new Set(),
            exit_port: new Set()
        };
        
        for (let i = 0; i < arrivalDepartureList.length; i++) {
            const item = arrivalDepartureList[i];
            if (item.type === 'Arrival') {
                // Extract date and time
                let bookingDate = normalizeDateToYYYYMMDD(item.dateTime);
                let entrytime = "03:00 AM";
                
                if (item.dateTime && item.dateTime.includes('T')) {
                    const parts = item.dateTime.split('T');
                    bookingDate = parts[0];
                    if (parts[1]) {
                        const timeParts = parts[1].split(':');
                        let hours = parseInt(timeParts[0]);
                        const minutes = timeParts[1] || '00';
                        const ampm = hours >= 12 ? 'PM' : 'AM';
                        hours = hours % 12 || 12;
                        entrytime = `${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
                    }
                }
                
                // Fetch vehicle details if vehicle_id exists
                const vehicleDetails = await fetchVehicleDetails(item.vehicleId, dmcId);
                
                // Check for duplicates (use row index so multiple arrival/departure services are all sent)
                const uniqueKey = createUniqueKey(item, 'entry_port', i);
                if (uniqueKey && seenKeys.entry_port.has(uniqueKey)) {
                    console.warn('Skipping duplicate entry_port (frontend):', uniqueKey);
                    continue; // Skip this duplicate
                }
                if (uniqueKey) {
                    seenKeys.entry_port.add(uniqueKey);
                }
                
                entryPortData.push({
                    id: item.id || `entry-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                    bookingDate: bookingDate,
                    date: bookingDate,
                    dateTime: item.dateTime || "",
                    pickupdate: bookingDate,
                    vehicle_id: item.vehicleId || '',
                    vehicleId: item.vehicleId || '',
                    image: vehicleDetails.image,
                    dmc_id: dmcId,
                    vehicles_name: vehicleDetails.vehicles_name,
                    vehicle_name: vehicleDetails.vehicles_name,
                    vehicleName: vehicleDetails.vehicles_name,
                    Mode: "dmc",
                    type: item.transferType || "Private",
                    transferType: item.transferType || "Private",
                    vehicle_type: vehicleDetails.vehicle_type || item.vehicleType || "",
                    vehicleType: vehicleDetails.vehicle_type || item.vehicleType || "",
                    vehicle_model: vehicleDetails.vehicle_model,
                    model_year: vehicleDetails.model_year,
                    seating_capacity: 0,
                    travel_type: "entry_port",
                    entrypickup: item.portName || "",
                    pickup: item.portName || "",
                    pickupLocation: item.portName || "",
                    port_name: item.portName || "",
                    portName: item.portName || "",
                    port_id: item.portId || "",
                    portId: item.portId || "",
                    entrydropoff: item.transferDestinationName || "",
                    dropoff: item.transferDestinationName || "",
                    dropoffLocation: item.transferDestinationName || "",
                    transfer_destination_name: item.transferDestinationName || "",
                    transferDestinationName: item.transferDestinationName || "",
                    transfer_destination_id: item.transferDestinationId || "",
                    transferDestinationId: item.transferDestinationId || "",
                    flightNumber: item.flightNo || item.flightNumber || "",
                    flight_number: item.flightNo || item.flightNumber || "",
                    PickupPlaceid: { lat: "", lng: "" },
                    DropoffPlaceid: { lat: "", lng: "" },
                    entrytime: entrytime,
                    time: entrytime,
                    adults: parseInt(item.adultsQty) || 0,
                    adultsQty: parseInt(item.adultsQty) || 0,
                    children: parseInt(item.childQty) || 0,
                    childQty: parseInt(item.childQty) || 0,
                    infants: parseInt(item.infantQty) || 0,
                    infantQty: parseInt(item.infantQty) || 0,
                    componentDayIndex: 0,
                    adultCost: parseFloat(item.adultCost) || 0,
                    childCost: parseFloat(item.childCost) || 0,
                    infantCost: parseFloat(item.infantCost) || 0,
                    adultSell: parseFloat(item.adultSell) || 0,
                    childSell: parseFloat(item.childSell) || 0,
                    infantSell: parseFloat(item.infantSell) || 0,
                    cost: parseFloat(item.adultCost || item.cost) || 0,
                    sell: parseFloat(item.adultSell || item.sell) || 0,
                    basePrice: parseFloat(item.adultSell || item.adultCost || item.cost) || 0,
                    base_price: parseFloat(item.adultSell || item.adultCost || item.cost) || 0,
                    totalPrice: (() => {
                        const _adultSell = parseFloat(item.adultSell) || 0;
                        const _childSell = parseFloat(item.childSell) || 0;
                        const _adultsQty = parseInt(item.adultsQty) || 0;
                        const _childQty = parseInt(item.childQty) || 0;
                        const _typeVal = (item.transferType || '').toString().toLowerCase();
                        const _isShared = _typeVal === 's' || _typeVal === 'shared' || _typeVal === 'sic';
                        if (_isShared) {
                            return (_adultSell * _adultsQty) + (_childSell * _childQty);
                        } else {
                            return _adultSell || _childSell || parseFloat(item.sell || item.cost || 0) || 0;
                        }
                    })(),
                    ...enquiryProOrderDiscountPayload(item, () => computeArrivalDepartureVehicleDiscountAmount(item)),
                    Tax: 0,
                    distance: 0,
                    Night_Start_Time: null,
                    Night_End_Time: null,
                    city: destination,
                    country: destination,
                    fullName: customerInfo.fullName,
                    email: customerInfo.email,
                    phone: customerInfo.phone,
                    countryCode: customerInfo.countryCode,
                    address1: customerInfo.address1,
                    address2: customerInfo.address2,
                    state: customerInfo.state,
                    zip: customerInfo.zip,
                    specialRequests: customerInfo.specialRequests,
                    userInfo: {
                        fullName: customerInfo.fullName,
                        email: customerInfo.email,
                        phone: customerInfo.phone,
                        countryCode: customerInfo.countryCode,
                        address1: customerInfo.address1,
                        address2: customerInfo.address2,
                        state: customerInfo.state,
                        zip: customerInfo.zip,
                        specialRequests: customerInfo.specialRequests
                    },
                    bookingType: "enquiry",
                    supplement: item.supplement || false,
                    booking_id: item.bookingId || item.booking_id || null,
                    bookingId: item.bookingId || item.booking_id || null
                });
                
                // Add guide_options if arrival has linked guide
                if (item.guideId) {
                    const linkedGuide = guideList.find(g => g.id === item.guideId);
                    if (linkedGuide) {
                        const lastEntry = entryPortData[entryPortData.length - 1];
                        lastEntry.guide_options = {
                            guide_required: true,
                            guideId: linkedGuide.guide_id || '',
                            guide_id: linkedGuide.guide_id || '',
                            guideName: linkedGuide.name || linkedGuide.guideName || '',
                            guide_name: linkedGuide.name || linkedGuide.guideName || '',
                            name: linkedGuide.name || linkedGuide.guideName || '',
                            hours: parseInt(linkedGuide.hours) || 12,
                            service_hours: parseInt(linkedGuide.hours) || 12,
                            serviceType: linkedGuide.serviceType || 'Full Day',
                            service_type: linkedGuide.serviceType || 'Full Day',
                            language: linkedGuide.language || linkedGuide.languages || '',
                            languages: linkedGuide.languages || linkedGuide.language || '',
                            cost: parseFloat(linkedGuide.cost) || 0,
                            Cost: parseFloat(linkedGuide.cost) || 0,
                            sell: parseFloat(linkedGuide.sell) || 0,
                            Sell: parseFloat(linkedGuide.sell) || 0,
                            tourActivity: `Arrival Guide - ${item.portName}`,
                            tour_activity: `Arrival Guide - ${item.portName}`,
                            Activity: `Arrival Guide - ${item.portName}`,
                            pickup_time: linkedGuide.time || '',
                            ...enquiryProOrderDiscountPayload(linkedGuide, () => computeGuideServiceDiscountAmount(linkedGuide, true))
                        };
                    }
                }
            } else if (item.type === 'Departure') {
                // Extract date and time
                let bookingDate = normalizeDateToYYYYMMDD(item.dateTime);
                let entrytime = "11:00 AM";
                
                if (item.dateTime && item.dateTime.includes('T')) {
                    const parts = item.dateTime.split('T');
                    bookingDate = parts[0];
                    if (parts[1]) {
                        const timeParts = parts[1].split(':');
                        let hours = parseInt(timeParts[0]);
                        const minutes = timeParts[1] || '00';
                        const ampm = hours >= 12 ? 'PM' : 'AM';
                        hours = hours % 12 || 12;
                        entrytime = `${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
                    }
                }
                
                // Fetch vehicle details if vehicle_id exists
                const vehicleDetails = await fetchVehicleDetails(item.vehicleId, dmcId);
                
                // Check for duplicates (use row index so multiple arrival/departure services are all sent)
                const uniqueKey = createUniqueKey(item, 'exit_port', i);
                if (uniqueKey && seenKeys.exit_port.has(uniqueKey)) {
                    console.warn('Skipping duplicate exit_port (frontend):', uniqueKey);
                    continue; // Skip this duplicate
                }
                if (uniqueKey) {
                    seenKeys.exit_port.add(uniqueKey);
                }
                
                exitPortData.push({
                    id: item.id || `exit-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                    fullName: customerInfo.fullName,
                    email: customerInfo.email,
                    phone: customerInfo.phone,
                    countryCode: customerInfo.countryCode,
                    address1: customerInfo.address1,
                    address2: customerInfo.address2,
                    state: customerInfo.state,
                    zip: customerInfo.zip,
                    specialRequests: customerInfo.specialRequests,
                    bookingDate: bookingDate,
                    date: bookingDate,
                    dateTime: item.dateTime || "",
                    exitpickupdate: bookingDate,
                    vehicle_id: item.vehicleId || '',
                    vehicleId: item.vehicleId || '',
                    vehicles_name: vehicleDetails.vehicles_name,
                    vehicle_name: vehicleDetails.vehicles_name,
                    vehicleName: vehicleDetails.vehicles_name,
                    dmc_id: String(dmcId),
                    Mode: "dmc",
                    type: item.transferType || "Shared",
                    transferType: item.transferType || "Shared",
                    image: vehicleDetails.image,
                    exitpickup: item.transferDestinationName || "",
                    pickup: item.transferDestinationName || "",
                    pickupLocation: item.transferDestinationName || "",
                    transfer_destination_name: item.transferDestinationName || "",
                    transferDestinationName: item.transferDestinationName || "",
                    transfer_destination_id: item.transferDestinationId || "",
                    transferDestinationId: item.transferDestinationId || "",
                    exitdropoff: item.portName || "",
                    dropoff: item.portName || "",
                    dropoffLocation: item.portName || "",
                    port_name: item.portName || "",
                    portName: item.portName || "",
                    port_id: item.portId || "",
                    portId: item.portId || "",
                    flightNumber: item.flightNo || item.flightNumber || "",
                    flight_number: item.flightNo || item.flightNumber || "",
                    entrytime: entrytime,
                    time: entrytime,
                    PickupPlaceid: null,
                    DropoffPlaceid: null,
                    adults: parseInt(item.adultsQty) || 0,
                    adultsQty: parseInt(item.adultsQty) || 0,
                    children: parseInt(item.childQty) || 0,
                    childQty: parseInt(item.childQty) || 0,
                    infants: parseInt(item.infantQty) || 0,
                    infantQty: parseInt(item.infantQty) || 0,
                    adultCost: parseFloat(item.adultCost) || 0,
                    childCost: parseFloat(item.childCost) || 0,
                    infantCost: parseFloat(item.infantCost) || 0,
                    adultSell: parseFloat(item.adultSell) || 0,
                    childSell: parseFloat(item.childSell) || 0,
                    infantSell: parseFloat(item.infantSell) || 0,
                    cost: parseFloat(item.adultCost || item.cost) || 0,
                    sell: parseFloat(item.adultSell || item.sell) || 0,
                    basePrice: parseFloat(item.adultSell || item.adultCost || item.cost) || 0,
                    base_price: parseFloat(item.adultSell || item.adultCost || item.cost) || 0,
                    totalPrice: (() => {
                        const _adultSell = parseFloat(item.adultSell) || 0;
                        const _childSell = parseFloat(item.childSell) || 0;
                        const _adultsQty = parseInt(item.adultsQty) || 0;
                        const _childQty = parseInt(item.childQty) || 0;
                        const _typeVal = (item.transferType || '').toString().toLowerCase();
                        const _isShared = _typeVal === 's' || _typeVal === 'shared' || _typeVal === 'sic';
                        if (_isShared) {
                            return (_adultSell * _adultsQty) + (_childSell * _childQty);
                        } else {
                            return _adultSell || _childSell || parseFloat(item.sell || item.cost || 0) || 0;
                        }
                    })(),
                    ...enquiryProOrderDiscountPayload(item, () => computeArrivalDepartureVehicleDiscountAmount(item)),
                    Tax: 0,
                    distance: 0,
                    Night_Start_Time: null,
                    Night_End_Time: null,
                    city: destination,
                    country: destination,
                    vehicle_type: vehicleDetails.vehicle_type || item.vehicleType || "",
                    vehicleType: vehicleDetails.vehicle_type || item.vehicleType || "",
                    vehicle_model: vehicleDetails.vehicle_model,
                    model_year: vehicleDetails.model_year,
                    seating_capacity: 0,
                    supplement: item.supplement || false,
                    booking_id: item.bookingId || item.booking_id || null,
                    bookingId: item.bookingId || item.booking_id || null
                });
                
                // Add guide_options if departure has linked guide
                if (item.guideId) {
                    const linkedGuide = guideList.find(g => g.id === item.guideId);
                    if (linkedGuide) {
                        const lastEntry = exitPortData[exitPortData.length - 1];
                        lastEntry.guide_options = {
                            guide_required: true,
                            guideId: linkedGuide.guide_id || '',
                            guide_id: linkedGuide.guide_id || '',
                            guideName: linkedGuide.name || linkedGuide.guideName || '',
                            guide_name: linkedGuide.name || linkedGuide.guideName || '',
                            name: linkedGuide.name || linkedGuide.guideName || '',
                            hours: parseInt(linkedGuide.hours) || 12,
                            service_hours: parseInt(linkedGuide.hours) || 12,
                            serviceType: linkedGuide.serviceType || 'Full Day',
                            service_type: linkedGuide.serviceType || 'Full Day',
                            language: linkedGuide.language || linkedGuide.languages || '',
                            languages: linkedGuide.languages || linkedGuide.language || '',
                            cost: parseFloat(linkedGuide.cost) || 0,
                            Cost: parseFloat(linkedGuide.cost) || 0,
                            sell: parseFloat(linkedGuide.sell) || 0,
                            Sell: parseFloat(linkedGuide.sell) || 0,
                            tourActivity: `Departure Guide - ${item.portName}`,
                            tour_activity: `Departure Guide - ${item.portName}`,
                            Activity: `Departure Guide - ${item.portName}`,
                            pickup_time: linkedGuide.time || '',
                            ...enquiryProOrderDiscountPayload(linkedGuide, () => computeGuideServiceDiscountAmount(linkedGuide, true))
                        };
                    }
                }
            }
        }
        
        return { entryPortData, exitPortData };
    }
    
    // Transform accommodation data to required hotel format
    function transformAccommodationData() {
        const customerInfo = getCustomerInfo();
        const dmcId = '{{ $dmc_id ?? "" }}';
        // Get tour_id from URL parameter, initial data, or hotel object
        const urlParams = new URLSearchParams(window.location.search);
        const tourIdFromUrl = urlParams.get('tour_id');
        const tourIdFromInitial = {{ isset($initialData['tour_id']) ? "'" . $initialData['tour_id'] . "'" : 'null' }};
        const defaultTourId = tourIdFromUrl || tourIdFromInitial || null;
        
        return accommodationList.map((hotel, hotelIdx) => {
            // Extract date and time from checkIn and checkOut
            let checkInDate = hotel.checkIn || '';
            let checkOutDate = hotel.checkOut || '';
            let checkInTime = "12:00:00";
            let checkOutTime = "20:15:00";
            
            // If checkIn/checkOut contain time (datetime-local format), extract them
            if (checkInDate && checkInDate.includes('T')) {
                const parts = checkInDate.split('T');
                checkInDate = parts[0];
                checkInTime = parts[1] ? parts[1].substring(0, 5) + ':00' : "12:00:00";
            }
            if (checkOutDate && checkOutDate.includes('T')) {
                const parts = checkOutDate.split('T');
                checkOutDate = parts[0];
                checkOutTime = parts[1] ? parts[1].substring(0, 5) + ':00' : "20:15:00";
            }
            
            // Calculate nights from checkIn/checkOut
            let nights = parseInt(hotel.nights) || 0;
            if (nights <= 0 && checkInDate && checkOutDate) {
                const inDate = new Date(checkInDate);
                const outDate = new Date(checkOutDate);
                if (!isNaN(inDate) && !isNaN(outDate) && outDate > inDate) {
                    nights = Math.ceil((outDate - inDate) / (1000 * 60 * 60 * 24));
                }
            }
            nights = Math.max(1, nights);
            
            // Calculate total price (room total = sell * rooms * nights; add child_with_bed and child_without_bed totals)
            const numberOfRooms = parseInt(hotel.rooms) || 1;
            const roomCost = parseFloat(hotel.cost || hotel.roomPrice) || 0;
            const roomSell = parseFloat(hotel.sell || hotel.roomPrice) || 0;
            const roomPrice = parseFloat(hotel.roomPrice) || 0;
            const totalCost = roomCost * numberOfRooms * nights;
            const roomTotal = roomSell * numberOfRooms * nights;
            const cwbPrice = hotel.hasCwb ? (parseFloat(hotel.cwbPrice) || 0) : 0;
            const cnbPrice = hotel.hasCnb ? (parseFloat(hotel.cnbPrice) || 0) : 0;
            let cwbChildren = parseInt(hotel.childWithBed) || 0;
            let cnbChildren = parseInt(hotel.childWithoutBed) || 0;
            // When both per-hotel child counts are 0, use header child value so payload reflects header
            const headerChildCount = parseInt(getHeaderValues().children) || 0;
            if (cwbChildren === 0 && cnbChildren === 0 && headerChildCount > 0) {
                cwbChildren = headerChildCount;
            }
            // For child_without_bed payload: use header when cnbChildren is 0 (same as child_with_bed) so both show children and total_cost
            const cnbChildrenForPayload = cnbChildren > 0 ? cnbChildren : (headerChildCount > 0 ? headerChildCount : 0);
            // Costs must match payload total_costs so totalPrice = roomTotal + extra_bed.total_cost + child_with_bed.total_cost + child_without_bed.total_cost
            const childWithBedTotalCost = (hotel.hasCwb && cwbChildren > 0) ? (cwbPrice * cwbChildren * nights) : 0;
            const childWithoutBedTotalCost = (hotel.hasCnb && cnbChildrenForPayload > 0) ? (cnbPrice * cnbChildrenForPayload * nights) : 0;
            // Extra bed: price * quantity * nights, add to total
            const extraBedPrice = hotel.hasExtraBed ? (parseFloat(hotel.extraBedPrice) || 0) : 0;
            const extraBedQuantity = parseInt(hotel.extraBed) || (hotel.hasExtraBed ? 1 : 0);
            const extraBedTotalCost = (hotel.hasExtraBed && extraBedQuantity > 0) ? (extraBedPrice * extraBedQuantity * nights) : 0;
            const totalPrice = roomTotal + extraBedTotalCost + childWithBedTotalCost + childWithoutBedTotalCost;
            
            // Structure rooms array with beds - matching working format exactly
            // Use actual database bed_id (this is what single tour package uses to match)
            const actualBedId = hotel.bedId || hotel.roomId || hotel.bedData?.bed_id || '';
            
            // Get raw bed type (without formatting) for matching with single tour package
            const rawBedType = hotel.bedTypeRaw || hotel.bedData?.room_type || hotel.bedData?.bed_type || hotel.bedType || "";
            // Remove formatting from bed type if it contains extra info (e.g., "Standard Bed - Max 2 guests" -> "Standard Bed")
            const cleanBedType = rawBedType.split(' - ')[0].split(' (')[0].trim();
            
            // Get meal plan in the format expected by single tour package (label format like "room only")
            // Use mealPlanLabel if available, otherwise convert mealPlan value to label format
            let mealPlanLabel = hotel.mealPlanLabel || hotel.mealPlan || "room only";
            // If it's a value format (e.g., "room_only"), convert to label format
            if (mealPlanLabel.includes('_')) {
                mealPlanLabel = mealPlanLabel.replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
            }
            
            // Get the actual database room_id
            const databaseRoomId = hotel.databaseRoomId || hotel.roomData?.room_id || hotel.roomData?.id || actualBedId || '';
            
            // Create bed object with clean structure
            const bedObject = {
                bed_id: String(actualBedId || ""),
                bed_type: cleanBedType,
                baby_cot: 0,
                head_count: getHotelHeadCount(hotel),
                max_occupancy: parseInt(hotel.maxOccupancy) || 3,
                price: roomSell,
                mealTypes: [mealPlanLabel],
                selectedMeals: {
                    meal_1: {
                        type: mealPlanLabel,
                        price: 0
                    }
                }
            };
            
            // Use database room_id for proper matching
            const rooms = [{
                room_id: parseInt(databaseRoomId) || databaseRoomId,
                room_type: hotel.roomType || "",
                number_of_rooms: numberOfRooms,
                beds: [bedObject]
            }];
            
            // Find linked transfer for this hotel
            const linkedTransfer = hotel.transferIds && hotel.transferIds.length > 0 
                ? transferList.find(t => hotel.transferIds.includes(t.id))
                : null;
            
            // Get hotel transfer data from accommodation object or linked transfer
            const hotelTransferData = hotel.hotelTransfer || (linkedTransfer ? {
                adults: linkedTransfer.adults,
                child: linkedTransfer.child,
                cost: linkedTransfer.cost,
                sell: linkedTransfer.sell,
                vehicleId: linkedTransfer.vehicleId,
                vehicleType: linkedTransfer.vehicleType,
                vehicleName: linkedTransfer.vehicleName,
                type: linkedTransfer.type,
                way: linkedTransfer.way
            } : null);
            
            // Build cleaner hotel data structure matching the correct format
            const hotelData = {
                // Customer info
                fullName: customerInfo.fullName || "",
                email: customerInfo.email || "",
                phone: customerInfo.phone || "",
                countryCode: customerInfo.countryCode || "",
                address1: customerInfo.address1 || "",
                address2: customerInfo.address2 || "",
                state: customerInfo.state || "",
                zip: customerInfo.zip || "",
                specialRequests: customerInfo.specialRequests || "",
                
                // Booking identifiers
                id: hotel.id || null,
                bookingType: "enquiry",
                bookingDate: [checkInDate, checkOutDate],
                
                // Hotel details (clean structure without room/bed/meal info)
                hotelDetails: {
                    hotel_id: hotel.hotel_unique_id || hotel.hotelId || "",
                    hotel_name: hotel.hotelName || "",
                    image: hotel.hotelImage || hotel.image || "",
                    location: hotel.destination || hotel.location || "Singapore",
                    checkInTime: checkInTime,
                    checkOutTime: checkOutTime,
                    cancellation_charge: null
                },
                
                // Pricing mode
                priceMode: "dmc",
                priceModeId: parseInt(dmcId) || null,
                
                // Rooms array (using 'rooms' instead of 'roomsArray')
                rooms: rooms,
                
                // Pricing
                totalPrice: totalPrice,
                price: totalPrice,
                ...enquiryProOrderDiscountPayload(hotel, () => computeHotelServiceDiscountAmount(hotel)),
                
                // Extra bed (enabled, price, quantity, total_cost = price * quantity * nights)
                extra_bed: {
                    enabled: !!(hotel.hasExtraBed),
                    price: parseFloat(hotel.extraBedPrice) || 0,
                    quantity: extraBedQuantity,
                    total_cost: extraBedTotalCost
                },
                // Child with bed / without bed (reference JSON format; children use header value when both 0; total_cost = price * children * nights)
                child_with_bed: {
                    enabled: !!(hotel.hasCwb),
                    price: parseFloat(hotel.cwbPrice) || 0,
                    children: cwbChildren,
                    total_cost: (parseFloat(hotel.cwbPrice) || 0) * cwbChildren * nights
                },
                child_without_bed: {
                    enabled: !!(hotel.hasCnb),
                    price: parseFloat(hotel.cnbPrice) || 0,
                    children: cnbChildrenForPayload,
                    total_cost: (parseFloat(hotel.cnbPrice) || 0) * cnbChildrenForPayload * nights
                },
                
                // Transfer options
                transfer_options: hotelTransferData ? (() => {
                    const type = hotelTransferData.type || linkedTransfer?.type || "P";
                    const way = hotelTransferData.way || linkedTransfer?.way || "one-way";
                    const baseCost = hotelTransferData.cost ?? linkedTransfer?.cost ?? parseFloat(linkedTransfer?.sell) ?? 0;
                    const baseSell = hotelTransferData.sell ?? linkedTransfer?.sell ?? hotelTransferData.cost ?? linkedTransfer?.cost ?? 0;
                    const basePrice = parseFloat(baseSell) || parseFloat(baseCost) || 0;
                    const adults = parseInt(hotelTransferData.adults ?? linkedTransfer?.adults ?? 0) || 0;
                    const child = parseInt(hotelTransferData.child ?? linkedTransfer?.child ?? 0) || 0;
                    const totalPax = Math.max(1, adults + child);
                    const isShared = (String(type).toLowerCase() === 's' || String(type).toLowerCase() === 'shared' || String(type).toLowerCase() === 'sic');
                    const totalPrice = isShared ? (basePrice * totalPax) : basePrice;
                    return {
                        transfer_required: true,
                        type: type,
                        way: way,
                        vehicle_id: hotelTransferData.vehicleId || linkedTransfer?.vehicleId || "",
                        vehicle_details: (hotelTransferData.vehicleId || linkedTransfer?.vehicleId) ? {
                            vehicle_id: hotelTransferData.vehicleId || linkedTransfer?.vehicleId || "",
                            vehicle_name: hotelTransferData.vehicleName || linkedTransfer?.vehicleName || "",
                            vehicle_type: hotelTransferData.vehicleType || linkedTransfer?.vehicleType || "",
                            seating_capacity: linkedTransfer?.seatingCapacity || linkedTransfer?.capacity || "",
                            private_price: linkedTransfer?.privatePrice || "0.00",
                            shared_price: linkedTransfer?.sharedPrice || "0.00"
                        } : null,
                        adults: adults,
                        child: child,
                        cost: basePrice,
                        sell: basePrice,
                        totalPrice: totalPrice,
                        destination_id: linkedTransfer?.destinationId || "",
                        pickup_location_name: linkedTransfer?.pickup || "",
                        destination_name: linkedTransfer?.dropoff || ""
                    };
                })() : null,
                
                // Tour ID
                tour_id: hotel.tour_id || defaultTourId || null,
                
                // Essential top-level fields for controller compatibility
                // These are needed for unique key generation and service_date extraction
                checkIn: checkInDate,
                checkOut: checkOutDate,
                hotel_unique_id: hotel.hotel_unique_id || hotel.hotelId || "",
                hotelName: hotel.hotelName || "",
                roomType: hotel.roomType || "",
                bedType: cleanBedType,
                destination: hotel.destination || hotel.location || "",
                booking_id: hotel.bookingId || hotel.booking_id || null,
                bookingId: hotel.bookingId || hotel.booking_id || null
            };
            
            return hotelData;
        });
    }
    
    // Transform tour/attraction data to required format
    function transformTourData() {
        const customerInfo = getCustomerInfo();
        const dmcId = '{{ $dmc_id ?? "" }}';
        
        return tourList.map(tour => {
            const tourData = {
                fullName: customerInfo.fullName,
                email: customerInfo.email,
                phone: customerInfo.phone,
                countryCode: customerInfo.countryCode,
                address1: customerInfo.address1,
                address2: customerInfo.address2,
                state: customerInfo.state,
                zip: customerInfo.zip,
                specialRequests: customerInfo.specialRequests,
                id: tour.id || null,
                bookingDate: normalizeDateToYYYYMMDD(tour.dateTime),
                date: normalizeDateToYYYYMMDD(tour.dateTime),
                dateTime: tour.dateTime || "",
                startTime: tour.startTime || "",
                endTime: tour.endTime || "",
                visitTime: tour.visitTime || "16:00",
                time: tour.visitTime || "16:00",
                adultCount: parseInt(tour.adultsQty) || 0,
                adultsQty: parseInt(tour.adultsQty) || 0,
                adults: parseInt(tour.adultsQty) || 0,
                childCount: parseInt(tour.childQty) || 0,
                childQty: parseInt(tour.childQty) || 0,
                children: parseInt(tour.childQty) || 0,
                infantQty: parseInt(tour.infantQty) || 0,
                infants: parseInt(tour.infantQty) || 0,
                seniorCount: 0,
                AttractionId: tour.attractionId || 0,
                AttractionID: tour.attractionId || 0,
                attraction_id: tour.attractionId || 0,
