                    child_price: parseFloat(tour.childCost) || 0,
                    child_cost: parseFloat(tour.childCost) || 0,
                    child_sell: parseFloat(tour.childSell) || 0,
                    infant_cost: parseFloat(tour.infantCost) || 0,
