                ...enquiryProOrderDiscountPayload(tour, () => computeTourTicketDiscountAmount(tour))
            };
            
            // Add transfer_options if attraction has linked transfer
            if (tour.transferId) {
                const linkedTransfer = transferList.find(t => t.id === tour.transferId);
                if (linkedTransfer) {
