                        cost: basePrice,
                        sell: basePrice,
                        totalPrice: transferTotalPrice,
                        adults: adults,
                        child: child
                    };
            }
            
            // Add guide_options if meal has linked guide
            if (meal.guideId) {
                const linkedGuide = guideList.find(g => g.id === meal.guideId);
                if (linkedGuide) {
                    mealData.guide_options = {
